    progress_update_id uuid,
    construction_stage_id uuid,
    storage_path text NOT NULL,
    file_name text NOT NULL,
    content_type text DEFAULT 'image/jpeg'::text NOT NULL,
    byte_size bigint,
    caption text,
    taken_at timestamp with time zone,
    is_customer_visible boolean DEFAULT true NOT NULL,
    uploaded_by_type text DEFAULT 'builder_user'::text NOT NULL,
    uploaded_by_builder_user_id uuid,
    uploaded_by_user_id uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_construction_photographs_byte_size_check CHECK (((byte_size IS NULL) OR (byte_size > 0))),
    CONSTRAINT builder_construction_photographs_content_type_check CHECK ((content_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text, 'image/heic'::text]))),
    CONSTRAINT builder_construction_photographs_file_name_check CHECK ((length(btrim(file_name)) > 0)),
    CONSTRAINT builder_construction_photographs_storage_path_check CHECK ((length(btrim(storage_path)) > 0)),
    CONSTRAINT builder_construction_photographs_uploaded_by_type_check CHECK ((uploaded_by_type = ANY (ARRAY['builder_user'::text, 'command_user'::text, 'service_role'::text, 'system'::text])))
);


