    CONSTRAINT builder_document_versions_byte_size_check CHECK (((byte_size IS NULL) OR (byte_size > 0))),
    CONSTRAINT builder_document_versions_file_name_check CHECK ((length(btrim(file_name)) > 0)),
    CONSTRAINT builder_document_versions_lifecycle_check CHECK ((lifecycle_status = ANY (ARRAY['upload_pending'::text, 'quarantined'::text, 'scanning'::text, 'available'::text, 'superseded'::text, 'rejected'::text]))),
    CONSTRAINT builder_document_versions_scan_check CHECK ((malware_scan_status = ANY (ARRAY['pending'::text, 'scanning'::text, 'clean'::text, 'infected'::text, 'error'::text]))),
    CONSTRAINT builder_document_versions_storage_path_check CHECK ((length(btrim(storage_path)) > 0)),
    CONSTRAINT builder_document_versions_uploaded_by_type_check CHECK ((uploaded_by_type = ANY (ARRAY['builder_user'::text, 'command_user'::text, 'service_role'::text, 'system'::text]))),
    CONSTRAINT builder_document_versions_version_number_check CHECK ((version_number > 0))
);


--
-- Name: COLUMN builder_document_versions.lifecycle_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_document_versions.lifecycle_status IS 'Quarantine lifecycle. Only `available` is downloadable, and a CHECK constraint requires malware_scan_status = clean for that state.';


--
-- Name: builder_add_document_version(uuid, text, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_add_document_version(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _document_id uuid, _payload jsonb, _reason text DEFAULT NULL::text) RETURNS public.builder_document_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE d public.builder_documents; v_row public.builder_document_versions; v_next integer;
BEGIN
  IF NULLIF(btrim(COALESCE(_payload->>'storage_path','')), '') IS NULL
     OR NULLIF(btrim(COALESCE(_payload->>'file_name','')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_FILE_REQUIRED';
  END IF;
  SELECT * INTO d FROM public.builder_documents WHERE id = _document_id FOR UPDATE;
  IF d.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_NOT_FOUND';
  END IF;

  SELECT COALESCE(max(version_number), 0) + 1 INTO v_next
  FROM public.builder_document_versions WHERE document_id = _document_id;

  INSERT INTO public.builder_document_versions(document_id, version_number, storage_path,
    file_name, content_type, byte_size, checksum, change_note,
    uploaded_by_type, uploaded_by_builder_user_id, uploaded_by_user_id,
    lifecycle_status, malware_scan_status)
  VALUES (_document_id, v_next, _payload->>'storage_path', _payload->>'file_name',
    COALESCE(_payload->>'content_type','application/pdf'),
    NULLIF(_payload->>'byte_size','')::bigint, _payload->>'checksum', _payload->>'change_note',
    _actor_type, _actor_builder_user_id, _actor_user_id,
    'upload_pending', 'pending')
  RETURNING * INTO v_row;

  -- Deliberately NOT setting current_version_id. An unscanned version is not
  -- the document.

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_document_version_added',
    'document_version', v_row.id, d.organisation_id, _actor_builder_user_id,
    NULL, jsonb_build_object('version_number', v_row.version_number,
                             'file_name', v_row.file_name,
                             'lifecycle_status', v_row.lifecycle_status),
    _reason, jsonb_build_object('document_id', _document_id));
  RETURN v_row;
END $$;


--
-- Name: FUNCTION builder_add_document_version(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _document_id uuid, _payload jsonb, _reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_add_document_version(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _document_id uuid, _payload jsonb, _reason text) IS 'Creates an upload_pending version. Promotion to current happens only in complete_builder_document_processing, after a clean scan.';


--
-- Name: builder_construction_progress_updates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_construction_progress_updates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    construction_stage_id uuid,
    title text NOT NULL,
    body text,
    percent_complete numeric(5,2),
    update_date date DEFAULT CURRENT_DATE NOT NULL,
    is_customer_visible boolean DEFAULT true NOT NULL,
    created_by_type text DEFAULT 'builder_user'::text NOT NULL,
    created_by_builder_user_id uuid,
    created_by_user_id uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_construction_progress_updates_created_by_type_check CHECK ((created_by_type = ANY (ARRAY['builder_user'::text, 'command_user'::text, 'service_role'::text, 'system'::text]))),
    CONSTRAINT builder_construction_progress_updates_percent_complete_check CHECK (((percent_complete IS NULL) OR ((percent_complete >= (0)::numeric) AND (percent_complete <= (100)::numeric)))),
    CONSTRAINT builder_construction_progress_updates_title_check CHECK ((length(btrim(title)) > 0))
);


--
-- Name: builder_add_progress_update(uuid, text, uuid, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_add_progress_update(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _construction_case_id uuid, _construction_stage_id uuid, _payload jsonb, _reason text DEFAULT NULL::text) RETURNS public.builder_construction_progress_updates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.builder_construction_progress_updates; v_org uuid; v_txn uuid;
BEGIN
  IF NULLIF(btrim(COALESCE(_payload->>'title','')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROGRESS_TITLE_REQUIRED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
  END IF;

  INSERT INTO public.builder_construction_progress_updates(construction_case_id,
    construction_stage_id, title, body, percent_complete, update_date, is_customer_visible,
    created_by_type, created_by_builder_user_id, created_by_user_id)
  VALUES (_construction_case_id, _construction_stage_id, _payload->>'title', _payload->>'body',
    (_payload->>'percent_complete')::numeric,
    COALESCE((_payload->>'update_date')::date, CURRENT_DATE),
    COALESCE((_payload->>'is_customer_visible')::boolean, true),
    _actor_type, _actor_builder_user_id, _actor_user_id)
  RETURNING * INTO v_row;

  -- The case's headline percentage follows the latest update that carries one.
  IF v_row.percent_complete IS NOT NULL THEN
    UPDATE public.builder_construction_cases SET percent_complete = v_row.percent_complete
    WHERE id = _construction_case_id;
  END IF;

  SELECT transaction_id INTO v_txn FROM public.builder_construction_cases
  WHERE id = _construction_case_id;
  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = v_txn;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_progress_update_added',
    'progress_update', v_row.id, v_org, _actor_builder_user_id,
    NULL, jsonb_build_object('title', v_row.title, 'percent_complete', v_row.percent_complete),
    _reason, jsonb_build_object('construction_case_id', _construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_admin_delete_membership(uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_delete_membership(_actor_user_id uuid, _actor_type text, _membership_id uuid, _expected_version bigint, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_membership public.builder_organisation_memberships;
  v_reason text := NULLIF(btrim(_reason), '');
  v_permissions_removed bigint;
  v_access_removed bigint;
  v_next_primary uuid;
  v_sessions_revoked integer := 0;
BEGIN
  IF v_reason IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_REASON_REQUIRED';
  END IF;

  SELECT * INTO v_membership FROM public.builder_organisation_memberships
  WHERE id = _membership_id
  FOR UPDATE;

  IF v_membership.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_MEMBERSHIP_NOT_FOUND';
  END IF;

  IF _expected_version IS NULL OR v_membership.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_membership.row_version);
  END IF;

  -- Evidence first: the membership row is about to stop existing, so the audit
  -- record has to carry everything worth knowing about it.
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_membership_removed',
    'membership', v_membership.id,
    v_membership.organisation_id, v_membership.builder_user_id,
    jsonb_build_object(
      'membership_id', v_membership.id,
      'builder_user_id', v_membership.builder_user_id,
      'organisation_id', v_membership.organisation_id,
      'membership_role', v_membership.membership_role,
      'is_primary', v_membership.is_primary,
      'status', v_membership.status,
      'revoked_at', v_membership.revoked_at,
      'revoked_reason', v_membership.revoked_reason),
    NULL, v_reason,
    jsonb_build_object('removal', 'permanent', 'removed_at', now()));

  -- Category A: access rows that exist only because this membership does.
  DELETE FROM public.builder_membership_permissions WHERE membership_id = _membership_id;
  GET DIAGNOSTICS v_permissions_removed = ROW_COUNT;

  DELETE FROM public.builder_project_access
  WHERE builder_user_id = v_membership.builder_user_id
    AND organisation_id = v_membership.organisation_id;
  GET DIAGNOSTICS v_access_removed = ROW_COUNT;

  DELETE FROM public.builder_organisation_memberships WHERE id = _membership_id;

  -- The primary flag moves to another live membership when one exists;
  -- otherwise the user simply has no primary organisation.
  IF v_membership.is_primary THEN
    SELECT id INTO v_next_primary FROM public.builder_organisation_memberships
    WHERE builder_user_id = v_membership.builder_user_id
      AND revoked_at IS NULL AND status = 'active'
    ORDER BY created_at
    LIMIT 1;

    IF v_next_primary IS NOT NULL THEN
      UPDATE public.builder_organisation_memberships
      SET is_primary = true WHERE id = v_next_primary;
    END IF;
  END IF;

  -- Losing the last membership that confers access must end the sessions it
  -- was carrying. The membership trigger only fires on UPDATE.
  IF NOT EXISTS (SELECT 1 FROM public.builder_accessible_organisations(v_membership.builder_user_id)) THEN
    v_sessions_revoked := public.builder_revoke_user_sessions(
      v_membership.builder_user_id, 'membership_removed');
  END IF;

  RETURN jsonb_build_object(
    'removed', true,
    'id', _membership_id,
    'membership_id', _membership_id,
    'builder_user_id', v_membership.builder_user_id,
    'organisation_id', v_membership.organisation_id,
    'permission_overrides_removed', v_permissions_removed,
    'project_access_removed', v_access_removed,
    'promoted_primary_membership_id', v_next_primary,
    'sessions_revoked', v_sessions_revoked);
END $$;


--
-- Name: FUNCTION builder_admin_delete_membership(_actor_user_id uuid, _actor_type text, _membership_id uuid, _expected_version bigint, _reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_admin_delete_membership(_actor_user_id uuid, _actor_type text, _membership_id uuid, _expected_version bigint, _reason text) IS 'Permanently removes a Builder membership in one transaction, whatever its status. Deletes the access rows that exist only because of it, hands the primary flag on, and ends the user''s sessions when it was their last access. The audit snapshot written first is the retained evidence.';


--
-- Name: builder_admin_delete_organisation(uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_delete_organisation(_actor_user_id uuid, _actor_type text, _organisation_id uuid, _expected_version bigint, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org public.builder_organisations;
  v_blockers text[] := ARRAY[]::text[];
  v_reason text := NULLIF(btrim(_reason), '');
  v_count bigint;
  v_membership_ids uuid[];
  v_user_ids uuid[];
  v_user_id uuid;
  v_sessions_revoked integer := 0;
BEGIN
  IF v_reason IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_REASON_REQUIRED';
  END IF;

  SELECT * INTO v_org FROM public.builder_organisations
  WHERE id = _organisation_id
  FOR UPDATE;

  IF v_org.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_NOT_FOUND';
  END IF;

  IF _expected_version IS NULL OR v_org.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_org.row_version);
  END IF;

  -- ---- Category B.
  SELECT count(*) INTO v_count FROM public.builder_projects
    WHERE builder_organisation_id = _organisation_id
       OR developer_organisation_id = _organisation_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('projects (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_reservations
    WHERE organisation_id = _organisation_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('reservations (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_transactions
    WHERE organisation_id = _organisation_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('transactions (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_unit_holds
    WHERE organisation_id = _organisation_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('unit holds (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_tasks
    WHERE organisation_id = _organisation_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('tasks (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_documents
    WHERE organisation_id = _organisation_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('documents (%s)', v_count)); END IF;

  -- A conversation that carries messages is business correspondence. An empty
  -- one is a shell and is removed as Category A below.
  SELECT count(*) INTO v_count FROM public.builder_conversations
    WHERE organisation_id = _organisation_id AND message_count > 0;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('conversations with messages (%s)', v_count)); END IF;

  IF array_length(v_blockers, 1) > 0 THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_HAS_DEPENDENTS',
      DETAIL = format('dependents=%s', array_to_string(v_blockers, ', '));
  END IF;

  SELECT coalesce(array_agg(id), ARRAY[]::uuid[]),
         coalesce(array_agg(DISTINCT builder_user_id), ARRAY[]::uuid[])
  INTO v_membership_ids, v_user_ids
  FROM public.builder_organisation_memberships
  WHERE organisation_id = _organisation_id;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_organisation_removed',
    'organisation', v_org.id, NULL, NULL,
    jsonb_build_object(
      'organisation_id', v_org.id,
      'legal_name', v_org.legal_name,
      'trading_name', v_org.trading_name,
      'abn', v_org.abn,
      'acn', v_org.acn,
      'org_type', v_org.org_type,
      'status', v_org.status,
      'membership_ids', to_jsonb(v_membership_ids),
      'affected_user_ids', to_jsonb(v_user_ids)),
    NULL, v_reason,
    jsonb_build_object('removal', 'permanent', 'removed_at', now()));

  -- ---- Category A.
  DELETE FROM public.builder_membership_permissions
  WHERE membership_id IN (
    SELECT id FROM public.builder_organisation_memberships WHERE organisation_id = _organisation_id);
  DELETE FROM public.builder_organisation_memberships WHERE organisation_id = _organisation_id;
  DELETE FROM public.builder_project_access WHERE organisation_id = _organisation_id;
  DELETE FROM public.builder_notifications WHERE organisation_id = _organisation_id;
  DELETE FROM public.builder_conversation_participants
  WHERE conversation_id IN (
    SELECT id FROM public.builder_conversations WHERE organisation_id = _organisation_id);
  DELETE FROM public.builder_conversations WHERE organisation_id = _organisation_id;
  DELETE FROM public.builder_organisation_settings WHERE organisation_id = _organisation_id;

  DELETE FROM public.builder_organisations WHERE id = _organisation_id;

  -- The users survive. Anyone who now holds no access loses their sessions.
  FOREACH v_user_id IN ARRAY v_user_ids LOOP
    IF NOT EXISTS (SELECT 1 FROM public.builder_accessible_organisations(v_user_id)) THEN
      v_sessions_revoked := v_sessions_revoked
        + public.builder_revoke_user_sessions(v_user_id, 'organisation_removed');
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'removed', true,
    'id', _organisation_id,
    'organisation_id', _organisation_id,
    'memberships_removed', coalesce(array_length(v_membership_ids, 1), 0),
    'affected_user_count', coalesce(array_length(v_user_ids, 1), 0),
    'sessions_revoked', v_sessions_revoked);
END $$;


--
-- Name: FUNCTION builder_admin_delete_organisation(_actor_user_id uuid, _actor_type text, _organisation_id uuid, _expected_version bigint, _reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_admin_delete_organisation(_actor_user_id uuid, _actor_type text, _organisation_id uuid, _expected_version bigint, _reason text) IS 'Permanently removes a Builder organisation in one transaction. Refuses with BUILDER_HAS_DEPENDENTS when it holds business work; otherwise removes its access records with it. Never deletes a user — a user left without access keeps their account and loses their sessions.';


--
-- Name: builder_admin_delete_user(uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_delete_user(_actor_user_id uuid, _actor_type text, _builder_user_id uuid, _expected_version bigint, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user public.builder_portal_users;
  v_blockers text[] := ARRAY[]::text[];
  v_reason text := NULLIF(btrim(_reason), '');
  v_count bigint;
  v_membership_ids uuid[];
  v_organisation_ids uuid[];
  v_sessions_revoked integer := 0;
BEGIN
  IF v_reason IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_REASON_REQUIRED';
  END IF;

  SELECT * INTO v_user FROM public.builder_portal_users
  WHERE id = _builder_user_id
  FOR UPDATE;

  IF v_user.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;

  IF _expected_version IS NULL OR v_user.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_user.row_version);
  END IF;

  -- ---- Category B. Business work this account produced. Counted under the
  -- ---- lock taken above, so nothing can be created between check and delete.
  SELECT count(*) INTO v_count FROM public.builder_document_versions
    WHERE uploaded_by_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('uploaded documents (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_messages
    WHERE author_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('authored messages (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_reservations
    WHERE reserved_by_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('reservations (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_unit_holds
    WHERE held_by_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('unit holds (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_tasks
    WHERE created_by_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('tasks (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_task_assignments
    WHERE builder_user_id = _builder_user_id
       OR assigned_by_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('task assignments (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_construction_progress_updates
    WHERE created_by_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('construction progress updates (%s)', v_count)); END IF;

  SELECT count(*) INTO v_count FROM public.builder_construction_photographs
    WHERE uploaded_by_builder_user_id = _builder_user_id;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('construction photographs (%s)', v_count)); END IF;

  SELECT (
      (SELECT count(*) FROM public.builder_construction_status_history WHERE changed_by_builder_user_id = _builder_user_id)
    + (SELECT count(*) FROM public.builder_construction_date_history   WHERE changed_by_builder_user_id = _builder_user_id)
    + (SELECT count(*) FROM public.builder_delivery_status_history     WHERE changed_by_builder_user_id = _builder_user_id)
    + (SELECT count(*) FROM public.builder_project_status_history      WHERE changed_by_builder_user_id = _builder_user_id)
    + (SELECT count(*) FROM public.builder_reservation_status_history  WHERE changed_by_builder_user_id = _builder_user_id)
    + (SELECT count(*) FROM public.builder_transaction_status_history  WHERE changed_by_builder_user_id = _builder_user_id)
    + (SELECT count(*) FROM public.builder_unit_status_history         WHERE changed_by_builder_user_id = _builder_user_id)
  ) INTO v_count;
  IF v_count > 0 THEN v_blockers := array_append(v_blockers, format('status history entries (%s)', v_count)); END IF;

  IF array_length(v_blockers, 1) > 0 THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_HAS_DEPENDENTS',
      DETAIL = format('dependents=%s', array_to_string(v_blockers, ', '));
  END IF;

  -- Memberships are named in the audit snapshot, so they are collected before
  -- they are deleted.
  SELECT coalesce(array_agg(id), ARRAY[]::uuid[]),
         coalesce(array_agg(DISTINCT organisation_id), ARRAY[]::uuid[])
  INTO v_membership_ids, v_organisation_ids
  FROM public.builder_organisation_memberships
  WHERE builder_user_id = _builder_user_id;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_user_removed',
    'portal_user', v_user.id, NULL, NULL,
    jsonb_build_object(
      'builder_user_id', v_user.id,
      'email', v_user.email,
      'name', v_user.name,
      'job_title', v_user.job_title,
      'status', v_user.status,
      'invited_at', v_user.invited_at,
      'invite_accepted_at', v_user.invite_accepted_at,
      'membership_ids', to_jsonb(v_membership_ids),
      'organisation_ids', to_jsonb(v_organisation_ids)),
    NULL, v_reason,
    jsonb_build_object('removal', 'permanent', 'removed_at', now()));

  -- End the sessions before the rows go, so the count is meaningful.
  v_sessions_revoked := public.builder_revoke_user_sessions(_builder_user_id, 'user_removed');

  -- ---- Category A. Access and account rows, deleted explicitly so the scope
  -- ---- of a removal is visible here rather than implied by a cascade.
  DELETE FROM public.builder_membership_permissions
  WHERE membership_id IN (
    SELECT id FROM public.builder_organisation_memberships WHERE builder_user_id = _builder_user_id);
  DELETE FROM public.builder_organisation_memberships WHERE builder_user_id = _builder_user_id;
  DELETE FROM public.builder_project_access WHERE builder_user_id = _builder_user_id;
  DELETE FROM public.builder_document_grants WHERE builder_user_id = _builder_user_id;
  DELETE FROM public.builder_conversation_participants WHERE builder_user_id = _builder_user_id;
  DELETE FROM public.builder_notifications WHERE builder_user_id = _builder_user_id;
  DELETE FROM public.builder_onboarding_steps WHERE builder_user_id = _builder_user_id;
  DELETE FROM public.builder_user_preferences WHERE builder_user_id = _builder_user_id;
  DELETE FROM public.builder_portal_sessions WHERE builder_user_id = _builder_user_id;

  -- Invitation and reset state are columns on this row and go with it.
  DELETE FROM public.builder_portal_users WHERE id = _builder_user_id;

  RETURN jsonb_build_object(
    'removed', true,
    'id', _builder_user_id,
    'builder_user_id', _builder_user_id,
    'memberships_removed', coalesce(array_length(v_membership_ids, 1), 0),
    'sessions_revoked', v_sessions_revoked);
END $$;


--
-- Name: FUNCTION builder_admin_delete_user(_actor_user_id uuid, _actor_type text, _builder_user_id uuid, _expected_version bigint, _reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_admin_delete_user(_actor_user_id uuid, _actor_type text, _builder_user_id uuid, _expected_version bigint, _reason text) IS 'Permanently removes a Builder portal user in one transaction. Refuses with BUILDER_HAS_DEPENDENTS when the account produced business work; otherwise removes its access and account records with it. Never deletes an organisation.';


--
-- Name: builder_organisation_memberships; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_organisation_memberships (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    builder_user_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    membership_role text NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_until timestamp with time zone,
    revoked_at timestamp with time zone,
    revoked_reason text,
    granted_by uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_memberships_revocation_stamp CHECK (((status <> 'revoked'::text) OR (revoked_at IS NOT NULL))),
    CONSTRAINT builder_memberships_validity_order CHECK (((valid_until IS NULL) OR (valid_until > valid_from))),
    CONSTRAINT builder_organisation_memberships_membership_role_check CHECK ((membership_role = ANY (ARRAY['owner'::text, 'administrator'::text, 'manager'::text, 'member'::text, 'read_only'::text]))),
    CONSTRAINT builder_organisation_memberships_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'revoked'::text])))
);


--
-- Name: TABLE builder_organisation_memberships; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_organisation_memberships IS 'Binds a Builder Portal user to an organisation. No active membership means no portal access. A developer and a builder may be separate organisations; a user may hold memberships in more than one.';


--
-- Name: builder_admin_revoke_membership(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_revoke_membership(_actor_user_id uuid, _actor_type text, _membership_id uuid, _reason text) RETURNS public.builder_organisation_memberships
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_organisation_memberships; v_row public.builder_organisation_memberships;
BEGIN
  SELECT * INTO v_existing FROM public.builder_organisation_memberships
  WHERE id = _membership_id AND revoked_at IS NULL
  FOR UPDATE;

  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_MEMBERSHIP_NOT_FOUND_OR_REVOKED';
  END IF;

  UPDATE public.builder_organisation_memberships
  SET status = 'revoked', revoked_at = now(),
      revoked_reason = COALESCE(NULLIF(btrim(_reason), ''), 'revoked by administrator')
  WHERE id = _membership_id
  RETURNING * INTO v_row;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_membership_revoked',
    'membership', v_row.id, v_row.organisation_id, v_row.builder_user_id,
    jsonb_build_object('membership_role', v_existing.membership_role, 'status', v_existing.status),
    jsonb_build_object('status', v_row.status, 'revoked_at', v_row.revoked_at),
    v_row.revoked_reason, '{}'::jsonb);

  RETURN v_row;
END $$;


--
-- Name: builder_tri_state_permissions_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_tri_state_permissions_valid(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_typeof(value) = 'object'
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_each(value) area
      WHERE jsonb_typeof(area.value) <> 'object'
         OR EXISTS (
           SELECT 1 FROM jsonb_each_text(area.value) decision
           WHERE decision.key NOT IN ('view','edit','delete')
              OR decision.value NOT IN ('inherit','allow','deny')
         )
    );
$$;


--
-- Name: builder_project_access; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_project_access (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    builder_user_id uuid NOT NULL,
    project_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    organisation_side text NOT NULL,
    access_role text DEFAULT 'team_member'::text NOT NULL,
    permissions jsonb DEFAULT '{}'::jsonb NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_until timestamp with time zone,
    granted_by uuid,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    revocation_reason text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_project_access_access_role_check CHECK ((access_role = ANY (ARRAY['responsible'::text, 'team_member'::text, 'supervisor'::text, 'read_only'::text]))),
    CONSTRAINT builder_project_access_organisation_side_check CHECK ((organisation_side = ANY (ARRAY['developer'::text, 'builder'::text]))),
    CONSTRAINT builder_project_access_permissions_valid CHECK (public.builder_tri_state_permissions_valid(permissions)),
    CONSTRAINT builder_project_access_window_valid CHECK (((valid_until IS NULL) OR (valid_until > valid_from)))
);


--
-- Name: TABLE builder_project_access; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_project_access IS 'Explicit Builder Portal project access grants. Mirrors solicitor_matter_access. Organisation membership is never on its own an authorization boundary.';


--
-- Name: builder_admin_revoke_project_access(uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_revoke_project_access(_actor_user_id uuid, _actor_type text, _access_id uuid, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_project_access
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_project_access; v_row public.builder_project_access;
BEGIN
  SELECT * INTO v_existing FROM public.builder_project_access
  WHERE id = _access_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_ACCESS_NOT_FOUND';
  END IF;
  IF v_existing.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_ACCESS_ALREADY_REVOKED';
  END IF;
  IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_existing.row_version);
  END IF;

  UPDATE public.builder_project_access
  SET revoked_at = now(), revoked_by = _actor_user_id,
      revocation_reason = COALESCE(NULLIF(btrim(_reason), ''), 'Revoked by Command Centre'),
      row_version = row_version + 1
  WHERE id = v_existing.id
  RETURNING * INTO v_row;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_project_access_revoked',
    'project_access', v_row.id, v_row.organisation_id, v_row.builder_user_id,
    jsonb_build_object('revoked_at', NULL, 'access_role', v_existing.access_role),
    jsonb_build_object('revoked_at', v_row.revoked_at),
    _reason, jsonb_build_object('project_id', v_row.project_id));

  PERFORM public.builder_revoke_user_sessions(
    v_row.builder_user_id, 'project_access_revoked', NULL);

  RETURN v_row;
END $$;


--
-- Name: builder_admin_revoke_user_sessions(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_revoke_user_sessions(_actor_user_id uuid, _actor_type text, _builder_user_id uuid, _reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_revoked integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.builder_portal_users WHERE id = _builder_user_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;

  v_revoked := public.builder_revoke_user_sessions(
    _builder_user_id, COALESCE(NULLIF(btrim(_reason), ''), 'revoked by administrator'), NULL);

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_sessions_revoked',
    'session', NULL, NULL, _builder_user_id,
    NULL, jsonb_build_object('revoked', v_revoked), _reason,
    jsonb_build_object('revoked', v_revoked));

  RETURN v_revoked;
END $$;


--
-- Name: builder_admin_set_membership_permissions(uuid, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_set_membership_permissions(_actor_user_id uuid, _actor_type text, _membership_id uuid, _overrides jsonb, _reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_membership public.builder_organisation_memberships;
  v_previous jsonb;
  v_new jsonb;
  v_entry jsonb;
  v_applied integer := 0;
BEGIN
  SELECT * INTO v_membership FROM public.builder_organisation_memberships
  WHERE id = _membership_id AND revoked_at IS NULL
  FOR UPDATE;
  IF v_membership.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_MEMBERSHIP_NOT_FOUND_OR_REVOKED';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'permission_key', permission_key, 'view', view_decision,
           'edit', edit_decision, 'delete', delete_decision) ORDER BY permission_key), '[]'::jsonb)
  INTO v_previous
  FROM public.builder_membership_permissions
  WHERE membership_id = _membership_id AND scope_type = 'organisation';

  DELETE FROM public.builder_membership_permissions
  WHERE membership_id = _membership_id AND scope_type = 'organisation';

  FOR v_entry IN SELECT * FROM jsonb_array_elements(COALESCE(_overrides, '[]'::jsonb))
  LOOP
    -- The forbidden-key and projection-writability triggers from Phase 1 still
    -- apply; an attempt to smuggle one through raises and rolls the whole
    -- command back, audit included.
    INSERT INTO public.builder_membership_permissions(
      membership_id, permission_key, scope_type,
      view_decision, edit_decision, delete_decision, reason, granted_by)
    VALUES (
      _membership_id,
      v_entry ->> 'permission_key',
      'organisation',
      COALESCE(v_entry ->> 'view_decision', 'inherit'),
      COALESCE(v_entry ->> 'edit_decision', 'inherit'),
      COALESCE(v_entry ->> 'delete_decision', 'inherit'),
      NULLIF(btrim(COALESCE(v_entry ->> 'reason', '')), ''),
      _actor_user_id);
    v_applied := v_applied + 1;
  END LOOP;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'permission_key', permission_key, 'view', view_decision,
           'edit', edit_decision, 'delete', delete_decision) ORDER BY permission_key), '[]'::jsonb)
  INTO v_new
  FROM public.builder_membership_permissions
  WHERE membership_id = _membership_id AND scope_type = 'organisation';

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_membership_permissions_changed',
    'membership_permissions', _membership_id,
    v_membership.organisation_id, v_membership.builder_user_id,
    v_previous, v_new, _reason,
    jsonb_build_object('applied', v_applied));

  RETURN v_applied;
END $$;


--
-- Name: builder_organisations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_organisations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    legal_name text NOT NULL,
    trading_name text,
    org_type text NOT NULL,
    abn text,
    acn text,
    contact_email text,
    contact_phone text,
    website text,
    address_line1 text,
    address_line2 text,
    suburb text,
    state text,
    postcode text,
    status text DEFAULT 'pending_activation'::text NOT NULL,
    is_active boolean DEFAULT false NOT NULL,
    activated_at timestamp with time zone,
    suspended_at timestamp with time zone,
    suspension_reason text,
    notes text,
    created_by uuid,
    updated_by uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_organisations_abn_check CHECK (((abn IS NULL) OR (abn ~ '^[0-9]{11}$'::text))),
    CONSTRAINT builder_organisations_acn_check CHECK (((acn IS NULL) OR (acn ~ '^[0-9]{9}$'::text))),
    CONSTRAINT builder_organisations_activation_stamp CHECK (((status <> 'active'::text) OR (activated_at IS NOT NULL))),
    CONSTRAINT builder_organisations_contact_email_check CHECK (((contact_email IS NULL) OR (contact_email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))),
    CONSTRAINT builder_organisations_legal_name_check CHECK ((btrim(legal_name) <> ''::text)),
    CONSTRAINT builder_organisations_org_type_check CHECK ((org_type = ANY (ARRAY['developer'::text, 'builder'::text, 'builder_developer'::text, 'sales_representative'::text]))),
    CONSTRAINT builder_organisations_postcode_check CHECK (((postcode IS NULL) OR (postcode ~ '^[0-9]{4}$'::text))),
    CONSTRAINT builder_organisations_state_check CHECK (((state IS NULL) OR (state = ANY (ARRAY['NSW'::text, 'VIC'::text, 'QLD'::text, 'SA'::text, 'WA'::text, 'TAS'::text, 'NT'::text, 'ACT'::text])))),
    CONSTRAINT builder_organisations_status_active_agree CHECK ((((status = 'active'::text) AND is_active) OR ((status <> 'active'::text) AND (NOT is_active)))),
    CONSTRAINT builder_organisations_status_check CHECK ((status = ANY (ARRAY['pending_activation'::text, 'active'::text, 'suspended'::text, 'closed'::text]))),
    CONSTRAINT builder_organisations_suspension_stamp CHECK (((status <> 'suspended'::text) OR (suspended_at IS NOT NULL)))
);


--
-- Name: TABLE builder_organisations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_organisations IS 'Builder and developer legal entities. Never auto-created from free-text builder names on client_deals or build_progress_payments; every row is created deliberately through the Command Centre administration plane.';


--
-- Name: builder_admin_set_organisation_status(uuid, text, uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_set_organisation_status(_actor_user_id uuid, _actor_type text, _organisation_id uuid, _status text, _expected_version bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_organisations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.builder_organisations; v_row public.builder_organisations;
  v_member record; v_revoked integer := 0;
BEGIN
  IF _status NOT IN ('pending_activation','active','suspended','closed') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNKNOWN_ORG_STATUS';
  END IF;

  SELECT * INTO v_existing FROM public.builder_organisations WHERE id = _organisation_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_NOT_FOUND';
  END IF;
  IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_existing.row_version);
  END IF;

  UPDATE public.builder_organisations
  SET status = _status,
      is_active = (_status = 'active'),
      activated_at = CASE WHEN _status = 'active' THEN now() ELSE NULL END,
      suspended_at = CASE WHEN _status = 'suspended' THEN now() ELSE NULL END,
      suspension_reason = CASE WHEN _status = 'suspended' THEN NULLIF(btrim(_reason), '') ELSE NULL END,
      updated_by = _actor_user_id
  WHERE id = _organisation_id
  RETURNING * INTO v_row;

  -- Losing organisation activity must end its members' sessions. Membership
  -- rows do not change here, so the membership trigger does not observe this.
  IF _status <> 'active' THEN
    FOR v_member IN
      SELECT builder_user_id FROM public.builder_organisation_memberships
      WHERE organisation_id = _organisation_id AND revoked_at IS NULL
    LOOP
      v_revoked := v_revoked + public.builder_revoke_user_sessions(
        v_member.builder_user_id, 'organisation_' || _status, NULL);
    END LOOP;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_organisation_' || _status,
    'organisation', v_row.id, v_row.id, NULL,
    jsonb_build_object('status', v_existing.status, 'is_active', v_existing.is_active),
    jsonb_build_object('status', v_row.status, 'is_active', v_row.is_active),
    _reason, jsonb_build_object('sessions_revoked', v_revoked));

  RETURN v_row;
END $$;


--
-- Name: builder_portal_users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_portal_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    name text NOT NULL,
    phone text,
    job_title text,
    password_hash text,
    must_change_password boolean DEFAULT true NOT NULL,
    password_changed_at timestamp with time zone,
    invite_token_hash text,
    invite_token_expires_at timestamp with time zone,
    invite_accepted_at timestamp with time zone,
    invited_by uuid,
    invited_at timestamp with time zone,
    reset_token_hash text,
    reset_token_expires_at timestamp with time zone,
    reset_attempts integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'invited'::text NOT NULL,
    is_active boolean DEFAULT false NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    has_accepted_current_terms boolean DEFAULT false NOT NULL,
    has_completed_onboarding boolean DEFAULT false NOT NULL,
    last_seen_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    failed_login_attempts integer DEFAULT 0 NOT NULL,
    locked_until timestamp with time zone,
    last_login_at timestamp with time zone,
    terms_accepted_at timestamp with time zone,
    CONSTRAINT builder_portal_users_email_check CHECK ((email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text)),
    CONSTRAINT builder_portal_users_failed_attempts_sane CHECK (((failed_login_attempts >= 0) AND (failed_login_attempts <= 1000))),
    CONSTRAINT builder_portal_users_invite_token_hash_check CHECK (((invite_token_hash IS NULL) OR (invite_token_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT builder_portal_users_name_check CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT builder_portal_users_reset_attempts_check CHECK ((reset_attempts >= 0)),
    CONSTRAINT builder_portal_users_reset_token_hash_check CHECK (((reset_token_hash IS NULL) OR (reset_token_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT builder_portal_users_revocation_stamp CHECK (((status <> 'revoked'::text) OR (revoked_at IS NOT NULL))),
    CONSTRAINT builder_portal_users_status_active_agree CHECK ((((status = 'active'::text) AND is_active) OR ((status <> 'active'::text) AND (NOT is_active)))),
    CONSTRAINT builder_portal_users_status_check CHECK ((status = ANY (ARRAY['invited'::text, 'active'::text, 'suspended'::text, 'revoked'::text])))
);


--
-- Name: COLUMN builder_portal_users.job_title; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_portal_users.job_title IS 'Display-only job title. Confers no access. Authorization comes from builder_organisation_memberships.membership_role plus permission grants.';


--
-- Name: COLUMN builder_portal_users.locked_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_portal_users.locked_until IS 'Set when failed_login_attempts reaches the lockout threshold. Login returns the generic credential error while locked, so lockout is never observable without valid credentials.';


--
-- Name: builder_admin_set_user_status(uuid, text, uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_set_user_status(_actor_user_id uuid, _actor_type text, _builder_user_id uuid, _status text, _expected_version bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_portal_users
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_portal_users; v_row public.builder_portal_users; v_revoked integer := 0;
BEGIN
  IF _status NOT IN ('invited','active','suspended','revoked') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNKNOWN_USER_STATUS';
  END IF;

  SELECT * INTO v_existing FROM public.builder_portal_users WHERE id = _builder_user_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;
  IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_existing.row_version);
  END IF;

  UPDATE public.builder_portal_users
  SET status = _status,
      is_active = (_status = 'active'),
      revoked_at = CASE WHEN _status = 'revoked' THEN now() ELSE NULL END,
      revoked_reason = CASE WHEN _status = 'revoked'
        THEN COALESCE(NULLIF(btrim(_reason), ''), 'revoked by administrator') ELSE NULL END,
      updated_by = _actor_user_id
  WHERE id = _builder_user_id
  RETURNING * INTO v_row;

  -- Deactivation must not leave a usable session behind. The Phase 1 trigger
  -- already covers active -> non-active; this also covers invited -> suspended.
  IF _status <> 'active' THEN
    v_revoked := public.builder_revoke_user_sessions(_builder_user_id, 'user_' || _status, NULL);
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_user_' || _status,
    'portal_user', v_row.id, NULL, v_row.id,
    jsonb_build_object('status', v_existing.status, 'is_active', v_existing.is_active),
    jsonb_build_object('status', v_row.status, 'is_active', v_row.is_active),
    _reason, jsonb_build_object('sessions_revoked', v_revoked));

  RETURN v_row;
END $$;


--
-- Name: builder_developments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_developments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    developer_organisation_id uuid NOT NULL,
    name text NOT NULL,
    development_reference text,
    description text,
    address_line text,
    suburb text,
    state text,
    postcode text,
    status text DEFAULT 'planning'::text NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_developments_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_developments_postcode_check CHECK (((postcode IS NULL) OR (postcode ~ '^[0-9]{4}$'::text))),
    CONSTRAINT builder_developments_state_check CHECK (((state IS NULL) OR (state = ANY (ARRAY['NSW'::text, 'VIC'::text, 'QLD'::text, 'SA'::text, 'WA'::text, 'TAS'::text, 'NT'::text, 'ACT'::text])))),
    CONSTRAINT builder_developments_status_check CHECK ((status = ANY (ARRAY['planning'::text, 'active'::text, 'on_hold'::text, 'completed'::text, 'cancelled'::text])))
);


--
-- Name: TABLE builder_developments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_developments IS 'A development groups Builder projects under one developer organisation. No Solicitor equivalent — a legal matter has no parent grouping.';


--
-- Name: builder_admin_upsert_development(uuid, text, uuid, uuid, jsonb, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_upsert_development(_actor_user_id uuid, _actor_type text, _development_id uuid, _developer_organisation_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _status text DEFAULT NULL::text, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_developments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_developments; v_row public.builder_developments; v_org_status text;
BEGIN
  IF _status IS NOT NULL AND _status NOT IN ('planning','active','on_hold','completed','cancelled') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_DEVELOPMENT_STATUS';
  END IF;

  IF _development_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_developments
    WHERE id = _development_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DEVELOPMENT_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;

    UPDATE public.builder_developments SET
      name                  = CASE WHEN _payload ? 'name' THEN _payload->>'name' ELSE name END,
      development_reference = CASE WHEN _payload ? 'development_reference' THEN _payload->>'development_reference' ELSE development_reference END,
      description           = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      address_line          = CASE WHEN _payload ? 'address_line' THEN _payload->>'address_line' ELSE address_line END,
      suburb                = CASE WHEN _payload ? 'suburb' THEN _payload->>'suburb' ELSE suburb END,
      state                 = CASE WHEN _payload ? 'state' THEN _payload->>'state' ELSE state END,
      postcode              = CASE WHEN _payload ? 'postcode' THEN _payload->>'postcode' ELSE postcode END,
      status                = COALESCE(_status, status),
      row_version           = row_version + 1,
      updated_at            = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_row;

    PERFORM public.builder_log_activity(
      _actor_user_id, _actor_type, 'builder_development_updated',
      'development', v_row.id, v_row.developer_organisation_id, NULL,
      jsonb_build_object('name', v_existing.name, 'status', v_existing.status),
      jsonb_build_object('name', v_row.name, 'status', v_row.status,
                         'row_version', v_row.row_version),
      _reason, '{}'::jsonb);
    RETURN v_row;
  END IF;

  IF _developer_organisation_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORGANISATION_REQUIRED';
  END IF;
  SELECT status INTO v_org_status FROM public.builder_organisations
  WHERE id = _developer_organisation_id;
  IF v_org_status IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_NOT_FOUND';
  END IF;
  IF v_org_status = 'closed' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_CLOSED';
  END IF;

  INSERT INTO public.builder_developments(
    developer_organisation_id, name, development_reference, description,
    address_line, suburb, state, postcode, status)
  VALUES (_developer_organisation_id, _payload->>'name', _payload->>'development_reference',
          _payload->>'description', _payload->>'address_line', _payload->>'suburb',
          _payload->>'state', _payload->>'postcode', COALESCE(_status, 'planning'))
  RETURNING * INTO v_row;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_development_created',
    'development', v_row.id, v_row.developer_organisation_id, NULL,
    NULL, jsonb_build_object('name', v_row.name, 'status', v_row.status),
    _reason, '{}'::jsonb);
  RETURN v_row;
END $$;


--
-- Name: builder_admin_upsert_membership(uuid, text, uuid, uuid, text, boolean, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_upsert_membership(_actor_user_id uuid, _actor_type text, _builder_user_id uuid, _organisation_id uuid, _membership_role text, _is_primary boolean, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_organisation_memberships
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.builder_organisation_memberships;
  v_row public.builder_organisation_memberships;
  v_org_status text;
  v_user_status text;
BEGIN
  SELECT status INTO v_org_status FROM public.builder_organisations WHERE id = _organisation_id;
  IF v_org_status IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_NOT_FOUND';
  END IF;
  IF v_org_status = 'closed' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_CLOSED';
  END IF;

  SELECT status INTO v_user_status FROM public.builder_portal_users WHERE id = _builder_user_id;
  IF v_user_status IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;
  IF v_user_status = 'revoked' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_REVOKED';
  END IF;

  SELECT * INTO v_existing FROM public.builder_organisation_memberships
  WHERE builder_user_id = _builder_user_id AND organisation_id = _organisation_id
    AND revoked_at IS NULL
  FOR UPDATE;

  -- Move the primary flag off whichever live membership holds it, so the
  -- partial unique index is satisfied by the write below.
  IF COALESCE(_is_primary, false) THEN
    UPDATE public.builder_organisation_memberships
    SET is_primary = false
    WHERE builder_user_id = _builder_user_id
      AND revoked_at IS NULL
      AND is_primary
      AND (v_existing.id IS NULL OR id <> v_existing.id);
  END IF;

  IF v_existing.id IS NOT NULL THEN
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;

    UPDATE public.builder_organisation_memberships
    SET membership_role = _membership_role, is_primary = COALESCE(_is_primary, false)
    WHERE id = v_existing.id
    RETURNING * INTO v_row;

    PERFORM public.builder_log_activity(
      _actor_user_id, _actor_type, 'builder_membership_role_changed',
      'membership', v_row.id, _organisation_id, _builder_user_id,
      jsonb_build_object('membership_role', v_existing.membership_role,
                         'is_primary', v_existing.is_primary,
                         'status', v_existing.status),
      jsonb_build_object('membership_role', v_row.membership_role,
                         'is_primary', v_row.is_primary,
                         'status', v_row.status),
      _reason, '{}'::jsonb);
  ELSE
    INSERT INTO public.builder_organisation_memberships(
      builder_user_id, organisation_id, membership_role, is_primary, status, granted_by)
    VALUES (_builder_user_id, _organisation_id, _membership_role,
            COALESCE(_is_primary, false), 'active', _actor_user_id)
    RETURNING * INTO v_row;

    PERFORM public.builder_log_activity(
      _actor_user_id, _actor_type, 'builder_membership_granted',
      'membership', v_row.id, _organisation_id, _builder_user_id,
      NULL,
      jsonb_build_object('membership_role', v_row.membership_role,
                         'is_primary', v_row.is_primary,
                         'status', v_row.status),
      _reason, '{}'::jsonb);
  END IF;

  RETURN v_row;
END $$;


--
-- Name: builder_admin_upsert_project_access(uuid, text, uuid, uuid, text, text, jsonb, timestamp with time zone, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_admin_upsert_project_access(_actor_user_id uuid, _actor_type text, _builder_user_id uuid, _project_id uuid, _organisation_side text, _access_role text, _permissions jsonb DEFAULT '{}'::jsonb, _valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_project_access
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.builder_project_access;
  v_row public.builder_project_access;
  v_dev uuid; v_builder uuid; v_org uuid;
BEGIN
  IF _organisation_side NOT IN ('developer','builder') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_ORGANISATION_SIDE';
  END IF;
  IF _access_role NOT IN ('responsible','team_member','supervisor','read_only') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_ACCESS_ROLE';
  END IF;
  IF _valid_until IS NOT NULL AND _valid_until <= now() THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ACCESS_WINDOW_INVALID';
  END IF;

  SELECT developer_organisation_id, builder_organisation_id INTO v_dev, v_builder
  FROM public.builder_projects WHERE id = _project_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
  END IF;
  v_org := CASE _organisation_side WHEN 'developer' THEN v_dev ELSE v_builder END;
  IF v_org IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_SIDE_UNASSIGNED';
  END IF;

  SELECT * INTO v_existing FROM public.builder_project_access
  WHERE builder_user_id = _builder_user_id AND project_id = _project_id
  FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;

    UPDATE public.builder_project_access
    SET organisation_id = v_org,
        organisation_side = _organisation_side,
        access_role = _access_role,
        permissions = COALESCE(_permissions, '{}'::jsonb),
        valid_until = _valid_until,
        revoked_at = NULL, revoked_by = NULL, revocation_reason = NULL,
        row_version = row_version + 1
    WHERE id = v_existing.id
    RETURNING * INTO v_row;

    PERFORM public.builder_log_activity(
      _actor_user_id, _actor_type, 'builder_project_access_updated',
      'project_access', v_row.id, v_org, _builder_user_id,
      jsonb_build_object('access_role', v_existing.access_role,
                         'organisation_side', v_existing.organisation_side,
                         'valid_until', v_existing.valid_until,
                         'revoked_at', v_existing.revoked_at),
      jsonb_build_object('access_role', v_row.access_role,
                         'organisation_side', v_row.organisation_side,
                         'valid_until', v_row.valid_until),
      _reason, jsonb_build_object('project_id', _project_id));
  ELSE
    INSERT INTO public.builder_project_access(
      builder_user_id, project_id, organisation_id, organisation_side,
      access_role, permissions, valid_until, granted_by)
    VALUES (_builder_user_id, _project_id, v_org, _organisation_side,
            _access_role, COALESCE(_permissions, '{}'::jsonb), _valid_until, _actor_user_id)
    RETURNING * INTO v_row;

    PERFORM public.builder_log_activity(
      _actor_user_id, _actor_type, 'builder_project_access_granted',
      'project_access', v_row.id, v_org, _builder_user_id,
      NULL,
      jsonb_build_object('access_role', v_row.access_role,
                         'organisation_side', v_row.organisation_side,
                         'valid_until', v_row.valid_until),
      _reason, jsonb_build_object('project_id', _project_id));
  END IF;

  -- Access changed, so every live session is re-evaluated from scratch.
  PERFORM public.builder_revoke_user_sessions(
    _builder_user_id, 'project_access_changed', NULL);

  RETURN v_row;
END $$;


--
-- Name: builder_can_see_activity(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_can_see_activity(_user_id uuid, _entity_type text, _entity_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_parent uuid;
BEGIN
  IF _entity_type IS NULL OR _entity_id IS NULL THEN RETURN false; END IF;
  IF NOT public.builder_activity_entity_is_portal_visible(_entity_type) THEN
    RETURN false;
  END IF;

  -- ── Project scope ────────────────────────────────────────────────────────
  IF _entity_type = 'project' THEN
    RETURN public.builder_resolve_project_permission(_user_id, _entity_id, 'projects', 'view');
  ELSIF _entity_type = 'project_party' THEN
    SELECT project_id INTO v_parent FROM public.builder_project_parties WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_project_permission(_user_id, v_parent, 'projects', 'view');
  ELSIF _entity_type = 'stage' THEN
    SELECT project_id INTO v_parent FROM public.builder_stages WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_project_permission(_user_id, v_parent, 'inventory', 'view');
  ELSIF _entity_type = 'building' THEN
    SELECT project_id INTO v_parent FROM public.builder_buildings WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_project_permission(_user_id, v_parent, 'inventory', 'view');
  ELSIF _entity_type = 'lot' THEN
    SELECT project_id INTO v_parent FROM public.builder_lots WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_project_permission(_user_id, v_parent, 'inventory', 'view');

  -- ── Unit scope ───────────────────────────────────────────────────────────
  ELSIF _entity_type = 'unit' THEN
    RETURN public.builder_resolve_unit_permission(_user_id, _entity_id, 'inventory', 'view');
  ELSIF _entity_type = 'unit_price' THEN
    SELECT unit_id INTO v_parent FROM public.builder_unit_pricing WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_unit_permission(_user_id, v_parent, 'pricing', 'view');
  ELSIF _entity_type = 'unit_hold' THEN
    SELECT unit_id INTO v_parent FROM public.builder_unit_holds WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_unit_permission(_user_id, v_parent, 'inventory', 'view');
  ELSIF _entity_type = 'reservation' THEN
    SELECT unit_id INTO v_parent FROM public.builder_reservations WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_unit_permission(_user_id, v_parent, 'reservations', 'view');
  ELSIF _entity_type = 'allocation' THEN
    SELECT unit_id INTO v_parent FROM public.builder_allocations WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_unit_permission(_user_id, v_parent, 'inventory', 'view');

  -- ── Transaction scope ────────────────────────────────────────────────────
  ELSIF _entity_type = 'transaction' THEN
    RETURN public.builder_resolve_transaction_permission(
             _user_id, _entity_id, 'transactions', 'view');
  ELSIF _entity_type = 'transaction_party' THEN
    SELECT transaction_id INTO v_parent
    FROM public.builder_transaction_parties WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_resolve_transaction_permission(
             _user_id, v_parent, 'transactions', 'view');

  -- ── Construction scope ───────────────────────────────────────────────────
  ELSIF _entity_type = 'construction_case' THEN
    RETURN public.builder_resolve_construction_permission(
             _user_id, _entity_id, 'construction', 'view');
  ELSIF _entity_type = 'construction_stage' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_construction_stages WHERE id = _entity_id;
  ELSIF _entity_type = 'milestone' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_construction_milestones WHERE id = _entity_id;
  ELSIF _entity_type = 'progress_update' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_construction_progress_updates WHERE id = _entity_id;
  ELSIF _entity_type = 'photograph' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_construction_photographs WHERE id = _entity_id;
  ELSIF _entity_type = 'variation' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_variations WHERE id = _entity_id;
  ELSIF _entity_type = 'variation_approval' THEN
    SELECT v.construction_case_id INTO v_parent
    FROM public.builder_variation_approvals a
    JOIN public.builder_variations v ON v.id = a.variation_id WHERE a.id = _entity_id;
  ELSIF _entity_type = 'progress_claim' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_progress_claims WHERE id = _entity_id;
  ELSIF _entity_type = 'inspection' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_inspections WHERE id = _entity_id;
  ELSIF _entity_type = 'defect' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_defects WHERE id = _entity_id;
  ELSIF _entity_type = 'practical_completion' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_practical_completions WHERE id = _entity_id;
  ELSIF _entity_type = 'handover' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_handovers WHERE id = _entity_id;
  ELSIF _entity_type = 'warranty_claim' THEN
    SELECT construction_case_id INTO v_parent
    FROM public.builder_warranty_claims WHERE id = _entity_id;

  -- ── Collaboration scope ──────────────────────────────────────────────────
  ELSIF _entity_type = 'document' THEN
    RETURN public.builder_can_see_document(_user_id, _entity_id, 'view');
  ELSIF _entity_type = 'document_version' THEN
    SELECT document_id INTO v_parent
    FROM public.builder_document_versions WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_can_see_document(_user_id, v_parent, 'view');
  ELSIF _entity_type = 'conversation' THEN
    RETURN public.builder_can_see_conversation(_user_id, _entity_id, 'view');
  ELSIF _entity_type = 'message' THEN
    SELECT conversation_id INTO v_parent FROM public.builder_messages WHERE id = _entity_id;
    RETURN v_parent IS NOT NULL
       AND public.builder_can_see_conversation(_user_id, v_parent, 'view');
  ELSIF _entity_type = 'task' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.builder_tasks t WHERE t.id = _entity_id
        AND public.builder_resolve_scope_permission(
              _user_id, t.scope_type, t.scope_id, 'tasks', 'view'));
  ELSIF _entity_type = 'task_assignment' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.builder_task_assignments a
      JOIN public.builder_tasks t ON t.id = a.task_id
      WHERE a.id = _entity_id
        AND public.builder_resolve_scope_permission(
              _user_id, t.scope_type, t.scope_id, 'tasks', 'view'));
  ELSE
    RETURN false;
  END IF;

  -- Every construction child falls through to here with its case in v_parent.
  RETURN v_parent IS NOT NULL
     AND public.builder_resolve_construction_permission(
           _user_id, v_parent, 'construction', 'view');
END $$;


--
-- Name: builder_can_see_conversation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_can_see_conversation(_user_id uuid, _conversation_id uuid, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.builder_conversations; v_has_participants boolean;
BEGIN
  SELECT * INTO c FROM public.builder_conversations WHERE id = _conversation_id;
  IF c.id IS NULL THEN RETURN false; END IF;

  IF NOT public.builder_resolve_scope_permission(
       _user_id, c.scope_type, c.scope_id, 'messages', _level) THEN
    RETURN false;
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.builder_conversation_participants
                 WHERE conversation_id = _conversation_id AND left_at IS NULL)
  INTO v_has_participants;
  IF NOT v_has_participants THEN RETURN true; END IF;

  RETURN EXISTS (SELECT 1 FROM public.builder_conversation_participants
                 WHERE conversation_id = _conversation_id AND builder_user_id = _user_id
                   AND left_at IS NULL);
END $$;


--
-- Name: builder_can_see_document(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_can_see_document(_user_id uuid, _document_id uuid, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE d public.builder_documents; v_restricted boolean;
BEGIN
  SELECT * INTO d FROM public.builder_documents WHERE id = _document_id;
  IF d.id IS NULL THEN RETURN false; END IF;

  IF NOT public.builder_resolve_scope_permission(
       _user_id, d.scope_type, d.scope_id, 'documents', _level) THEN
    RETURN false;
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.builder_document_grants
                 WHERE document_id = _document_id AND revoked_at IS NULL)
  INTO v_restricted;
  IF NOT v_restricted THEN RETURN true; END IF;

  RETURN EXISTS (SELECT 1 FROM public.builder_document_grants
                 WHERE document_id = _document_id AND builder_user_id = _user_id
                   AND revoked_at IS NULL);
END $$;


--
-- Name: builder_complete_onboarding(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_complete_onboarding(_builder_user_id uuid, _session_id uuid, _step_key text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_mandatory_total integer; v_mandatory_done integer; v_complete boolean;
BEGIN
  -- Session ownership, as in builder_accept_current_terms and
  -- builder_select_session_organisation. `completed_session_id` is stamped from
  -- `_session_id`, so an unverified pair would attribute a completion to a
  -- session that does not belong to the user.
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_portal_sessions
    WHERE id = _session_id AND builder_user_id = _builder_user_id AND revoked_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SESSION_NOT_FOUND';
  END IF;

  PERFORM public.builder_ensure_onboarding_steps(_builder_user_id);

  UPDATE public.builder_onboarding_steps
  SET completed_at = COALESCE(completed_at, now()),
      completed_session_id = COALESCE(completed_session_id, _session_id)
  WHERE builder_user_id = _builder_user_id
    AND (_step_key IS NULL OR step_key = _step_key);

  SELECT count(*) FILTER (WHERE mandatory),
         count(*) FILTER (WHERE mandatory AND completed_at IS NOT NULL)
  INTO v_mandatory_total, v_mandatory_done
  FROM public.builder_onboarding_steps
  WHERE builder_user_id = _builder_user_id;

  v_complete := v_mandatory_total > 0 AND v_mandatory_done = v_mandatory_total;

  UPDATE public.builder_portal_users
  SET has_completed_onboarding = v_complete
  WHERE id = _builder_user_id;

  PERFORM public.builder_log_activity(
    NULL, 'builder_user', 'builder_onboarding_updated',
    'portal_user', _builder_user_id, NULL, _builder_user_id,
    NULL, jsonb_build_object('step_key', _step_key, 'mandatory_complete', v_complete),
    NULL, jsonb_build_object('session_id', _session_id));

  RETURN v_complete;
END $$;


--
-- Name: builder_complete_onboarding_tour(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_complete_onboarding_tour(_builder_user_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_completed timestamptz;
BEGIN
  IF _builder_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PREFERENCE_OWNER_REQUIRED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_portal_users WHERE id = _builder_user_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;

  INSERT INTO public.builder_user_preferences(builder_user_id, tour_completed_at)
  VALUES (_builder_user_id, now())
  ON CONFLICT (builder_user_id) DO UPDATE
    -- Monotonic: a replay from settings clears the flag client-side and
    -- re-completing restamps it, but an already-completed tour is never
    -- silently backdated by a concurrent call.
    SET tour_completed_at = COALESCE(public.builder_user_preferences.tour_completed_at, now())
  RETURNING tour_completed_at INTO v_completed;

  RETURN v_completed;
END $$;


--
-- Name: FUNCTION builder_complete_onboarding_tour(_builder_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_complete_onboarding_tour(_builder_user_id uuid) IS 'Stamps guided-tour completion for one Builder user. Idempotent, single-field and version-free, so it can never collide with the preferences form.';


