--

CREATE TABLE public.builder_allocations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    allocated_to_organisation_id uuid NOT NULL,
    allocation_type text DEFAULT 'sales_channel'::text NOT NULL,
    reference text,
    expires_at timestamp with time zone,
    status text DEFAULT 'active'::text NOT NULL,
    released_at timestamp with time zone,
    released_reason text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_allocations_allocation_type_check CHECK ((allocation_type = ANY (ARRAY['sales_channel'::text, 'display'::text, 'staff'::text, 'investor'::text, 'other'::text]))),
    CONSTRAINT builder_allocations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'released'::text, 'expired'::text])))
);


--
-- Name: builder_create_allocation(uuid, text, uuid, uuid, uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_create_allocation(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _unit_id uuid, _allocated_to_organisation_id uuid, _allocation_type text DEFAULT 'sales_channel'::text, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _reference text DEFAULT NULL::text, _reason text DEFAULT NULL::text) RETURNS public.builder_allocations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.builder_allocations; v_project uuid; v_org uuid;
BEGIN
  SELECT project_id INTO v_project FROM public.builder_units WHERE id = _unit_id;
  IF v_project IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_FOUND'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_organisations
                 WHERE id = _allocated_to_organisation_id AND status <> 'closed') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_NOT_FOUND'; END IF;
  IF _allocation_type NOT IN ('sales_channel','display','staff','investor','other') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_ALLOCATION_TYPE'; END IF;
  IF _expires_at IS NOT NULL AND _expires_at <= now() THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ALLOCATION_EXPIRY_INVALID'; END IF;

  INSERT INTO public.builder_allocations(unit_id, allocated_to_organisation_id,
    allocation_type, reference, expires_at)
  VALUES (_unit_id, _allocated_to_organisation_id, _allocation_type, _reference, _expires_at)
  RETURNING * INTO v_row;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = v_project;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_allocation_created',
    'allocation', v_row.id, v_org, _actor_builder_user_id,
    NULL, jsonb_build_object('allocated_to', v_row.allocated_to_organisation_id,
                             'allocation_type', v_row.allocation_type),
    _reason, jsonb_build_object('unit_id', _unit_id));
  RETURN v_row;
END $$;


--
-- Name: builder_conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope_type text NOT NULL,
    scope_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    subject text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    last_message_at timestamp with time zone,
    message_count integer DEFAULT 0 NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_conversations_message_count_check CHECK ((message_count >= 0)),
    CONSTRAINT builder_conversations_scope_type_check CHECK ((scope_type = ANY (ARRAY['project'::text, 'unit'::text, 'transaction'::text, 'construction_case'::text]))),
    CONSTRAINT builder_conversations_status_check CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text, 'archived'::text]))),
    CONSTRAINT builder_conversations_subject_check CHECK ((length(btrim(subject)) > 0))
);


--
-- Name: builder_create_conversation(uuid, text, uuid, text, uuid, jsonb, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_create_conversation(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _scope_type text, _scope_id uuid, _payload jsonb, _participant_ids uuid[] DEFAULT NULL::uuid[], _reason text DEFAULT NULL::text) RETURNS public.builder_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.builder_conversations; v_org uuid; p uuid;
BEGIN
  IF NULLIF(btrim(COALESCE(_payload->>'subject','')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONVERSATION_SUBJECT_REQUIRED';
  END IF;
  v_org := public.builder_scope_org(_scope_type, _scope_id);
  IF v_org IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
  END IF;

  INSERT INTO public.builder_conversations(scope_type, scope_id, organisation_id, subject)
  VALUES (_scope_type, _scope_id, v_org, _payload->>'subject')
  RETURNING * INTO v_row;

  -- The author is always a participant; anyone else named is added too. A
  -- participant who cannot reach the scope still cannot open the conversation,
  -- because the resolver runs first.
  IF _actor_builder_user_id IS NOT NULL THEN
    INSERT INTO public.builder_conversation_participants(conversation_id, builder_user_id)
    VALUES (v_row.id, _actor_builder_user_id) ON CONFLICT DO NOTHING;
  END IF;
  IF _participant_ids IS NOT NULL THEN
    FOREACH p IN ARRAY _participant_ids LOOP
      INSERT INTO public.builder_conversation_participants(conversation_id, builder_user_id)
      VALUES (v_row.id, p) ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_conversation_created',
    'conversation', v_row.id, v_org, _actor_builder_user_id,
    NULL, jsonb_build_object('subject', v_row.subject),
    _reason, jsonb_build_object('scope_type', _scope_type, 'scope_id', _scope_id));
  RETURN v_row;
END $$;


--
-- Name: builder_reservations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_reservations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    reservation_reference text,
    purchaser_name text NOT NULL,
    purchaser_email text,
    purchaser_phone text,
    reserved_by_builder_user_id uuid,
    reservation_fee numeric(14,2),
    reserved_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    status text DEFAULT 'active'::text NOT NULL,
    cancelled_reason text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_reservations_purchaser_name_check CHECK ((length(btrim(purchaser_name)) > 0)),
    CONSTRAINT builder_reservations_reservation_fee_check CHECK (((reservation_fee IS NULL) OR (reservation_fee >= (0)::numeric))),
    CONSTRAINT builder_reservations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'contracted'::text, 'cancelled'::text, 'expired'::text, 'lapsed'::text]))),
    CONSTRAINT builder_reservations_window_valid CHECK (((expires_at IS NULL) OR (expires_at > reserved_at)))
);


--
-- Name: builder_create_reservation(uuid, text, uuid, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_create_reservation(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _unit_id uuid, _organisation_id uuid, _payload jsonb, _reason text DEFAULT NULL::text) RETURNS public.builder_reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.builder_reservations; u public.builder_units; v_org uuid; v_expires timestamptz;
BEGIN
  SELECT * INTO u FROM public.builder_units WHERE id = _unit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_FOUND'; END IF;
  IF NULLIF(btrim(COALESCE(_payload->>'purchaser_name','')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PURCHASER_REQUIRED'; END IF;
  IF u.availability_status NOT IN ('available','on_hold') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_RESERVABLE',
      DETAIL=format('unit is %s', u.availability_status); END IF;

  v_expires := (_payload->>'expires_at')::timestamptz;
  IF v_expires IS NOT NULL AND v_expires <= now() THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_RESERVATION_EXPIRY_INVALID'; END IF;

  INSERT INTO public.builder_reservations(unit_id, organisation_id, reservation_reference,
    purchaser_name, purchaser_email, purchaser_phone, reserved_by_builder_user_id,
    reservation_fee, expires_at)
  VALUES (_unit_id, _organisation_id, _payload->>'reservation_reference',
    _payload->>'purchaser_name', _payload->>'purchaser_email', _payload->>'purchaser_phone',
    _actor_builder_user_id, (_payload->>'reservation_fee')::numeric, v_expires)
  RETURNING * INTO v_row;

  INSERT INTO public.builder_reservation_status_history(reservation_id, from_status, to_status,
    changed_by_type, changed_by_builder_user_id, changed_by_user_id, reason)
  VALUES (v_row.id, NULL, 'active', _actor_type, _actor_builder_user_id, _actor_user_id,
    COALESCE(_reason, 'Reservation created'));

  PERFORM public.builder_transition_unit_availability(
    _unit_id, u.row_version, u.availability_status, 'reserved',
    COALESCE(_reason, 'Unit reserved'), _actor_type, _actor_builder_user_id, _actor_user_id);

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = u.project_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_reservation_created',
    'reservation', v_row.id, v_org, _actor_builder_user_id,
    NULL, jsonb_build_object('purchaser_name', v_row.purchaser_name, 'status', v_row.status),
    _reason, jsonb_build_object('unit_id', _unit_id));
  RETURN v_row;
END $$;


