    status text DEFAULT 'active'::text NOT NULL,
    released_at timestamp with time zone,
    released_reason text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_unit_holds_status_check CHECK ((status = ANY (ARRAY['active'::text, 'released'::text, 'expired'::text, 'converted'::text])))
);


--
-- Name: builder_create_unit_hold(uuid, text, uuid, uuid, uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_create_unit_hold(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _unit_id uuid, _organisation_id uuid, _expires_at timestamp with time zone, _hold_reference text DEFAULT NULL::text, _reason text DEFAULT NULL::text) RETURNS public.builder_unit_holds
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.builder_unit_holds; u public.builder_units; v_org uuid;
BEGIN
  SELECT * INTO u FROM public.builder_units WHERE id = _unit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_FOUND'; END IF;
  IF _expires_at IS NULL OR _expires_at <= now() THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_HOLD_EXPIRY_INVALID';
  END IF;
  IF u.availability_status <> 'available' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_AVAILABLE',
      DETAIL=format('unit is %s', u.availability_status);
  END IF;

  INSERT INTO public.builder_unit_holds(unit_id, organisation_id, held_by_builder_user_id,
    hold_reference, reason, expires_at)
  VALUES (_unit_id, _organisation_id, _actor_builder_user_id, _hold_reference, _reason, _expires_at)
  RETURNING * INTO v_row;

  -- The hold moves the unit, and the move records its own history.
  PERFORM public.builder_transition_unit_availability(
    _unit_id, u.row_version, 'available', 'on_hold',
    COALESCE(_reason, 'Unit placed on hold'), _actor_type, _actor_builder_user_id, _actor_user_id);

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = u.project_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_unit_hold_created',
    'unit_hold', v_row.id, v_org, _actor_builder_user_id,
    NULL, jsonb_build_object('expires_at', v_row.expires_at),
    _reason, jsonb_build_object('unit_id', _unit_id));
  RETURN v_row;
END $$;


--
-- Name: builder_delete_construction_photograph(uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_delete_construction_photograph(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _construction_case_id uuid, _photograph_id uuid, _reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_construction_photographs; v_org uuid; v_txn uuid;
BEGIN
  SELECT * INTO v_existing FROM public.builder_construction_photographs
  WHERE id = _photograph_id AND construction_case_id = _construction_case_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PHOTOGRAPH_NOT_FOUND';
  END IF;

  DELETE FROM public.builder_construction_photographs WHERE id = v_existing.id;

  SELECT transaction_id INTO v_txn FROM public.builder_construction_cases
  WHERE id = _construction_case_id;
  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = v_txn;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_construction_photograph_removed',
    'photograph', v_existing.id, v_org, _actor_builder_user_id,
    jsonb_build_object('file_name', v_existing.file_name,
                       'storage_path', v_existing.storage_path), NULL,
    _reason, jsonb_build_object('construction_case_id', _construction_case_id));
  RETURN true;
END $$;


--
-- Name: builder_delete_project_party(uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_delete_project_party(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _project_id uuid, _party_id uuid, _reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_project_parties; v_project public.builder_projects;
BEGIN
  SELECT * INTO v_project FROM public.builder_projects WHERE id = _project_id;
  IF v_project.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
  END IF;

  SELECT * INTO v_existing FROM public.builder_project_parties
  WHERE id = _party_id AND project_id = _project_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PARTY_NOT_FOUND';
  END IF;

  DELETE FROM public.builder_project_parties WHERE id = v_existing.id;

  -- Removing a party is destructive, so the audit row carries the whole record.
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_project_party_removed',
    'project_party', v_existing.id,
    COALESCE(v_project.developer_organisation_id, v_project.builder_organisation_id),
    _actor_builder_user_id,
    jsonb_build_object('name', v_existing.name, 'role', v_existing.role,
                       'organisation', v_existing.organisation),
    NULL,
    _reason, jsonb_build_object('project_id', _project_id));
  RETURN true;
END $$;


--
-- Name: builder_delete_transaction_party(uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_delete_transaction_party(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _transaction_id uuid, _party_id uuid, _reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_transaction_parties; v_org uuid;
BEGIN
  SELECT * INTO v_existing FROM public.builder_transaction_parties
  WHERE id = _party_id AND transaction_id = _transaction_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PARTY_NOT_FOUND';
  END IF;

  DELETE FROM public.builder_transaction_parties WHERE id = v_existing.id;

  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = _transaction_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_transaction_party_removed',
    'transaction_party', v_existing.id, v_org, _actor_builder_user_id,
    jsonb_build_object('name', v_existing.name, 'role', v_existing.role), NULL,
    _reason, jsonb_build_object('transaction_id', _transaction_id));
  RETURN true;
END $$;


