--
-- Name: builder_enforce_collaboration_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_enforce_collaboration_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.builder_scope_exists(NEW.scope_type, NEW.scope_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND',
      DETAIL=format('%s %s does not exist', NEW.scope_type, NEW.scope_id);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: builder_enforce_construction_parentage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_enforce_construction_parentage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_project uuid; v_unit uuid;
BEGIN
  SELECT project_id, unit_id INTO v_project, v_unit
  FROM public.builder_transactions WHERE id = NEW.transaction_id;
  IF v_project IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TRANSACTION_NOT_FOUND';
  END IF;
  IF NEW.project_id IS DISTINCT FROM v_project THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_PARENT_MISMATCH',
      DETAIL='the construction case names a different project than its transaction';
  END IF;
  IF NEW.unit_id IS NOT NULL AND v_unit IS NOT NULL AND NEW.unit_id IS DISTINCT FROM v_unit THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_PARENT_MISMATCH',
      DETAIL='the construction case names a different unit than its transaction';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: builder_enforce_defect_parentage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_enforce_defect_parentage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_parent uuid;
BEGIN
  IF NEW.inspection_id IS NULL THEN RETURN NEW; END IF;
  SELECT construction_case_id INTO v_parent
  FROM public.builder_inspections WHERE id = NEW.inspection_id;
  IF v_parent IS DISTINCT FROM NEW.construction_case_id THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DELIVERY_PARENT_MISMATCH',
      DETAIL='the inspection belongs to a different construction case';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: builder_enforce_delivery_parentage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_enforce_delivery_parentage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_parent uuid;
BEGIN
  IF NEW.milestone_id IS NULL THEN RETURN NEW; END IF;
  SELECT construction_case_id INTO v_parent
  FROM public.builder_construction_milestones WHERE id = NEW.milestone_id;
  IF v_parent IS DISTINCT FROM NEW.construction_case_id THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DELIVERY_PARENT_MISMATCH',
      DETAIL='the milestone belongs to a different construction case';
  END IF;
  RETURN NEW;
END $$;


