    AS $$
DECLARE v_parent uuid;
BEGIN
  IF NEW.stage_id IS NOT NULL THEN
    SELECT project_id INTO v_parent FROM public.builder_stages WHERE id = NEW.stage_id;
    IF v_parent IS DISTINCT FROM NEW.project_id THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_PARENT_MISMATCH',
        DETAIL='the stage belongs to a different project';
    END IF;
  END IF;
  IF NEW.building_id IS NOT NULL THEN
    SELECT project_id INTO v_parent FROM public.builder_buildings WHERE id = NEW.building_id;
    IF v_parent IS DISTINCT FROM NEW.project_id THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_PARENT_MISMATCH',
        DETAIL='the building belongs to a different project';
    END IF;
  END IF;
  IF NEW.lot_id IS NOT NULL THEN
    SELECT project_id INTO v_parent FROM public.builder_lots WHERE id = NEW.lot_id;
    IF v_parent IS DISTINCT FROM NEW.project_id THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_PARENT_MISMATCH',
        DETAIL='the lot belongs to a different project';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: builder_ensure_onboarding_steps(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_ensure_onboarding_steps(_builder_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_inserted integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.builder_portal_users WHERE id = _builder_user_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;

  WITH seeded AS (
    INSERT INTO public.builder_onboarding_steps(builder_user_id, step_key, mandatory)
    SELECT _builder_user_id, k, true
    FROM unnest(ARRAY['profile_confirmed','organisation_confirmed','contact_confirmed','security_reviewed']) AS k
    ON CONFLICT (builder_user_id, step_key) DO NOTHING
    RETURNING 1)
  SELECT count(*)::integer INTO v_inserted FROM seeded;

  RETURN v_inserted;
END $$;


--
-- Name: builder_guard_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_guard_membership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE org_status text; user_status text;
BEGIN
  SELECT status INTO org_status FROM public.builder_organisations WHERE id = NEW.organisation_id;
  IF org_status IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_NOT_FOUND';
  END IF;
  IF org_status = 'closed' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_CLOSED';
  END IF;

  SELECT status INTO user_status FROM public.builder_portal_users WHERE id = NEW.builder_user_id;
  IF user_status IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;
  IF user_status = 'revoked' AND NEW.revoked_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_REVOKED';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: builder_guard_permission_grant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_guard_permission_grant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE forbidden boolean; kind text;
BEGIN
  SELECT is_forbidden, key_kind INTO forbidden, kind
  FROM public.builder_permission_keys WHERE permission_key = NEW.permission_key;

  IF forbidden IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNKNOWN_PERMISSION_KEY';
  END IF;
  IF forbidden THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_FORBIDDEN_PERMISSION_KEY';
  END IF;

  -- Inbound projections are read-only in every direction.
  IF kind = 'inbound_projection' THEN
    IF TG_TABLE_NAME = 'builder_role_default_permissions' THEN
      IF NEW.can_edit OR NEW.can_delete THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECTION_NOT_WRITABLE';
      END IF;
    ELSE
      IF NEW.edit_decision = 'allow' OR NEW.delete_decision = 'allow' THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECTION_NOT_WRITABLE';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: builder_guard_permission_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_guard_permission_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.scope_type NOT IN ('organisation', 'project', 'stage', 'unit',
                            'transaction', 'construction_case') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='BUILDER_SCOPE_NOT_AVAILABLE',
      DETAIL=format('scope_type %s is not available', NEW.scope_type);
  END IF;

  IF NEW.scope_type = 'organisation' THEN
    IF NEW.scope_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.builder_organisations WHERE id = NEW.scope_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.scope_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND',
      DETAIL='a narrower scope requires a scope_id';
  END IF;

  IF NEW.scope_type = 'project' AND NOT EXISTS (
    SELECT 1 FROM public.builder_projects WHERE id = NEW.scope_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
  END IF;
  IF NEW.scope_type = 'stage' AND NOT EXISTS (
    SELECT 1 FROM public.builder_stages WHERE id = NEW.scope_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
  END IF;
  IF NEW.scope_type = 'unit' AND NOT EXISTS (
    SELECT 1 FROM public.builder_units WHERE id = NEW.scope_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
  END IF;
  IF NEW.scope_type = 'transaction' AND NOT EXISTS (
    SELECT 1 FROM public.builder_transactions WHERE id = NEW.scope_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
  END IF;
  IF NEW.scope_type = 'construction_case' AND NOT EXISTS (
    SELECT 1 FROM public.builder_construction_cases WHERE id = NEW.scope_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: builder_guard_session_organisation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_guard_session_organisation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.active_organisation_id IS NULL THEN RETURN NEW; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.builder_accessible_organisations(NEW.builder_user_id) a
    WHERE a.organisation_id = NEW.active_organisation_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='BUILDER_ORGANISATION_NOT_ACCESSIBLE',
      DETAIL='the session owner holds no active membership of that organisation';
  END IF;

  RETURN NEW;
END $$;


