--
-- Name: builder_is_construction_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_is_construction_transition_allowed(_from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _from = _to THEN false
    WHEN _from IN ('completed','cancelled') THEN false
    WHEN _to = 'cancelled' THEN true
    WHEN _from = 'on_hold' THEN _to IN ('site_preparation','under_construction')
    WHEN _to = 'on_hold' THEN _from IN ('site_preparation','under_construction')
    WHEN _from = 'not_started' THEN _to = 'site_preparation'
    WHEN _from = 'site_preparation' THEN _to = 'under_construction'
    WHEN _from = 'under_construction' THEN _to = 'practical_completion'
    WHEN _from = 'practical_completion' THEN _to IN ('handover','under_construction')
    WHEN _from = 'handover' THEN _to IN ('completed','practical_completion')
    ELSE false
  END;
$$;


--
-- Name: builder_is_delivery_transition_allowed(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_is_delivery_transition_allowed(_kind text, _from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _from = _to THEN false
    WHEN _kind = 'variation' THEN CASE
      WHEN _from IN ('approved','rejected','withdrawn','superseded') THEN false
      WHEN _from = 'draft' THEN _to IN ('submitted','withdrawn')
      WHEN _from = 'submitted' THEN _to IN ('approved','rejected','withdrawn','superseded')
      ELSE false END
    WHEN _kind = 'progress_claim' THEN CASE
      WHEN _from IN ('closed','withdrawn') THEN false
      WHEN _from = 'draft' THEN _to IN ('submitted','withdrawn')
      WHEN _from = 'submitted' THEN _to IN ('certified','disputed','withdrawn')
      WHEN _from = 'disputed' THEN _to IN ('certified','submitted','withdrawn')
      WHEN _from = 'certified' THEN _to = 'closed'
      ELSE false END
    WHEN _kind = 'inspection' THEN CASE
      WHEN _from IN ('cancelled','passed') THEN false
      WHEN _from IN ('scheduled','rescheduled') THEN
        _to IN ('in_progress','rescheduled','cancelled')
      WHEN _from = 'in_progress' THEN _to IN ('passed','failed','passed_with_defects','cancelled')
      WHEN _from IN ('failed','passed_with_defects') THEN _to IN ('rescheduled','passed','cancelled')
      ELSE false END
    WHEN _kind = 'defect' THEN CASE
      WHEN _from = 'closed' THEN false
      WHEN _from = 'open' THEN _to IN ('acknowledged','rejected','in_rectification')
      WHEN _from = 'acknowledged' THEN _to IN ('in_rectification','rejected')
      WHEN _from = 'in_rectification' THEN _to IN ('rectified','open')
      WHEN _from = 'rectified' THEN _to IN ('verified','in_rectification')
      WHEN _from = 'verified' THEN _to = 'closed'
      WHEN _from = 'rejected' THEN _to IN ('open','closed')
      ELSE false END
    WHEN _kind = 'practical_completion' THEN CASE
      WHEN _from = 'achieved' THEN false
      WHEN _from = 'not_reached' THEN _to = 'notified'
      WHEN _from = 'notified' THEN _to IN ('inspected','disputed')
      WHEN _from = 'inspected' THEN _to IN ('achieved','disputed')
      WHEN _from = 'disputed' THEN _to IN ('inspected','notified')
      ELSE false END
    WHEN _kind = 'handover' THEN CASE
      WHEN _from = 'completed' THEN false
      WHEN _from = 'not_scheduled' THEN _to = 'scheduled'
      WHEN _from = 'scheduled' THEN _to IN ('walkthrough_complete','not_scheduled')
      WHEN _from = 'walkthrough_complete' THEN _to = 'keys_released'
      WHEN _from = 'keys_released' THEN _to = 'completed'
      ELSE false END
    WHEN _kind = 'warranty_claim' THEN CASE
      WHEN _from = 'closed' THEN false
      WHEN _from = 'lodged' THEN _to IN ('under_review','rejected')
      WHEN _from = 'under_review' THEN _to IN ('accepted','rejected')
      WHEN _from = 'accepted' THEN _to = 'rectified'
      WHEN _from = 'rectified' THEN _to = 'closed'
      WHEN _from = 'rejected' THEN _to IN ('under_review','closed')
      ELSE false END
    ELSE false
  END;
$$;


--
-- Name: builder_is_milestone_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_is_milestone_transition_allowed(_from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _from = _to THEN false
    WHEN _from = 'achieved' THEN false
    WHEN _to IN ('achieved','missed','waived') THEN _from IN ('pending','in_progress')
    WHEN _from = 'pending' THEN _to = 'in_progress'
    WHEN _from = 'in_progress' THEN _to = 'pending'
    WHEN _from IN ('missed','waived') THEN _to IN ('pending','in_progress')
    ELSE false
  END;
$$;


--
-- Name: builder_is_project_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_is_project_transition_allowed(_from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _from = _to THEN false
    -- Cancelled and completed are terminal from the portal's point of view.
    WHEN _from IN ('completed','cancelled') THEN false
    WHEN _to = 'cancelled' THEN true
    WHEN _from = 'on_hold' THEN _to IN ('planning','pre_sales','approved','under_construction')
    WHEN _to = 'on_hold' THEN true
    WHEN _from = 'planning' THEN _to IN ('pre_sales','approved')
    WHEN _from = 'pre_sales' THEN _to IN ('approved','planning')
    WHEN _from = 'approved' THEN _to IN ('under_construction','pre_sales')
    WHEN _from = 'under_construction' THEN _to IN ('practical_completion')
    WHEN _from = 'practical_completion' THEN _to IN ('handover','under_construction')
    WHEN _from = 'handover' THEN _to IN ('completed','practical_completion')
    ELSE false
  END;
$$;


--
-- Name: builder_is_reservation_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_is_reservation_transition_allowed(_from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _from = _to THEN false
    WHEN _from <> 'active' THEN false
    WHEN _to IN ('contracted','cancelled','expired','lapsed') THEN true
    ELSE false
  END;
$$;


--
-- Name: builder_is_transaction_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_is_transaction_transition_allowed(_from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _from = _to THEN false
    WHEN _from IN ('settled','cancelled','lapsed') THEN false
    WHEN _to IN ('cancelled','lapsed') THEN true
    WHEN _from = 'lead' THEN _to IN ('reserved','contract_issued')
    WHEN _from = 'reserved' THEN _to IN ('contract_issued','lead')
    WHEN _from = 'contract_issued' THEN _to IN ('contract_signed','reserved')
    WHEN _from = 'contract_signed' THEN _to IN ('unconditional','contract_issued')
    WHEN _from = 'unconditional' THEN _to IN ('construction','practical_completion','settled')
    WHEN _from = 'construction' THEN _to IN ('practical_completion','unconditional')
    WHEN _from = 'practical_completion' THEN _to IN ('settled','construction')
    ELSE false
  END;
$$;


--
-- Name: builder_is_unit_availability_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_is_unit_availability_transition_allowed(_from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _from = _to THEN false
    WHEN _from = 'settled' THEN false
    WHEN _to = 'withdrawn' THEN _from IN ('available','on_hold','reserved')
    WHEN _from = 'withdrawn' THEN _to = 'available'
    WHEN _from = 'available' THEN _to IN ('on_hold','reserved')
    WHEN _from = 'on_hold' THEN _to IN ('available','reserved')
    WHEN _from = 'reserved' THEN _to IN ('available','contracted')
    WHEN _from = 'contracted' THEN _to IN ('settled','available')
    ELSE false
  END;
$$;


--
-- Name: builder_issue_session(uuid, text, timestamp with time zone, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_issue_session(_user_id uuid, _token_hash text, _absolute_expires_at timestamp with time zone, _idle_expires_at timestamp with time zone, _ip_hash text DEFAULT NULL::text, _user_agent_hash text DEFAULT NULL::text, _device_label text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_session_id uuid; v_ok boolean;
BEGIN
  IF _token_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SESSION_TOKEN_NOT_HASHED';
  END IF;

  -- A session may only be issued to an active user who holds at least one
  -- active membership. No membership means no portal access, at the point of
  -- issue as well as at every later authorization check.
  SELECT EXISTS (
    SELECT 1 FROM public.builder_portal_users u
    WHERE u.id = _user_id AND u.is_active AND u.status = 'active' AND u.revoked_at IS NULL
      AND EXISTS (SELECT 1 FROM public.builder_accessible_organisations(u.id))
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SESSION_NOT_PERMITTED';
  END IF;

  INSERT INTO public.builder_portal_sessions(
    builder_user_id, token_hash, absolute_expires_at, idle_expires_at,
    ip_hash, user_agent_hash, device_label)
  VALUES (_user_id, _token_hash, _absolute_expires_at,
          LEAST(_idle_expires_at, _absolute_expires_at),
          _ip_hash, _user_agent_hash, _device_label)
  RETURNING id INTO v_session_id;

  RETURN v_session_id;
END $_$;


--
-- Name: builder_log_activity(uuid, text, text, text, uuid, uuid, uuid, jsonb, jsonb, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_log_activity(_actor_user_id uuid, _actor_type text, _action text, _entity_type text, _entity_id uuid, _organisation_id uuid, _builder_user_id uuid, _previous_state jsonb, _new_state jsonb, _reason text, _metadata jsonb DEFAULT '{}'::jsonb, _ip_address text DEFAULT NULL::text, _user_agent text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.builder_portal_activity_log(
    actor_user_id, actor_type, action, entity_type, entity_id,
    organisation_id, builder_user_id, previous_state, new_state, reason,
    metadata, ip_address, user_agent)
  VALUES (
    _actor_user_id, COALESCE(NULLIF(btrim(_actor_type), ''), 'command_user'),
    _action, _entity_type, _entity_id,
    _organisation_id, _builder_user_id, _previous_state, _new_state, _reason,
    COALESCE(_metadata, '{}'::jsonb), _ip_address, _user_agent)
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'BUILDER_AUDIT_WRITE_FAILED';
  END IF;
  RETURN v_id;
END $$;


--
-- Name: FUNCTION builder_log_activity(_actor_user_id uuid, _actor_type text, _action text, _entity_type text, _entity_id uuid, _organisation_id uuid, _builder_user_id uuid, _previous_state jsonb, _new_state jsonb, _reason text, _metadata jsonb, _ip_address text, _user_agent text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_log_activity(_actor_user_id uuid, _actor_type text, _action text, _entity_type text, _entity_id uuid, _organisation_id uuid, _builder_user_id uuid, _previous_state jsonb, _new_state jsonb, _reason text, _metadata jsonb, _ip_address text, _user_agent text) IS 'Writes a trusted Builder audit record. Raises rather than swallowing, so a caller inside a transaction rolls its mutation back when audit fails.';


--
-- Name: builder_mark_conversation_read(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_mark_conversation_read(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _conversation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.builder_conversations;
BEGIN
  SELECT * INTO c FROM public.builder_conversations WHERE id = _conversation_id;
  IF c.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONVERSATION_NOT_FOUND';
  END IF;

  -- Scoped to the caller's own participation row. A conversation the caller does
  -- not participate in matches nothing, so the watermark cannot be moved for
  -- anyone else.
  UPDATE public.builder_conversation_participants SET last_read_at = now()
  WHERE conversation_id = _conversation_id AND builder_user_id = _actor_builder_user_id
    AND left_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_NOT_A_PARTICIPANT';
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_conversation_read',
    'conversation', _conversation_id, c.organisation_id, _actor_builder_user_id,
    NULL, jsonb_build_object('read_at', now()), NULL, '{}'::jsonb);
  RETURN true;
END $$;


--
-- Name: builder_mark_notifications_read(uuid, text, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_mark_notifications_read(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _notification_ids uuid[] DEFAULT NULL::uuid[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count bigint; v_org uuid;
BEGIN
  IF _actor_builder_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_NOTIFICATION_READER_REQUIRED';
  END IF;

  SELECT organisation_id INTO v_org FROM public.builder_notifications
  WHERE builder_user_id = _actor_builder_user_id
    AND (_notification_ids IS NULL OR id = ANY(_notification_ids)) LIMIT 1;

  UPDATE public.builder_notifications SET read_at = now()
  WHERE builder_user_id = _actor_builder_user_id AND read_at IS NULL
    AND (_notification_ids IS NULL OR id = ANY(_notification_ids));
  GET DIAGNOSTICS v_count = ROW_COUNT;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_notifications_read',
    'notification', NULL, v_org, _actor_builder_user_id,
    NULL, jsonb_build_object('marked_read', v_count), NULL, '{}'::jsonb);
  RETURN v_count;
END $$;


--
-- Name: builder_messages_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_messages_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_MESSAGE_IMMUTABLE',
    DETAIL='messages cannot be edited or deleted';
END $$;


--
-- Name: builder_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    body text NOT NULL,
    author_type text DEFAULT 'builder_user'::text NOT NULL,
    author_builder_user_id uuid,
    author_user_id uuid,
    author_display_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_messages_author_type_check CHECK ((author_type = ANY (ARRAY['builder_user'::text, 'command_user'::text, 'service_role'::text, 'system'::text]))),
    CONSTRAINT builder_messages_body_check CHECK ((length(btrim(body)) > 0))
);


--
-- Name: builder_post_message(uuid, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_post_message(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _conversation_id uuid, _body text, _display_name text DEFAULT NULL::text, _reason text DEFAULT NULL::text) RETURNS public.builder_messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.builder_conversations; v_row public.builder_messages;
BEGIN
  IF NULLIF(btrim(COALESCE(_body,'')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_MESSAGE_BODY_REQUIRED';
  END IF;
  SELECT * INTO c FROM public.builder_conversations WHERE id = _conversation_id FOR UPDATE;
  IF c.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONVERSATION_NOT_FOUND';
  END IF;
  IF c.status = 'archived' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONVERSATION_ARCHIVED';
  END IF;

  INSERT INTO public.builder_messages(conversation_id, body, author_type,
    author_builder_user_id, author_user_id, author_display_name)
  VALUES (_conversation_id, _body, _actor_type, _actor_builder_user_id, _actor_user_id,
    _display_name)
  RETURNING * INTO v_row;

  UPDATE public.builder_conversations
  SET last_message_at = v_row.created_at, message_count = message_count + 1
  WHERE id = _conversation_id;

  -- The author's own watermark advances so their own message is not unread.
  IF _actor_builder_user_id IS NOT NULL THEN
    UPDATE public.builder_conversation_participants SET last_read_at = v_row.created_at
    WHERE conversation_id = _conversation_id AND builder_user_id = _actor_builder_user_id;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_message_posted',
    'message', v_row.id, c.organisation_id, _actor_builder_user_id,
    NULL, jsonb_build_object('conversation_id', _conversation_id),
    _reason, '{}'::jsonb);
  RETURN v_row;
END $$;


--
-- Name: builder_prevent_project_access_org_drift(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_prevent_project_access_org_drift() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.developer_organisation_id IS NOT DISTINCT FROM OLD.developer_organisation_id
     AND NEW.builder_organisation_id IS NOT DISTINCT FROM OLD.builder_organisation_id THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.builder_project_access
    WHERE project_id = OLD.id AND revoked_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='BUILDER_PROJECT_ACCESS_ORG_DRIFT',
      DETAIL='revoke active project access before changing a project organisation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: builder_project_status_history_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_project_status_history_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION USING ERRCODE='P0001',
    MESSAGE='BUILDER_PROJECT_STATUS_HISTORY_APPEND_ONLY',
    DETAIL='builder_project_status_history rows cannot be updated or deleted';
END $$;


--
-- Name: builder_register_uploaded_document_version(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_register_uploaded_document_version(_document_version_id uuid, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_type text DEFAULT 'builder_user'::text) RETURNS public.builder_document_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v public.builder_document_versions; v_org uuid;
BEGIN
  SELECT * INTO v FROM public.builder_document_versions
  WHERE id = _document_version_id FOR UPDATE;
  IF v.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_VERSION_NOT_FOUND';
  END IF;
  IF v.lifecycle_status NOT IN ('upload_pending','quarantined') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_INVALID_STATE',
      DETAIL = format('lifecycle_status=%s', v.lifecycle_status);
  END IF;

  UPDATE public.builder_document_versions
  SET lifecycle_status = 'quarantined',
      malware_scan_status = 'pending',
      uploaded_at = COALESCE(uploaded_at, now())
  WHERE id = v.id
  RETURNING * INTO v;

  -- Idempotent: re-registering the same version does not queue it twice.
  INSERT INTO public.document_processing_jobs(portal, builder_document_version_id, document_version_id)
  VALUES ('builder', v.id, NULL)
  ON CONFLICT DO NOTHING;

  SELECT organisation_id INTO v_org FROM public.builder_documents WHERE id = v.document_id;

  PERFORM public.builder_log_activity(
    NULL, _actor_type, 'builder_document_version_quarantined',
    'document_version', v.id, v_org, _actor_builder_user_id,
    NULL,
    jsonb_build_object('lifecycle_status', v.lifecycle_status,
                       'malware_scan_status', v.malware_scan_status),
    NULL, jsonb_build_object('document_id', v.document_id));

  RETURN v;
END $$;


--
-- Name: builder_release_allocation(uuid, text, uuid, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_release_allocation(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _allocation_id uuid, _expected_version bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_allocations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_allocations; v_row public.builder_allocations;
        v_project uuid; v_org uuid;
BEGIN
  SELECT * INTO v_existing FROM public.builder_allocations WHERE id = _allocation_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ALLOCATION_NOT_FOUND'; END IF;
  IF v_existing.status <> 'active' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ALLOCATION_NOT_ACTIVE'; END IF;
  IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_existing.row_version); END IF;

  UPDATE public.builder_allocations
  SET status='released', released_at=now(), released_reason=_reason
  WHERE id = v_existing.id RETURNING * INTO v_row;

  SELECT project_id INTO v_project FROM public.builder_units WHERE id = v_row.unit_id;
  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = v_project;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_allocation_released',
    'allocation', v_row.id, v_org, _actor_builder_user_id,
    jsonb_build_object('status', v_existing.status), jsonb_build_object('status', v_row.status),
    _reason, jsonb_build_object('unit_id', v_row.unit_id));
  RETURN v_row;
END $$;


--
-- Name: builder_release_unit_hold(uuid, text, uuid, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_release_unit_hold(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _hold_id uuid, _expected_version bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_unit_holds
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_unit_holds; v_row public.builder_unit_holds;
        u public.builder_units; v_org uuid;
BEGIN
  SELECT * INTO v_existing FROM public.builder_unit_holds WHERE id = _hold_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_HOLD_NOT_FOUND'; END IF;
  IF v_existing.status <> 'active' THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_HOLD_NOT_ACTIVE'; END IF;
  IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_existing.row_version); END IF;

  UPDATE public.builder_unit_holds
  SET status='released', released_at=now(), released_reason=_reason
  WHERE id = v_existing.id RETURNING * INTO v_row;

  SELECT * INTO u FROM public.builder_units WHERE id = v_row.unit_id FOR UPDATE;
  IF u.availability_status = 'on_hold' THEN
    PERFORM public.builder_transition_unit_availability(
      u.id, u.row_version, 'on_hold', 'available',
      COALESCE(_reason, 'Hold released'), _actor_type, _actor_builder_user_id, _actor_user_id);
  END IF;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = u.project_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_unit_hold_released',
    'unit_hold', v_row.id, v_org, _actor_builder_user_id,
    jsonb_build_object('status', v_existing.status),
    jsonb_build_object('status', v_row.status),
    _reason, jsonb_build_object('unit_id', v_row.unit_id));
  RETURN v_row;
END $$;


--
-- Name: builder_resolve_construction_permission(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_resolve_construction_permission(_user_id uuid, _construction_case_id uuid, _permission_key text DEFAULT 'construction'::text, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_transaction_id uuid; v_project_id uuid; v_org uuid;
  v_base boolean; v_membership_id uuid; v_scoped text;
BEGIN
  SELECT transaction_id, project_id INTO v_transaction_id, v_project_id
  FROM public.builder_construction_cases WHERE id = _construction_case_id;
  IF v_project_id IS NULL THEN RETURN false; END IF;

  -- The project decision is authoritative for the construction key.
  v_base := public.builder_resolve_project_permission(
    _user_id, v_project_id, _permission_key, _level);
  IF NOT v_base THEN RETURN false; END IF;

  -- A denial on the parent TRANSACTION also denies its construction case: the
  -- build cannot be a way around a denial on the sale it fulfils.
  IF NOT public.builder_resolve_transaction_permission(
       _user_id, v_transaction_id, 'transactions', 'view') THEN
    RETURN false;
  END IF;

  SELECT a.organisation_id INTO v_org FROM public.builder_project_access a
  WHERE a.builder_user_id = _user_id AND a.project_id = v_project_id
    AND a.revoked_at IS NULL;
  IF v_org IS NULL THEN RETURN false; END IF;

  -- HARD GATE: an active membership is required BEFORE any override runs.
  SELECT membership_id INTO v_membership_id
  FROM public.builder_active_membership(_user_id, v_org);
  IF v_membership_id IS NULL THEN RETURN false; END IF;

  SELECT CASE _level WHEN 'view' THEN view_decision
                    WHEN 'edit' THEN edit_decision ELSE delete_decision END
  INTO v_scoped FROM public.builder_membership_permissions
  WHERE membership_id = v_membership_id AND permission_key = _permission_key
    AND scope_type = 'construction_case' AND scope_id = _construction_case_id;
  IF v_scoped = 'deny' THEN RETURN false; END IF;

  RETURN true;
END $$;


--
-- Name: builder_resolve_permission(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_resolve_permission(_user_id uuid, _org_id uuid, _permission_key text, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_membership_id uuid;
  v_role text;
  v_forbidden boolean;
  v_kind text;
  v_baseline boolean := false;
  v_override text;
BEGIN
  IF _level NOT IN ('view','edit','delete') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_PERMISSION_LEVEL';
  END IF;

  -- 1. Forbidden keys are denied before anything else is consulted. An unknown
  --    key is also denied: deny by default extends to typos.
  SELECT is_forbidden, key_kind INTO v_forbidden, v_kind
  FROM public.builder_permission_keys WHERE permission_key = _permission_key;
  IF v_forbidden IS NULL OR v_forbidden THEN
    RETURN false;
  END IF;

  -- 2. Inbound projections are never writable.
  IF v_kind = 'inbound_projection' AND _level <> 'view' THEN
    RETURN false;
  END IF;

  -- 3. No active membership means no access. This is also the cross-organisation
  --    boundary: a user asking about an organisation they do not belong to
  --    resolves no membership and is denied.
  SELECT membership_id, membership_role INTO v_membership_id, v_role
  FROM public.builder_active_membership(_user_id, _org_id);
  IF v_membership_id IS NULL THEN
    RETURN false;
  END IF;

  -- 4. Role default supplies the baseline. Unconfigured resolves to false.
  SELECT CASE _level WHEN 'view' THEN can_view WHEN 'edit' THEN can_edit ELSE can_delete END
  INTO v_baseline
  FROM public.builder_role_default_permissions
  WHERE membership_role = v_role AND permission_key = _permission_key;
  v_baseline := COALESCE(v_baseline, false);

  -- 5. Membership override refines the baseline. An explicit deny always wins;
  --    an explicit allow can raise a false baseline. 'inherit' falls through.
  SELECT CASE _level WHEN 'view' THEN view_decision WHEN 'edit' THEN edit_decision ELSE delete_decision END
  INTO v_override
  FROM public.builder_membership_permissions
  WHERE membership_id = v_membership_id
    AND permission_key = _permission_key
    AND scope_type = 'organisation';

  IF v_override = 'deny' THEN
    RETURN false;
  ELSIF v_override = 'allow' THEN
    v_baseline := true;
  END IF;

  -- 6. read_only clamps write levels last, after every other decision.
  IF v_role = 'read_only' AND _level <> 'view' THEN
    RETURN false;
  END IF;

  RETURN v_baseline;
END $$;


--
-- Name: FUNCTION builder_resolve_permission(_user_id uuid, _org_id uuid, _permission_key text, _level text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_resolve_permission(_user_id uuid, _org_id uuid, _permission_key text, _level text) IS 'Deny-by-default Builder permission resolution. Forbidden keys are denied first; an unknown key is denied; no active membership is denied; an unconfigured key is denied; an explicit membership deny overrides a role allow; read_only clamps edit and delete.';


--
-- Name: builder_resolve_project_permission(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_resolve_project_permission(_user_id uuid, _project_id uuid, _permission_key text, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_access public.builder_project_access;
  v_baseline boolean;
  v_override text;
  v_membership_id uuid;
  v_scoped text;
BEGIN
  IF _level NOT IN ('view','edit','delete') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_PERMISSION_LEVEL';
  END IF;

  -- 1. An explicit, live, in-window grant is required. No grant, no access —
  --    this is the whole boundary, and it is checked before anything else.
  SELECT * INTO v_access FROM public.builder_project_access
  WHERE builder_user_id = _user_id AND project_id = _project_id
    AND revoked_at IS NULL
    AND valid_from <= now()
    AND (valid_until IS NULL OR valid_until > now());
  IF v_access.id IS NULL THEN
    RETURN false;
  END IF;

  -- 2. HARD GATE: an active membership of the granting organisation is
  --    required, and it is resolved BEFORE any override can run.
  --
  --    builder_resolve_permission already returns false without one, but that is
  --    only a baseline: steps 3 and 4 below can raise a false baseline back to
  --    true with an explicit 'allow'. A revoked membership would then still
  --    reach the project through a stored override. Returning here means no
  --    override of any kind can restore access to a user whose membership is
  --    inactive, revoked or absent.
  SELECT membership_id INTO v_membership_id
  FROM public.builder_active_membership(_user_id, v_access.organisation_id);
  IF v_membership_id IS NULL THEN
    RETURN false;
  END IF;

  -- 3. The organisation baseline, resolved by the Phase 1 function. It denies
  --    forbidden keys, re-checks the membership and clamps read_only.
  v_baseline := public.builder_resolve_permission(
    _user_id, v_access.organisation_id, _permission_key, _level);

  -- 4. Project-scoped membership override from the Phase 1 seam. Reachable only
  --    because step 2 has already proven the membership is active.
  SELECT CASE _level WHEN 'view' THEN view_decision
                    WHEN 'edit' THEN edit_decision
                    ELSE delete_decision END
  INTO v_scoped
  FROM public.builder_membership_permissions
  WHERE membership_id = v_membership_id
    AND permission_key = _permission_key
    AND scope_type = 'project'
    AND scope_id = _project_id;
  IF v_scoped = 'deny' THEN
    RETURN false;
  ELSIF v_scoped = 'allow' THEN
    v_baseline := true;
  END IF;

  -- 5. The grant's own tri-state override. Explicit deny wins; explicit allow
  --    can raise a false baseline; inherit falls through.
  v_override := v_access.permissions #>> ARRAY[_permission_key, _level];
  IF v_override = 'deny' THEN
    RETURN false;
  ELSIF v_override = 'allow' THEN
    v_baseline := true;
  END IF;

  -- 6. A forbidden key can never be raised by a project grant. Re-asserted here
  --    because steps 4 and 5 can set the baseline true.
  IF EXISTS (
    SELECT 1 FROM public.builder_permission_keys
    WHERE permission_key = _permission_key AND is_forbidden
  ) OR NOT EXISTS (
    SELECT 1 FROM public.builder_permission_keys WHERE permission_key = _permission_key
  ) THEN
    RETURN false;
  END IF;

  -- 7. read_only on the grant clamps writes last, mirroring
  --    resolveMatterPermissions()'s read_only clamp.
  IF v_access.access_role = 'read_only' AND _level <> 'view' THEN
    RETURN false;
  END IF;

  RETURN COALESCE(v_baseline, false);
END $$;


--
-- Name: builder_resolve_scope_permission(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_resolve_scope_permission(_user_id uuid, _scope_type text, _scope_id uuid, _permission_key text DEFAULT 'documents'::text, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN CASE _scope_type
    WHEN 'project' THEN
      public.builder_resolve_project_permission(_user_id, _scope_id, _permission_key, _level)
    WHEN 'unit' THEN
      public.builder_resolve_unit_permission(_user_id, _scope_id, _permission_key, _level)
    WHEN 'transaction' THEN
      public.builder_resolve_transaction_permission(_user_id, _scope_id, _permission_key, _level)
    WHEN 'construction_case' THEN
      public.builder_resolve_construction_permission(_user_id, _scope_id, _permission_key, _level)
    ELSE false
  END;
END $$;


--
-- Name: builder_resolve_session(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_resolve_session(_token_hash text, _idle_minutes integer DEFAULT 30) RETURNS TABLE(session_id uuid, builder_user_id uuid, absolute_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_row record; v_new_idle timestamptz;
BEGIN
  IF _token_hash IS NULL OR _token_hash !~ '^[0-9a-f]{64}$' THEN
    RETURN;
  END IF;

  SELECT s.id, s.builder_user_id, s.absolute_expires_at, s.idle_expires_at
  INTO v_row
  FROM public.builder_portal_sessions s
  WHERE s.token_hash = _token_hash AND s.revoked_at IS NULL;

  IF v_row.id IS NULL THEN RETURN; END IF;
  IF v_row.absolute_expires_at <= now() OR v_row.idle_expires_at <= now() THEN RETURN; END IF;

  v_new_idle := LEAST(now() + make_interval(mins => GREATEST(_idle_minutes, 1)),
                      v_row.absolute_expires_at);

  -- The revoked_at re-check inside the UPDATE closes the race between a
  -- concurrent revoke and an in-flight request: if the revoke landed first, no
  -- row is updated and the session does not resolve.
  UPDATE public.builder_portal_sessions s
  SET last_used_at = now(), idle_expires_at = v_new_idle
  WHERE s.id = v_row.id AND s.revoked_at IS NULL
  RETURNING s.id, s.builder_user_id, s.absolute_expires_at
  INTO session_id, builder_user_id, absolute_expires_at;

  IF session_id IS NULL THEN RETURN; END IF;

  -- The user and at least one membership must still be live. A user whose last
  -- membership was revoked loses portal access immediately, without waiting for
  -- the session to expire.
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_portal_users u
    WHERE u.id = builder_resolve_session.builder_user_id
      AND u.is_active AND u.status = 'active' AND u.revoked_at IS NULL
      AND EXISTS (SELECT 1 FROM public.builder_accessible_organisations(u.id))
  ) THEN
    session_id := NULL; builder_user_id := NULL; absolute_expires_at := NULL;
    RETURN;
  END IF;

  RETURN NEXT;
END $_$;


--
-- Name: builder_resolve_transaction_permission(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_resolve_transaction_permission(_user_id uuid, _transaction_id uuid, _permission_key text, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_project_id uuid; v_unit_id uuid; v_org uuid;
  v_base boolean; v_membership_id uuid; v_scoped text;
BEGIN
  SELECT project_id, unit_id INTO v_project_id, v_unit_id
  FROM public.builder_transactions WHERE id = _transaction_id;
  IF v_project_id IS NULL THEN RETURN false; END IF;

  v_base := public.builder_resolve_project_permission(
    _user_id, v_project_id, _permission_key, _level);
  IF NOT v_base THEN RETURN false; END IF;

  SELECT a.organisation_id INTO v_org FROM public.builder_project_access a
  WHERE a.builder_user_id = _user_id AND a.project_id = v_project_id
    AND a.revoked_at IS NULL;
  IF v_org IS NULL THEN RETURN false; END IF;

  -- HARD GATE: an active membership of the granting organisation is required,
  -- and it is resolved BEFORE any override can run.
  SELECT membership_id INTO v_membership_id
  FROM public.builder_active_membership(_user_id, v_org);
  IF v_membership_id IS NULL THEN RETURN false; END IF;

  -- The unit-scoped override still applies: a transaction cannot be a way
  -- around a denial on the unit it sells.
  IF v_unit_id IS NOT NULL THEN
    SELECT CASE _level WHEN 'view' THEN view_decision
                      WHEN 'edit' THEN edit_decision ELSE delete_decision END
    INTO v_scoped FROM public.builder_membership_permissions
    WHERE membership_id = v_membership_id AND permission_key = _permission_key
      AND scope_type = 'unit' AND scope_id = v_unit_id;
    IF v_scoped = 'deny' THEN RETURN false; END IF;
  END IF;

  SELECT CASE _level WHEN 'view' THEN view_decision
                    WHEN 'edit' THEN edit_decision ELSE delete_decision END
  INTO v_scoped FROM public.builder_membership_permissions
  WHERE membership_id = v_membership_id AND permission_key = _permission_key
    AND scope_type = 'transaction' AND scope_id = _transaction_id;
  IF v_scoped = 'deny' THEN RETURN false; END IF;

  RETURN true;
END $$;


--
-- Name: builder_resolve_unit_permission(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_resolve_unit_permission(_user_id uuid, _unit_id uuid, _permission_key text, _level text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_project_id uuid; v_stage_id uuid; v_org uuid;
  v_base boolean; v_membership_id uuid; v_scoped text;
BEGIN
  SELECT project_id, stage_id INTO v_project_id, v_stage_id
  FROM public.builder_units WHERE id = _unit_id;
  IF v_project_id IS NULL THEN RETURN false; END IF;

  -- The parent decision is authoritative. If the project denies, the unit
  -- denies — a unit-scoped allow can never open a project the user cannot see.
  v_base := public.builder_resolve_project_permission(
    _user_id, v_project_id, _permission_key, _level);
  IF NOT v_base THEN RETURN false; END IF;

  -- The membership is already proven by the parent, but it is re-read here
  -- because the scoped override below is keyed on the membership id.
  SELECT a.organisation_id INTO v_org FROM public.builder_project_access a
  WHERE a.builder_user_id = _user_id AND a.project_id = v_project_id
    AND a.revoked_at IS NULL;
  IF v_org IS NULL THEN RETURN false; END IF;

  SELECT membership_id INTO v_membership_id
  FROM public.builder_active_membership(_user_id, v_org);
  IF v_membership_id IS NULL THEN RETURN false; END IF;

  -- Stage-scoped override, then unit-scoped. Each may only DENY: a narrower
  -- scope must not be able to grant what the parent withheld, and the parent
  -- has already returned true to reach this point.
  IF v_stage_id IS NOT NULL THEN
    SELECT CASE _level WHEN 'view' THEN view_decision
                      WHEN 'edit' THEN edit_decision ELSE delete_decision END
    INTO v_scoped FROM public.builder_membership_permissions
    WHERE membership_id = v_membership_id AND permission_key = _permission_key
      AND scope_type = 'stage' AND scope_id = v_stage_id;
    IF v_scoped = 'deny' THEN RETURN false; END IF;
  END IF;

  SELECT CASE _level WHEN 'view' THEN view_decision
                    WHEN 'edit' THEN edit_decision ELSE delete_decision END
  INTO v_scoped FROM public.builder_membership_permissions
  WHERE membership_id = v_membership_id AND permission_key = _permission_key
    AND scope_type = 'unit' AND scope_id = _unit_id;
  IF v_scoped = 'deny' THEN RETURN false; END IF;

  RETURN true;
END $$;


--
-- Name: builder_revoke_session(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_revoke_session(_session_id uuid, _reason text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH revoked AS (
    UPDATE public.builder_portal_sessions
    SET revoked_at = now(), revoked_reason = COALESCE(NULLIF(btrim(_reason), ''), 'revoked')
    WHERE id = _session_id AND revoked_at IS NULL
    RETURNING id)
  SELECT EXISTS (SELECT 1 FROM revoked);
$$;


--
-- Name: builder_revoke_sessions_on_membership_loss(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_revoke_sessions_on_membership_loss() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (NEW.revoked_at IS NOT NULL AND OLD.revoked_at IS NULL)
     OR (NEW.status <> 'active' AND OLD.status = 'active') THEN
    IF NOT EXISTS (SELECT 1 FROM public.builder_accessible_organisations(NEW.builder_user_id)) THEN
      PERFORM public.builder_revoke_user_sessions(
        NEW.builder_user_id, 'membership_revoked');
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: builder_revoke_sessions_on_user_deactivation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_revoke_sessions_on_user_deactivation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status <> 'active' AND OLD.status = 'active' THEN
    PERFORM public.builder_revoke_user_sessions(NEW.id, 'user_' || NEW.status);
  ELSIF NEW.password_changed_at IS DISTINCT FROM OLD.password_changed_at
        AND NEW.password_changed_at IS NOT NULL THEN
    PERFORM public.builder_revoke_user_sessions(NEW.id, 'password_changed');
  END IF;
  RETURN NEW;
END $$;


--
-- Name: builder_revoke_user_sessions(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_revoke_user_sessions(_user_id uuid, _reason text, _except_session_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH revoked AS (
    UPDATE public.builder_portal_sessions
    SET revoked_at = now(), revoked_reason = COALESCE(NULLIF(btrim(_reason), ''), 'revoked')
    WHERE builder_user_id = _user_id
      AND revoked_at IS NULL
      AND (_except_session_id IS NULL OR id <> _except_session_id)
    RETURNING id)
  SELECT count(*)::integer FROM revoked;
$$;


--
-- Name: FUNCTION builder_revoke_user_sessions(_user_id uuid, _reason text, _except_session_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_revoke_user_sessions(_user_id uuid, _reason text, _except_session_id uuid) IS 'Revokes every live Builder session for a user. Called on password reset, password change, membership revocation and account suspension.';


--
-- Name: builder_rollout_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_rollout_transition_allowed(_from text, _to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _to = 'rollback' THEN _from IN ('shadow','cutover')
    WHEN _from = 'off'      AND _to = 'shadow'  THEN true
    WHEN _from = 'shadow'   AND _to = 'cutover' THEN true
    WHEN _from = 'shadow'   AND _to = 'off'     THEN true
    WHEN _from = 'rollback' AND _to = 'shadow'  THEN true
    WHEN _from = 'rollback' AND _to = 'off'     THEN true
    ELSE false
  END;
$$;


--
-- Name: FUNCTION builder_rollout_transition_allowed(_from text, _to text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.builder_rollout_transition_allowed(_from text, _to text) IS 'Builder rollout transition graph. dual_read and dual_write are deliberately unreachable: Builder is greenfield and has no legacy path to compare against.';


--
-- Name: builder_scope_exists(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_scope_exists(_scope_type text, _scope_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN CASE _scope_type
    WHEN 'project' THEN EXISTS (SELECT 1 FROM public.builder_projects WHERE id = _scope_id)
    WHEN 'unit' THEN EXISTS (SELECT 1 FROM public.builder_units WHERE id = _scope_id)
    WHEN 'transaction' THEN EXISTS (SELECT 1 FROM public.builder_transactions WHERE id = _scope_id)
    WHEN 'construction_case' THEN
      EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _scope_id)
    ELSE false
  END;
END $$;


--
-- Name: builder_scope_org(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_scope_org(_scope_type text, _scope_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF _scope_type = 'project' THEN
    SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
    FROM public.builder_projects WHERE id = _scope_id;
  ELSIF _scope_type = 'unit' THEN
    SELECT COALESCE(p.developer_organisation_id, p.builder_organisation_id) INTO v_org
    FROM public.builder_units u JOIN public.builder_projects p ON p.id = u.project_id
    WHERE u.id = _scope_id;
  ELSIF _scope_type = 'transaction' THEN
    SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = _scope_id;
  ELSIF _scope_type = 'construction_case' THEN
    SELECT t.organisation_id INTO v_org
    FROM public.builder_construction_cases c
    JOIN public.builder_transactions t ON t.id = c.transaction_id
    WHERE c.id = _scope_id;
  END IF;
  RETURN v_org;
END $$;


--
-- Name: builder_select_session_organisation(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_select_session_organisation(_session_id uuid, _builder_user_id uuid, _organisation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_previous uuid; v_updated uuid;
BEGIN
  SELECT active_organisation_id INTO v_previous
  FROM public.builder_portal_sessions
  WHERE id = _session_id AND builder_user_id = _builder_user_id AND revoked_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SESSION_NOT_FOUND';
  END IF;

  -- The trigger enforces this too; raising here gives the Edge Function a
  -- specific error to map onto 403 rather than a generic constraint failure.
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_accessible_organisations(_builder_user_id) a
    WHERE a.organisation_id = _organisation_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORGANISATION_NOT_ACCESSIBLE';
  END IF;

  UPDATE public.builder_portal_sessions
  SET active_organisation_id = _organisation_id
  WHERE id = _session_id AND builder_user_id = _builder_user_id AND revoked_at IS NULL
  RETURNING active_organisation_id INTO v_updated;

  PERFORM public.builder_log_activity(
    NULL, 'builder_user', 'builder_active_organisation_selected',
    'session', _session_id, _organisation_id, _builder_user_id,
    jsonb_build_object('active_organisation_id', v_previous),
    jsonb_build_object('active_organisation_id', v_updated),
    NULL, '{}'::jsonb);

  RETURN v_updated;
END $$;


--
-- Name: builder_construction_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_construction_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    transaction_id uuid NOT NULL,
    project_id uuid NOT NULL,
    unit_id uuid,
    case_reference text,
    status text DEFAULT 'not_started'::text NOT NULL,
    site_supervisor_name text,
    site_supervisor_email text,
    site_supervisor_phone text,
    site_start_date date,
    estimated_completion_date date,
    actual_completion_date date,
    practical_completion_date date,
    percent_complete numeric(5,2) DEFAULT 0 NOT NULL,
    shared_summary text,
    builder_notes text,
    weather_delay_days integer DEFAULT 0 NOT NULL,
    variation_delay_days integer DEFAULT 0 NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_construction_cases_completion_order CHECK (((actual_completion_date IS NULL) OR (site_start_date IS NULL) OR (actual_completion_date >= site_start_date))),
    CONSTRAINT builder_construction_cases_percent_complete_check CHECK (((percent_complete >= (0)::numeric) AND (percent_complete <= (100)::numeric))),
    CONSTRAINT builder_construction_cases_status_check CHECK ((status = ANY (ARRAY['not_started'::text, 'site_preparation'::text, 'under_construction'::text, 'on_hold'::text, 'practical_completion'::text, 'handover'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT builder_construction_cases_variation_delay_days_check CHECK ((variation_delay_days >= 0)),
    CONSTRAINT builder_construction_cases_weather_delay_days_check CHECK ((weather_delay_days >= 0))
);


--
-- Name: TABLE builder_construction_cases; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_construction_cases IS 'The build programme for one transaction. Holds dates, progress and site contacts only: no build cost, margin, supplier price, contractor price or payment information.';


--
-- Name: builder_set_construction_date(uuid, text, uuid, uuid, text, date, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_set_construction_date(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _construction_case_id uuid, _date_kind text, _new_date date, _expected_version bigint, _reason text) RETURNS public.builder_construction_cases
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_construction_cases; v_row public.builder_construction_cases;
        v_from date; v_org uuid;
BEGIN
  IF NULLIF(btrim(COALESCE(_reason,'')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;
  IF _date_kind NOT IN ('site_start','estimated_completion','practical_completion','actual_completion') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_DATE_KIND';
  END IF;

  SELECT * INTO v_existing FROM public.builder_construction_cases
  WHERE id = _construction_case_id FOR UPDATE;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
  END IF;
  IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
      DETAIL = format('current_version=%s', v_existing.row_version);
  END IF;

  v_from := CASE _date_kind
    WHEN 'site_start' THEN v_existing.site_start_date
    WHEN 'estimated_completion' THEN v_existing.estimated_completion_date
    WHEN 'practical_completion' THEN v_existing.practical_completion_date
    ELSE v_existing.actual_completion_date END;

  UPDATE public.builder_construction_cases SET
    site_start_date = CASE WHEN _date_kind='site_start' THEN _new_date ELSE site_start_date END,
    estimated_completion_date = CASE WHEN _date_kind='estimated_completion' THEN _new_date ELSE estimated_completion_date END,
    practical_completion_date = CASE WHEN _date_kind='practical_completion' THEN _new_date ELSE practical_completion_date END,
    actual_completion_date = CASE WHEN _date_kind='actual_completion' THEN _new_date ELSE actual_completion_date END
  WHERE id = v_existing.id RETURNING * INTO v_row;

  INSERT INTO public.builder_construction_date_history(construction_case_id, date_kind,
    from_date, to_date, reason, changed_by_type, changed_by_builder_user_id, changed_by_user_id)
  VALUES (_construction_case_id, _date_kind, v_from, _new_date, left(btrim(_reason),1000),
    _actor_type, _actor_builder_user_id, _actor_user_id);

  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = v_row.transaction_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_construction_date_changed',
    'construction_case', v_row.id, v_org, _actor_builder_user_id,
    jsonb_build_object('date_kind', _date_kind, 'from', v_from),
    jsonb_build_object('date_kind', _date_kind, 'to', _new_date,
                       'row_version', v_row.row_version),
    left(btrim(_reason),1000), '{}'::jsonb);
  RETURN v_row;
END $$;


--
-- Name: builder_document_grants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_document_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id uuid NOT NULL,
    builder_user_id uuid NOT NULL,
    can_download boolean DEFAULT true NOT NULL,
    granted_by_user_id uuid,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revocation_reason text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE builder_document_grants; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_document_grants IS 'A restriction, not a widening. The scope resolver is consulted first; a grant can only narrow a document to the named users.';


--
-- Name: builder_set_document_grant(uuid, text, uuid, uuid, uuid, boolean, boolean, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_set_document_grant(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _document_id uuid, _builder_user_id uuid, _can_download boolean, _revoke boolean DEFAULT false, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_document_grants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE d public.builder_documents; v_existing public.builder_document_grants;
        v_row public.builder_document_grants;
BEGIN
  SELECT * INTO d FROM public.builder_documents WHERE id = _document_id;
  IF d.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_NOT_FOUND';
  END IF;

  SELECT * INTO v_existing FROM public.builder_document_grants
  WHERE document_id = _document_id AND builder_user_id = _builder_user_id FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_document_grants SET
      can_download = _can_download,
      revoked_at = CASE WHEN _revoke THEN COALESCE(revoked_at, now()) ELSE NULL END,
      revocation_reason = CASE WHEN _revoke THEN _reason ELSE NULL END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _revoke THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_GRANT_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_document_grants(document_id, builder_user_id, can_download,
      granted_by_user_id)
    VALUES (_document_id, _builder_user_id, _can_download, _actor_user_id)
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _revoke THEN 'builder_document_grant_revoked' ELSE 'builder_document_grant_set' END,
    'document_grant', v_row.id, d.organisation_id, _actor_builder_user_id,
    CASE WHEN v_existing.id IS NULL THEN NULL
         ELSE jsonb_build_object('revoked_at', v_existing.revoked_at) END,
    jsonb_build_object('builder_user_id', v_row.builder_user_id,
                       'can_download', v_row.can_download,
                       'revoked_at', v_row.revoked_at, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('document_id', _document_id));
  RETURN v_row;
END $$;


--
-- Name: builder_task_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_task_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    task_id uuid NOT NULL,
    builder_user_id uuid NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_by_builder_user_id uuid,
    unassigned_at timestamp with time zone,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: builder_set_task_assignment(uuid, text, uuid, uuid, uuid, boolean, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_set_task_assignment(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _task_id uuid, _builder_user_id uuid, _unassign boolean DEFAULT false, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_task_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.builder_tasks; v_existing public.builder_task_assignments;
        v_row public.builder_task_assignments;
BEGIN
  SELECT * INTO t FROM public.builder_tasks WHERE id = _task_id;
  IF t.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TASK_NOT_FOUND';
  END IF;

  SELECT * INTO v_existing FROM public.builder_task_assignments
  WHERE task_id = _task_id AND builder_user_id = _builder_user_id FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_task_assignments SET
      unassigned_at = CASE WHEN _unassign THEN COALESCE(unassigned_at, now()) ELSE NULL END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _unassign THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ASSIGNMENT_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_task_assignments(task_id, builder_user_id,
      assigned_by_builder_user_id)
    VALUES (_task_id, _builder_user_id, _actor_builder_user_id)
    RETURNING * INTO v_row;

    -- Assignment raises a notification for the assignee. It is a POINTER: it
    -- carries the task title only, never its contents.
    INSERT INTO public.builder_notifications(builder_user_id, organisation_id,
      notification_type, title, body, scope_type, scope_id, entity_kind, entity_id)
    VALUES (_builder_user_id, t.organisation_id, 'task_assigned',
      'You were assigned a task', t.title, t.scope_type, t.scope_id, 'task', t.id);
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _unassign THEN 'builder_task_unassigned' ELSE 'builder_task_assigned' END,
    'task_assignment', v_row.id, t.organisation_id, _actor_builder_user_id,
    CASE WHEN v_existing.id IS NULL THEN NULL
         ELSE jsonb_build_object('unassigned_at', v_existing.unassigned_at) END,
    jsonb_build_object('builder_user_id', v_row.builder_user_id,
                       'unassigned_at', v_row.unassigned_at,
                       'row_version', v_row.row_version),
    _reason, jsonb_build_object('task_id', _task_id));
  RETURN v_row;
END $$;


--
-- Name: builder_unit_pricing; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_unit_pricing (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    list_price numeric(14,2) NOT NULL,
    price_basis text DEFAULT 'fixed'::text NOT NULL,
    effective_from timestamp with time zone DEFAULT now() NOT NULL,
    effective_to timestamp with time zone,
    is_current boolean DEFAULT true NOT NULL,
    reason text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_unit_pricing_list_price_check CHECK ((list_price >= (0)::numeric)),
    CONSTRAINT builder_unit_pricing_price_basis_check CHECK ((price_basis = ANY (ARRAY['fixed'::text, 'from'::text, 'indicative'::text, 'on_application'::text]))),
    CONSTRAINT builder_unit_pricing_window_valid CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);


--
-- Name: TABLE builder_unit_pricing; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_unit_pricing IS 'Customer-facing list price history. Deliberately holds NO cost, margin, supplier or contractor price — those are internal Builder commercial information.';


--
-- Name: builder_set_unit_price(uuid, text, uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_set_unit_price(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _unit_id uuid, _list_price numeric, _price_basis text DEFAULT 'fixed'::text, _reason text DEFAULT NULL::text) RETURNS public.builder_unit_pricing
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_previous public.builder_unit_pricing; v_row public.builder_unit_pricing; v_org uuid; v_project uuid;
BEGIN
  SELECT project_id INTO v_project FROM public.builder_units WHERE id = _unit_id;
  IF v_project IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_FOUND';
  END IF;
  IF _list_price IS NULL OR _list_price < 0 THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_PRICE';
  END IF;
  IF _price_basis NOT IN ('fixed','from','indicative','on_application') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_PRICE_BASIS';
  END IF;

  -- Close the current price rather than editing it: price history is evidence.
  SELECT * INTO v_previous FROM public.builder_unit_pricing
  WHERE unit_id = _unit_id AND is_current FOR UPDATE;
  IF v_previous.id IS NOT NULL THEN
    UPDATE public.builder_unit_pricing
    SET is_current = false, effective_to = now()
    WHERE id = v_previous.id;
  END IF;

  INSERT INTO public.builder_unit_pricing(unit_id, list_price, price_basis, reason)
  VALUES (_unit_id, _list_price, _price_basis, _reason)
  RETURNING * INTO v_row;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = v_project;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_unit_price_set',
    'unit_price', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN v_previous.id IS NULL THEN NULL
         ELSE jsonb_build_object('list_price', v_previous.list_price) END,
    jsonb_build_object('list_price', v_row.list_price, 'price_basis', v_row.price_basis),
    _reason, jsonb_build_object('unit_id', _unit_id));
  RETURN v_row;
END $$;


--
-- Name: builder_stock_image_work_pending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_stock_image_work_pending() RETURNS TABLE(claimable bigint, outstanding bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    count(*) FILTER (
      WHERE i.image_work_next_attempt_at <= now()
        AND (i.image_work_claim_until IS NULL OR i.image_work_claim_until < now())
    ) AS claimable,
    count(*) AS outstanding
  FROM public.builder_stock_items AS i
  WHERE i.lifecycle_status IN ('active', 'staged')
    AND i.image_work_stage <> 'settled';
$$;


--
-- Name: builder_stock_items_rearm_settlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_stock_items_rearm_settlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.ensure_builder_stock_settlement_scheduled();
  RETURN NULL;
END;
$$;


--
-- Name: builder_stock_publication_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_stock_publication_readiness(p_upload_id uuid) RETURNS TABLE(staged bigint, source_outstanding bigint, ready boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    count(*) AS staged,
    count(*) FILTER (
      WHERE i.lifecycle_status = 'staged' AND i.image_work_stage = 'source'
    ) AS source_outstanding,
    count(*) > 0 AND count(*) FILTER (
      WHERE i.lifecycle_status = 'staged' AND i.image_work_stage = 'source'
    ) = 0 AS ready
  FROM public.builder_stock_items AS i
  WHERE (i.upload_id = p_upload_id AND i.lifecycle_status = 'staged')
     -- A MATCHED PROPERTY WAITING ONLY ON ITS PATCH COUNTS TOO. An import whose
     -- rows ALL matched stages nothing at all, and a readiness rule that looked
     -- only at staged rows would answer "nothing here" for ever — so the new
     -- prices would never publish. It owes no source work: its imagery is
     -- already earned and its row is already serving.
     OR (i.pending_upload_id = p_upload_id);
$$;


--
-- Name: builder_stock_publications_pending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_stock_publications_pending() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT count(*)::integer
    FROM public.builder_stock_uploads AS u
   WHERE u.published_at IS NULL
     AND u.deleted_at IS NULL
     AND NOT public.builder_stock_upload_superseded(u.id)
     AND (SELECT ready FROM public.builder_stock_publication_readiness(u.id));
$$;


--
-- Name: builder_stock_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_stock_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: builder_stock_upload_superseded(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_stock_upload_superseded(p_upload_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.builder_stock_uploads AS newer
      JOIN public.builder_stock_uploads AS this ON this.id = p_upload_id
     WHERE newer.organisation_id = this.organisation_id
       AND newer.id <> this.id
       AND newer.deleted_at IS NULL
       AND newer.created_at > this.created_at
  );
$$;


--
-- Name: builder_stock_uploads_rearm_settlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_stock_uploads_rearm_settlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.ensure_builder_stock_settlement_scheduled();
  RETURN NULL;
END;
$$;


--
-- Name: builder_touch_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_touch_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();
  -- row_version is server-owned. A client may send expected_version to a guarded
  -- command, but can never set the stored value directly.
  NEW.row_version := COALESCE(OLD.row_version, 0) + 1;
  RETURN NEW;
END $$;


--
-- Name: builder_transaction_history_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transaction_history_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION USING ERRCODE='P0001',
    MESSAGE='BUILDER_TRANSACTION_HISTORY_APPEND_ONLY',
    DETAIL='transaction status history rows cannot be updated or deleted';
END $$;


--
-- Name: builder_transition_construction_case(uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_construction_case(_construction_case_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.builder_construction_cases; v_history_id uuid; v_org uuid;
BEGIN
  IF NULLIF(btrim(COALESCE(_reason,'')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;
  IF NOT public.builder_is_construction_transition_allowed(_from, _to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION';
  END IF;

  SELECT * INTO c FROM public.builder_construction_cases
  WHERE id = _construction_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
  END IF;
  IF c.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION';
  END IF;
  IF c.status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS';
  END IF;

  UPDATE public.builder_construction_cases SET
    status = _to,
    practical_completion_date = CASE WHEN _to = 'practical_completion'
      THEN COALESCE(practical_completion_date, CURRENT_DATE) ELSE practical_completion_date END,
    actual_completion_date = CASE WHEN _to = 'completed'
      THEN COALESCE(actual_completion_date, CURRENT_DATE) ELSE actual_completion_date END,
    percent_complete = CASE WHEN _to = 'completed' THEN 100 ELSE percent_complete END
  WHERE id = _construction_case_id RETURNING * INTO c;

  INSERT INTO public.builder_construction_status_history(construction_case_id, entity_kind,
    entity_id, from_status, to_status, changed_by_type, changed_by_builder_user_id,
    changed_by_user_id, reason, metadata)
  VALUES (_construction_case_id, 'case', _construction_case_id, _from, _to, _actor_type,
    _actor_builder_user_id, _actor_staff_user_id, left(btrim(_reason),1000),
    jsonb_build_object('row_version', c.row_version))
  RETURNING id INTO v_history_id;

  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = c.transaction_id;
  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_construction_status_changed',
    'construction_case', c.id, v_org, _actor_builder_user_id,
    jsonb_build_object('status', _from),
    jsonb_build_object('status', _to, 'row_version', c.row_version),
    left(btrim(_reason),1000), jsonb_build_object('history_id', v_history_id));
  RETURN to_jsonb(c);
END $$;


--
-- Name: builder_transition_delivery(text, uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_delivery(_kind text, _entity_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_case uuid; v_version bigint; v_status text; v_result jsonb; v_history_id uuid;
BEGIN
  IF NULLIF(btrim(COALESCE(_reason,'')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;
  IF NOT public.builder_is_delivery_transition_allowed(_kind, _from, _to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION';
  END IF;

  -- Lock, read the current version and status, and confirm both match what the
  -- caller declared. The row is located by kind so no caller can aim an id at
  -- the wrong table.
  IF _kind = 'variation' THEN
    SELECT construction_case_id, row_version, status INTO v_case, v_version, v_status
    FROM public.builder_variations WHERE id = _entity_id FOR UPDATE;
  ELSIF _kind = 'progress_claim' THEN
    SELECT construction_case_id, row_version, status INTO v_case, v_version, v_status
    FROM public.builder_progress_claims WHERE id = _entity_id FOR UPDATE;
  ELSIF _kind = 'inspection' THEN
    SELECT construction_case_id, row_version, status INTO v_case, v_version, v_status
    FROM public.builder_inspections WHERE id = _entity_id FOR UPDATE;
  ELSIF _kind = 'defect' THEN
    SELECT construction_case_id, row_version, status INTO v_case, v_version, v_status
    FROM public.builder_defects WHERE id = _entity_id FOR UPDATE;
  ELSIF _kind = 'practical_completion' THEN
    SELECT construction_case_id, row_version, status INTO v_case, v_version, v_status
    FROM public.builder_practical_completions WHERE id = _entity_id FOR UPDATE;
  ELSIF _kind = 'handover' THEN
    SELECT construction_case_id, row_version, status INTO v_case, v_version, v_status
    FROM public.builder_handovers WHERE id = _entity_id FOR UPDATE;
  ELSIF _kind = 'warranty_claim' THEN
    SELECT construction_case_id, row_version, status INTO v_case, v_version, v_status
    FROM public.builder_warranty_claims WHERE id = _entity_id FOR UPDATE;
  ELSE
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_DELIVERY_KIND';
  END IF;

  IF v_case IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DELIVERY_NOT_FOUND';
  END IF;
  IF v_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION';
  END IF;
  IF v_status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS';
  END IF;

  IF _kind = 'variation' THEN
    UPDATE public.builder_variations SET status = _to,
      submitted_at = CASE WHEN _to = 'submitted' THEN COALESCE(submitted_at, now()) ELSE submitted_at END,
      decided_at = CASE WHEN _to IN ('approved','rejected') THEN COALESCE(decided_at, now()) ELSE decided_at END
    WHERE id = _entity_id RETURNING to_jsonb(builder_variations.*) INTO v_result;
  ELSIF _kind = 'progress_claim' THEN
    UPDATE public.builder_progress_claims SET status = _to,
      claimed_at = CASE WHEN _to = 'submitted' THEN COALESCE(claimed_at, now()) ELSE claimed_at END,
      certified_at = CASE WHEN _to = 'certified' THEN COALESCE(certified_at, now()) ELSE certified_at END
    WHERE id = _entity_id RETURNING to_jsonb(builder_progress_claims.*) INTO v_result;
  ELSIF _kind = 'inspection' THEN
    UPDATE public.builder_inspections SET status = _to,
      performed_at = CASE WHEN _to IN ('passed','failed','passed_with_defects')
                          THEN COALESCE(performed_at, now()) ELSE performed_at END
    WHERE id = _entity_id RETURNING to_jsonb(builder_inspections.*) INTO v_result;
  ELSIF _kind = 'defect' THEN
    UPDATE public.builder_defects SET status = _to,
      rectified_at = CASE WHEN _to = 'rectified' THEN COALESCE(rectified_at, now()) ELSE rectified_at END,
      verified_at = CASE WHEN _to = 'verified' THEN COALESCE(verified_at, now()) ELSE verified_at END
    WHERE id = _entity_id RETURNING to_jsonb(builder_defects.*) INTO v_result;
  ELSIF _kind = 'practical_completion' THEN
    UPDATE public.builder_practical_completions SET status = _to,
      notified_at = CASE WHEN _to = 'notified' THEN COALESCE(notified_at, now()) ELSE notified_at END,
      inspected_at = CASE WHEN _to = 'inspected' THEN COALESCE(inspected_at, now()) ELSE inspected_at END,
      achieved_at = CASE WHEN _to = 'achieved' THEN COALESCE(achieved_at, now()) ELSE achieved_at END
    WHERE id = _entity_id RETURNING to_jsonb(builder_practical_completions.*) INTO v_result;
  ELSIF _kind = 'handover' THEN
    UPDATE public.builder_handovers SET status = _to,
      walkthrough_at = CASE WHEN _to = 'walkthrough_complete' THEN COALESCE(walkthrough_at, now()) ELSE walkthrough_at END,
      keys_released_at = CASE WHEN _to = 'keys_released' THEN COALESCE(keys_released_at, now()) ELSE keys_released_at END,
      completed_at = CASE WHEN _to = 'completed' THEN COALESCE(completed_at, now()) ELSE completed_at END
    WHERE id = _entity_id RETURNING to_jsonb(builder_handovers.*) INTO v_result;
  ELSE
    UPDATE public.builder_warranty_claims SET status = _to,
      decided_at = CASE WHEN _to IN ('accepted','rejected') THEN COALESCE(decided_at, now()) ELSE decided_at END,
      rectified_at = CASE WHEN _to = 'rectified' THEN COALESCE(rectified_at, now()) ELSE rectified_at END
    WHERE id = _entity_id RETURNING to_jsonb(builder_warranty_claims.*) INTO v_result;
  END IF;

  INSERT INTO public.builder_delivery_status_history(construction_case_id, entity_kind, entity_id,
    from_status, to_status, changed_by_type, changed_by_builder_user_id, changed_by_user_id,
    reason, metadata)
  VALUES (v_case, _kind, _entity_id, _from, _to, _actor_type, _actor_builder_user_id,
    _actor_staff_user_id, left(btrim(_reason),1000),
    jsonb_build_object('row_version', v_result->>'row_version'))
  RETURNING id INTO v_history_id;

  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_'||_kind||'_status_changed',
    CASE _kind WHEN 'variation' THEN 'variation'
               WHEN 'progress_claim' THEN 'progress_claim'
               WHEN 'inspection' THEN 'inspection'
               WHEN 'defect' THEN 'defect'
               WHEN 'practical_completion' THEN 'practical_completion'
               WHEN 'handover' THEN 'handover' ELSE 'warranty_claim' END,
    _entity_id, public.builder_delivery_org(v_case), _actor_builder_user_id,
    jsonb_build_object('status', _from),
    jsonb_build_object('status', _to, 'row_version', v_result->>'row_version'),
    left(btrim(_reason),1000), jsonb_build_object('history_id', v_history_id));
  RETURN v_result;
END $$;


--
-- Name: builder_transition_milestone(uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_milestone(_milestone_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE m public.builder_construction_milestones; v_history_id uuid; v_org uuid; v_txn uuid;
BEGIN
  IF NULLIF(btrim(COALESCE(_reason,'')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;
  IF NOT public.builder_is_milestone_transition_allowed(_from, _to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION';
  END IF;

  SELECT * INTO m FROM public.builder_construction_milestones
  WHERE id = _milestone_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_MILESTONE_NOT_FOUND';
  END IF;
  IF m.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION';
  END IF;
  IF m.status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS';
  END IF;

  UPDATE public.builder_construction_milestones SET
    status = _to,
    achieved_date = CASE WHEN _to = 'achieved' THEN COALESCE(achieved_date, CURRENT_DATE)
                         ELSE achieved_date END
  WHERE id = _milestone_id RETURNING * INTO m;

  INSERT INTO public.builder_construction_status_history(construction_case_id, entity_kind,
    entity_id, from_status, to_status, changed_by_type, changed_by_builder_user_id,
    changed_by_user_id, reason, metadata)
  VALUES (m.construction_case_id, 'milestone', m.id, _from, _to, _actor_type,
    _actor_builder_user_id, _actor_staff_user_id, left(btrim(_reason),1000),
    jsonb_build_object('row_version', m.row_version))
  RETURNING id INTO v_history_id;

  SELECT transaction_id INTO v_txn FROM public.builder_construction_cases
  WHERE id = m.construction_case_id;
  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = v_txn;
  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_milestone_status_changed',
    'milestone', m.id, v_org, _actor_builder_user_id,
    jsonb_build_object('status', _from),
    jsonb_build_object('status', _to, 'row_version', m.row_version),
    left(btrim(_reason),1000), jsonb_build_object('history_id', v_history_id));
  RETURN to_jsonb(m);
END $$;


--
-- Name: builder_transition_project(uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_project(_project_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE p public.builder_projects; v_history_id uuid;
BEGIN
  IF NULLIF(btrim(_reason), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;

  SELECT * INTO p FROM public.builder_projects WHERE id = _project_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
  END IF;
  IF p.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION';
  END IF;
  IF p.status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS';
  END IF;
  IF NOT public.builder_is_project_transition_allowed(_from, _to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION';
  END IF;

  UPDATE public.builder_projects
  SET status = _to,
      row_version = row_version + 1,
      actual_completion_date = CASE WHEN _to = 'completed'
        THEN COALESCE(actual_completion_date, current_date) ELSE actual_completion_date END,
      actual_start_date = CASE WHEN _to = 'under_construction'
        THEN COALESCE(actual_start_date, current_date) ELSE actual_start_date END,
      closed_at = CASE WHEN _to IN ('completed','cancelled') THEN now() ELSE closed_at END,
      updated_at = now()
  WHERE id = _project_id
  RETURNING * INTO p;

  INSERT INTO public.builder_project_status_history(
    project_id, from_status, to_status, changed_by_type,
    changed_by_builder_user_id, changed_by_user_id, reason, metadata)
  VALUES (_project_id, _from, _to, _actor_type,
          _actor_builder_user_id, _actor_staff_user_id,
          left(btrim(_reason), 1000), jsonb_build_object('row_version', p.row_version))
  RETURNING id INTO v_history_id;

  -- A status change is a governed event: the trusted audit write happens in
  -- this transaction, so a failure rolls the transition back.
  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_project_status_changed',
    'project', p.id,
    COALESCE(p.developer_organisation_id, p.builder_organisation_id),
    _actor_builder_user_id,
    jsonb_build_object('status', _from),
    jsonb_build_object('status', _to, 'row_version', p.row_version),
    left(btrim(_reason), 1000),
    jsonb_build_object('history_id', v_history_id));

  RETURN to_jsonb(p);
END $$;


--
-- Name: builder_transition_reservation(uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_reservation(_reservation_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.builder_reservations; u public.builder_units; v_org uuid; v_history_id uuid;
BEGIN
  IF NULLIF(btrim(_reason), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED'; END IF;
  SELECT * INTO r FROM public.builder_reservations WHERE id = _reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_RESERVATION_NOT_FOUND'; END IF;
  IF r.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION'; END IF;
  IF r.status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS'; END IF;
  IF NOT public.builder_is_reservation_transition_allowed(_from, _to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION'; END IF;

  UPDATE public.builder_reservations
  SET status = _to,
      cancelled_reason = CASE WHEN _to IN ('cancelled','lapsed','expired')
        THEN left(btrim(_reason),1000) ELSE cancelled_reason END
  WHERE id = _reservation_id RETURNING * INTO r;

  INSERT INTO public.builder_reservation_status_history(reservation_id, from_status, to_status,
    changed_by_type, changed_by_builder_user_id, changed_by_user_id, reason, metadata)
  VALUES (_reservation_id, _from, _to, _actor_type, _actor_builder_user_id,
    _actor_staff_user_id, left(btrim(_reason),1000),
    jsonb_build_object('row_version', r.row_version))
  RETURNING id INTO v_history_id;

  -- The unit follows the reservation.
  SELECT * INTO u FROM public.builder_units WHERE id = r.unit_id FOR UPDATE;
  IF _to = 'contracted' AND u.availability_status = 'reserved' THEN
    PERFORM public.builder_transition_unit_availability(u.id, u.row_version, 'reserved',
      'contracted', left(btrim(_reason),1000), _actor_type, _actor_builder_user_id, _actor_staff_user_id);
  ELSIF _to IN ('cancelled','expired','lapsed') AND u.availability_status = 'reserved' THEN
    PERFORM public.builder_transition_unit_availability(u.id, u.row_version, 'reserved',
      'available', left(btrim(_reason),1000), _actor_type, _actor_builder_user_id, _actor_staff_user_id);
  END IF;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = u.project_id;
  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_reservation_status_changed',
    'reservation', r.id, v_org, _actor_builder_user_id,
    jsonb_build_object('status', _from), jsonb_build_object('status', _to),
    left(btrim(_reason),1000), jsonb_build_object('history_id', v_history_id));
  RETURN to_jsonb(r);
END $$;


--
-- Name: builder_transition_transaction(uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_transaction(_transaction_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.builder_transactions; v_history_id uuid;
BEGIN
  IF NULLIF(btrim(_reason), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;
  IF NOT public.builder_is_transaction_transition_allowed(_from, _to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION';
  END IF;

  SELECT * INTO t FROM public.builder_transactions WHERE id = _transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TRANSACTION_NOT_FOUND';
  END IF;
  IF t.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION';
  END IF;
  IF t.status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS';
  END IF;

  UPDATE public.builder_transactions SET
    status = _to,
    closed_at = CASE WHEN _to IN ('settled','cancelled','lapsed') THEN COALESCE(closed_at, now())
                     ELSE closed_at END,
    actual_settlement_date = CASE WHEN _to = 'settled'
      THEN COALESCE(actual_settlement_date, CURRENT_DATE) ELSE actual_settlement_date END
  WHERE id = _transaction_id RETURNING * INTO t;

  INSERT INTO public.builder_transaction_status_history(transaction_id, from_status, to_status,
    changed_by_type, changed_by_builder_user_id, changed_by_user_id, reason, metadata)
  VALUES (_transaction_id, _from, _to, _actor_type,
    _actor_builder_user_id, _actor_staff_user_id, left(btrim(_reason),1000),
    jsonb_build_object('row_version', t.row_version))
  RETURNING id INTO v_history_id;

  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_transaction_status_changed',
    'transaction', t.id, t.organisation_id, _actor_builder_user_id,
    jsonb_build_object('status', _from),
    jsonb_build_object('status', _to, 'row_version', t.row_version),
    left(btrim(_reason),1000), jsonb_build_object('history_id', v_history_id));
  RETURN to_jsonb(t);
END $$;


--
-- Name: builder_transition_unit_availability(uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_unit_availability(_unit_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE u public.builder_units; v_history_id uuid; v_org uuid;
BEGIN
  IF NULLIF(btrim(_reason), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;
  SELECT * INTO u FROM public.builder_units WHERE id = _unit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_FOUND'; END IF;
  IF u.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION'; END IF;
  IF u.availability_status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS'; END IF;
  IF NOT public.builder_is_unit_availability_transition_allowed(_from, _to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION'; END IF;

  UPDATE public.builder_units SET availability_status = _to
  WHERE id = _unit_id RETURNING * INTO u;

  INSERT INTO public.builder_unit_status_history(unit_id, status_kind, from_status, to_status,
    changed_by_type, changed_by_builder_user_id, changed_by_user_id, reason, metadata)
  VALUES (_unit_id, 'availability', _from, _to, _actor_type,
    _actor_builder_user_id, _actor_staff_user_id, left(btrim(_reason),1000),
    jsonb_build_object('row_version', u.row_version))
  RETURNING id INTO v_history_id;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = u.project_id;
  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_unit_availability_changed',
    'unit', u.id, v_org, _actor_builder_user_id,
    jsonb_build_object('availability_status', _from),
    jsonb_build_object('availability_status', _to, 'row_version', u.row_version),
    left(btrim(_reason),1000), jsonb_build_object('history_id', v_history_id));
  RETURN to_jsonb(u);
END $$;


--
-- Name: builder_transition_unit_release(uuid, bigint, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_transition_unit_release(_unit_id uuid, _expected_version bigint, _from text, _to text, _reason text, _actor_type text, _actor_builder_user_id uuid DEFAULT NULL::uuid, _actor_staff_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE u public.builder_units; v_history_id uuid; v_org uuid;
BEGIN
  IF NULLIF(btrim(_reason), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='REASON_REQUIRED';
  END IF;
  IF _to NOT IN ('unreleased','coming_soon','released','sold_out') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION'; END IF;
  IF _from = _to THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='INVALID_TRANSITION'; END IF;

  SELECT * INTO u FROM public.builder_units WHERE id = _unit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_FOUND'; END IF;
  IF u.row_version <> _expected_version THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_VERSION'; END IF;
  IF u.release_status <> _from THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='STALE_STATUS'; END IF;

  -- A unit cannot be released without a current price: a released unit with no
  -- price is a customer-facing error, not a valid inventory state.
  IF _to = 'released' AND NOT EXISTS (
    SELECT 1 FROM public.builder_unit_pricing WHERE unit_id = _unit_id AND is_current) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_PRICE_REQUIRED',
      DETAIL='a unit cannot be released without a current price';
  END IF;

  UPDATE public.builder_units SET release_status = _to,
    released_at = CASE WHEN _to = 'released' THEN COALESCE(released_at, now()) ELSE released_at END
  WHERE id = _unit_id RETURNING * INTO u;

  INSERT INTO public.builder_unit_status_history(unit_id, status_kind, from_status, to_status,
    changed_by_type, changed_by_builder_user_id, changed_by_user_id, reason, metadata)
  VALUES (_unit_id, 'release', _from, _to, _actor_type,
    _actor_builder_user_id, _actor_staff_user_id, left(btrim(_reason),1000),
    jsonb_build_object('row_version', u.row_version))
  RETURNING id INTO v_history_id;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = u.project_id;
  PERFORM public.builder_log_activity(
    _actor_staff_user_id, _actor_type, 'builder_unit_release_changed',
    'unit', u.id, v_org, _actor_builder_user_id,
    jsonb_build_object('release_status', _from),
    jsonb_build_object('release_status', _to, 'row_version', u.row_version),
    left(btrim(_reason),1000), jsonb_build_object('history_id', v_history_id));
  RETURN to_jsonb(u);
END $$;


--
-- Name: builder_unread_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_unread_counts(_user_id uuid) RETURNS TABLE(unread_messages bigint, unread_notifications bigint, overdue_tasks bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    (SELECT count(*) FROM public.builder_conversation_participants p
     JOIN public.builder_conversations c ON c.id = p.conversation_id
     WHERE p.builder_user_id = _user_id AND p.left_at IS NULL
       AND c.last_message_at IS NOT NULL
       AND (p.last_read_at IS NULL OR c.last_message_at > p.last_read_at)
       AND public.builder_can_see_conversation(_user_id, c.id, 'view')),
    (SELECT count(*) FROM public.builder_notifications n
     WHERE n.builder_user_id = _user_id AND n.read_at IS NULL),
    (SELECT count(*) FROM public.builder_task_assignments a
     JOIN public.builder_tasks t ON t.id = a.task_id
     WHERE a.builder_user_id = _user_id AND a.unassigned_at IS NULL
       AND t.status NOT IN ('done','cancelled')
       AND t.due_date IS NOT NULL AND t.due_date < CURRENT_DATE
       AND public.builder_resolve_scope_permission(
             _user_id, t.scope_type, t.scope_id, 'tasks', 'view'));
$$;


--
-- Name: builder_buildings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_buildings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    stage_id uuid,
    name text NOT NULL,
    building_code text,
    level_count integer,
    status text DEFAULT 'planned'::text NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_buildings_level_count_check CHECK (((level_count IS NULL) OR (level_count > 0))),
    CONSTRAINT builder_buildings_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_buildings_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'under_construction'::text, 'completed'::text, 'on_hold'::text, 'cancelled'::text])))
);


--
-- Name: builder_upsert_building(uuid, text, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_building(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _building_id uuid, _project_id uuid, _stage_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_buildings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_buildings; v_row public.builder_buildings; v_org uuid;
BEGIN
  IF _building_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_buildings WHERE id = _building_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_BUILDING_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_buildings SET
      name          = CASE WHEN _payload ? 'name' THEN _payload->>'name' ELSE name END,
      building_code = CASE WHEN _payload ? 'building_code' THEN _payload->>'building_code' ELSE building_code END,
      level_count   = CASE WHEN _payload ? 'level_count' THEN (_payload->>'level_count')::integer ELSE level_count END,
      status        = CASE WHEN _payload ? 'status' THEN _payload->>'status' ELSE status END,
      stage_id      = COALESCE(_stage_id, stage_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _project_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_REQUIRED';
    END IF;
    INSERT INTO public.builder_buildings(project_id, stage_id, name, building_code, level_count, status)
    VALUES (_project_id, _stage_id, _payload->>'name', _payload->>'building_code',
            (_payload->>'level_count')::integer, COALESCE(_payload->>'status','planned'))
    RETURNING * INTO v_row;
  END IF;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = v_row.project_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _building_id IS NULL THEN 'builder_building_created' ELSE 'builder_building_updated' END,
    'building', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _building_id IS NULL THEN NULL ELSE jsonb_build_object('name', v_existing.name) END,
    jsonb_build_object('name', v_row.name, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('project_id', v_row.project_id));
  RETURN v_row;
END $$;


--
-- Name: builder_upsert_construction_case(uuid, text, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_construction_case(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _construction_case_id uuid, _transaction_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_construction_cases
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_construction_cases; v_row public.builder_construction_cases;
        v_org uuid; v_project uuid; v_unit uuid; d record;
BEGIN
  IF _construction_case_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_construction_cases
    WHERE id = _construction_case_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    -- Status is NOT writable here: it moves only through the transition command.
    UPDATE public.builder_construction_cases SET
      case_reference = CASE WHEN _payload ? 'case_reference' THEN _payload->>'case_reference' ELSE case_reference END,
      site_supervisor_name  = CASE WHEN _payload ? 'site_supervisor_name' THEN _payload->>'site_supervisor_name' ELSE site_supervisor_name END,
      site_supervisor_email = CASE WHEN _payload ? 'site_supervisor_email' THEN _payload->>'site_supervisor_email' ELSE site_supervisor_email END,
      site_supervisor_phone = CASE WHEN _payload ? 'site_supervisor_phone' THEN _payload->>'site_supervisor_phone' ELSE site_supervisor_phone END,
      percent_complete = CASE WHEN _payload ? 'percent_complete' THEN (_payload->>'percent_complete')::numeric ELSE percent_complete END,
      shared_summary = CASE WHEN _payload ? 'shared_summary' THEN _payload->>'shared_summary' ELSE shared_summary END,
      builder_notes  = CASE WHEN _payload ? 'builder_notes' THEN _payload->>'builder_notes' ELSE builder_notes END,
      weather_delay_days = CASE WHEN _payload ? 'weather_delay_days' THEN (_payload->>'weather_delay_days')::integer ELSE weather_delay_days END,
      variation_delay_days = CASE WHEN _payload ? 'variation_delay_days' THEN (_payload->>'variation_delay_days')::integer ELSE variation_delay_days END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _transaction_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TRANSACTION_REQUIRED';
    END IF;
    SELECT project_id, unit_id INTO v_project, v_unit
    FROM public.builder_transactions WHERE id = _transaction_id;
    IF v_project IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TRANSACTION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_construction_cases(transaction_id, project_id, unit_id,
      case_reference, site_supervisor_name, site_supervisor_email, site_supervisor_phone,
      shared_summary, builder_notes)
    VALUES (_transaction_id, v_project, v_unit,
      _payload->>'case_reference', _payload->>'site_supervisor_name',
      _payload->>'site_supervisor_email', _payload->>'site_supervisor_phone',
      _payload->>'shared_summary', _payload->>'builder_notes')
    RETURNING * INTO v_row;
  END IF;

  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = v_row.transaction_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _construction_case_id IS NULL THEN 'builder_construction_case_created'
         ELSE 'builder_construction_case_updated' END,
    'construction_case', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _construction_case_id IS NULL THEN NULL
         ELSE jsonb_build_object('status', v_existing.status,
                                 'row_version', v_existing.row_version) END,
    jsonb_build_object('status', v_row.status, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('transaction_id', v_row.transaction_id));
  RETURN v_row;
END $$;


--
-- Name: builder_construction_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_construction_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    name text NOT NULL,
    stage_key text NOT NULL,
    sequence_number smallint DEFAULT 1 NOT NULL,
    status text DEFAULT 'not_started'::text NOT NULL,
    planned_start_date date,
    planned_end_date date,
    actual_start_date date,
    actual_end_date date,
    percent_complete numeric(5,2) DEFAULT 0 NOT NULL,
    notes text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_construction_stages_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_construction_stages_percent_complete_check CHECK (((percent_complete >= (0)::numeric) AND (percent_complete <= (100)::numeric))),
    CONSTRAINT builder_construction_stages_sequence_number_check CHECK ((sequence_number > 0)),
    CONSTRAINT builder_construction_stages_stage_key_check CHECK ((stage_key = ANY (ARRAY['site_preparation'::text, 'base'::text, 'frame'::text, 'lockup'::text, 'fixing'::text, 'practical_completion'::text, 'handover'::text, 'other'::text]))),
    CONSTRAINT builder_construction_stages_status_check CHECK ((status = ANY (ARRAY['not_started'::text, 'in_progress'::text, 'complete'::text, 'on_hold'::text, 'skipped'::text])))
);


--
-- Name: builder_upsert_construction_stage(uuid, text, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_construction_stage(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _stage_id uuid, _construction_case_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_construction_stages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_construction_stages; v_row public.builder_construction_stages;
        v_org uuid; v_case uuid;
BEGIN
  IF _stage_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_construction_stages
    WHERE id = _stage_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_STAGE_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_construction_stages SET
      name = CASE WHEN _payload ? 'name' THEN _payload->>'name' ELSE name END,
      stage_key = CASE WHEN _payload ? 'stage_key' THEN _payload->>'stage_key' ELSE stage_key END,
      sequence_number = CASE WHEN _payload ? 'sequence_number' THEN (_payload->>'sequence_number')::smallint ELSE sequence_number END,
      status = CASE WHEN _payload ? 'status' THEN _payload->>'status' ELSE status END,
      planned_start_date = CASE WHEN _payload ? 'planned_start_date' THEN (_payload->>'planned_start_date')::date ELSE planned_start_date END,
      planned_end_date = CASE WHEN _payload ? 'planned_end_date' THEN (_payload->>'planned_end_date')::date ELSE planned_end_date END,
      actual_start_date = CASE WHEN _payload ? 'actual_start_date' THEN (_payload->>'actual_start_date')::date ELSE actual_start_date END,
      actual_end_date = CASE WHEN _payload ? 'actual_end_date' THEN (_payload->>'actual_end_date')::date ELSE actual_end_date END,
      percent_complete = CASE WHEN _payload ? 'percent_complete' THEN (_payload->>'percent_complete')::numeric ELSE percent_complete END,
      notes = CASE WHEN _payload ? 'notes' THEN _payload->>'notes' ELSE notes END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _construction_case_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_construction_stages(construction_case_id, name, stage_key,
      sequence_number, status, planned_start_date, planned_end_date, notes)
    VALUES (_construction_case_id, _payload->>'name', COALESCE(_payload->>'stage_key','other'),
      COALESCE((_payload->>'sequence_number')::smallint, 1),
      COALESCE(_payload->>'status','not_started'),
      (_payload->>'planned_start_date')::date, (_payload->>'planned_end_date')::date,
      _payload->>'notes')
    RETURNING * INTO v_row;
  END IF;

  SELECT c.transaction_id INTO v_case FROM public.builder_construction_cases c
  WHERE c.id = v_row.construction_case_id;
  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = v_case;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _stage_id IS NULL THEN 'builder_construction_stage_created'
         ELSE 'builder_construction_stage_updated' END,
    'construction_stage', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _stage_id IS NULL THEN NULL ELSE jsonb_build_object('name', v_existing.name,
      'status', v_existing.status) END,
    jsonb_build_object('name', v_row.name, 'status', v_row.status,
                       'row_version', v_row.row_version),
    _reason, jsonb_build_object('construction_case_id', v_row.construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_defects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_defects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    inspection_id uuid,
    defect_number text,
    title text NOT NULL,
    description text,
    location text,
    severity text DEFAULT 'minor'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    raised_by_type text DEFAULT 'builder'::text NOT NULL,
    raised_at timestamp with time zone DEFAULT now() NOT NULL,
    due_date date,
    rectified_at timestamp with time zone,
    verified_at timestamp with time zone,
    is_customer_visible boolean DEFAULT true NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_defects_raised_by_type_check CHECK ((raised_by_type = ANY (ARRAY['builder'::text, 'purchaser'::text, 'inspector'::text, 'developer'::text, 'authority'::text]))),
    CONSTRAINT builder_defects_severity_check CHECK ((severity = ANY (ARRAY['cosmetic'::text, 'minor'::text, 'major'::text, 'critical'::text]))),
    CONSTRAINT builder_defects_status_check CHECK ((status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'in_rectification'::text, 'rectified'::text, 'verified'::text, 'rejected'::text, 'closed'::text]))),
    CONSTRAINT builder_defects_title_check CHECK ((length(btrim(title)) > 0))
);


--
-- Name: builder_upsert_defect(uuid, text, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_defect(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _defect_id uuid, _construction_case_id uuid, _inspection_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_defects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_defects; v_row public.builder_defects;
BEGIN
  IF _defect_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_defects WHERE id = _defect_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DEFECT_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_defects SET
      defect_number = CASE WHEN _payload ? 'defect_number' THEN _payload->>'defect_number' ELSE defect_number END,
      title = CASE WHEN _payload ? 'title' THEN _payload->>'title' ELSE title END,
      description = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      location = CASE WHEN _payload ? 'location' THEN _payload->>'location' ELSE location END,
      severity = CASE WHEN _payload ? 'severity' THEN _payload->>'severity' ELSE severity END,
      due_date = CASE WHEN _payload ? 'due_date' THEN (_payload->>'due_date')::date ELSE due_date END,
      is_customer_visible = CASE WHEN _payload ? 'is_customer_visible' THEN (_payload->>'is_customer_visible')::boolean ELSE is_customer_visible END,
      inspection_id = COALESCE(_inspection_id, inspection_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _construction_case_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_defects(construction_case_id, inspection_id, defect_number, title,
      description, location, severity, raised_by_type, due_date, is_customer_visible)
    VALUES (_construction_case_id, _inspection_id, _payload->>'defect_number', _payload->>'title',
      _payload->>'description', _payload->>'location', COALESCE(_payload->>'severity','minor'),
      COALESCE(_payload->>'raised_by_type','builder'), (_payload->>'due_date')::date,
      COALESCE((_payload->>'is_customer_visible')::boolean, true))
    RETURNING * INTO v_row;
    -- The inspection's defect count follows the defects raised against it.
    IF _inspection_id IS NOT NULL THEN
      UPDATE public.builder_inspections
      SET defect_count = (SELECT count(*) FROM public.builder_defects
                          WHERE inspection_id = _inspection_id)
      WHERE id = _inspection_id;
    END IF;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _defect_id IS NULL THEN 'builder_defect_raised' ELSE 'builder_defect_updated' END,
    'defect', v_row.id, public.builder_delivery_org(v_row.construction_case_id),
    _actor_builder_user_id,
    CASE WHEN _defect_id IS NULL THEN NULL ELSE jsonb_build_object('title', v_existing.title) END,
    jsonb_build_object('title', v_row.title, 'status', v_row.status,
                       'severity', v_row.severity, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('construction_case_id', v_row.construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_upsert_delivery_record(uuid, text, uuid, text, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_delivery_record(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _kind text, _construction_case_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pc public.builder_practical_completions; v_ho public.builder_handovers;
        v_wr public.builder_warranties; v_current bigint; v_result jsonb;
BEGIN
  IF _kind NOT IN ('practical_completion','handover','warranty') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INVALID_DELIVERY_KIND';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
  END IF;

  -- One row per case for each of these three. The row is created on first use;
  -- from then on an update requires the matching expected_version.
  IF _kind = 'practical_completion' THEN
    SELECT * INTO v_pc FROM public.builder_practical_completions
    WHERE construction_case_id = _construction_case_id FOR UPDATE;
    IF v_pc.id IS NULL THEN
      INSERT INTO public.builder_practical_completions(construction_case_id,
        certificate_reference, outstanding_defect_count, notes)
      VALUES (_construction_case_id, _payload->>'certificate_reference',
        COALESCE((_payload->>'outstanding_defect_count')::integer, 0), _payload->>'notes')
      RETURNING * INTO v_pc;
    ELSE
      IF _expected_version IS NULL OR v_pc.row_version <> _expected_version THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
          DETAIL = format('current_version=%s', v_pc.row_version);
      END IF;
      UPDATE public.builder_practical_completions SET
        certificate_reference = CASE WHEN _payload ? 'certificate_reference' THEN _payload->>'certificate_reference' ELSE certificate_reference END,
        outstanding_defect_count = CASE WHEN _payload ? 'outstanding_defect_count' THEN (_payload->>'outstanding_defect_count')::integer ELSE outstanding_defect_count END,
        dispute_reason = CASE WHEN _payload ? 'dispute_reason' THEN _payload->>'dispute_reason' ELSE dispute_reason END,
        notes = CASE WHEN _payload ? 'notes' THEN _payload->>'notes' ELSE notes END
      WHERE id = v_pc.id RETURNING * INTO v_pc;
    END IF;
    v_result := to_jsonb(v_pc);
  ELSIF _kind = 'handover' THEN
    SELECT * INTO v_ho FROM public.builder_handovers
    WHERE construction_case_id = _construction_case_id FOR UPDATE;
    IF v_ho.id IS NULL THEN
      INSERT INTO public.builder_handovers(construction_case_id, scheduled_for, attendee_names,
        key_set_count, manual_provided, notes)
      VALUES (_construction_case_id, (_payload->>'scheduled_for')::timestamptz,
        _payload->>'attendee_names', (_payload->>'key_set_count')::integer,
        COALESCE((_payload->>'manual_provided')::boolean, false), _payload->>'notes')
      RETURNING * INTO v_ho;
    ELSE
      IF _expected_version IS NULL OR v_ho.row_version <> _expected_version THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
          DETAIL = format('current_version=%s', v_ho.row_version);
      END IF;
      UPDATE public.builder_handovers SET
        scheduled_for = CASE WHEN _payload ? 'scheduled_for' THEN (_payload->>'scheduled_for')::timestamptz ELSE scheduled_for END,
        attendee_names = CASE WHEN _payload ? 'attendee_names' THEN _payload->>'attendee_names' ELSE attendee_names END,
        key_set_count = CASE WHEN _payload ? 'key_set_count' THEN (_payload->>'key_set_count')::integer ELSE key_set_count END,
        manual_provided = CASE WHEN _payload ? 'manual_provided' THEN (_payload->>'manual_provided')::boolean ELSE manual_provided END,
        notes = CASE WHEN _payload ? 'notes' THEN _payload->>'notes' ELSE notes END
      WHERE id = v_ho.id RETURNING * INTO v_ho;
    END IF;
    v_result := to_jsonb(v_ho);
  ELSE
    SELECT * INTO v_wr FROM public.builder_warranties
    WHERE construction_case_id = _construction_case_id FOR UPDATE;
    IF v_wr.id IS NULL THEN
      INSERT INTO public.builder_warranties(construction_case_id, warranty_type, provider_name,
        policy_reference, starts_on, expires_on, notes)
      VALUES (_construction_case_id, COALESCE(_payload->>'warranty_type','structural'),
        _payload->>'provider_name', _payload->>'policy_reference',
        (_payload->>'starts_on')::date, (_payload->>'expires_on')::date, _payload->>'notes')
      RETURNING * INTO v_wr;
    ELSE
      IF _expected_version IS NULL OR v_wr.row_version <> _expected_version THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
          DETAIL = format('current_version=%s', v_wr.row_version);
      END IF;
      UPDATE public.builder_warranties SET
        warranty_type = CASE WHEN _payload ? 'warranty_type' THEN _payload->>'warranty_type' ELSE warranty_type END,
        provider_name = CASE WHEN _payload ? 'provider_name' THEN _payload->>'provider_name' ELSE provider_name END,
        policy_reference = CASE WHEN _payload ? 'policy_reference' THEN _payload->>'policy_reference' ELSE policy_reference END,
        starts_on = CASE WHEN _payload ? 'starts_on' THEN (_payload->>'starts_on')::date ELSE starts_on END,
        expires_on = CASE WHEN _payload ? 'expires_on' THEN (_payload->>'expires_on')::date ELSE expires_on END,
        notes = CASE WHEN _payload ? 'notes' THEN _payload->>'notes' ELSE notes END
      WHERE id = v_wr.id RETURNING * INTO v_wr;
    END IF;
    v_result := to_jsonb(v_wr);
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_'||_kind||'_saved',
    CASE _kind WHEN 'practical_completion' THEN 'practical_completion'
               WHEN 'handover' THEN 'handover' ELSE 'warranty_claim' END,
    (v_result->>'id')::uuid, public.builder_delivery_org(_construction_case_id),
    _actor_builder_user_id, NULL,
    jsonb_build_object('row_version', v_result->>'row_version'),
    _reason, jsonb_build_object('construction_case_id', _construction_case_id));
  RETURN v_result;
END $$;


--
-- Name: builder_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope_type text NOT NULL,
    scope_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    document_type text DEFAULT 'other'::text NOT NULL,
    current_version_id uuid,
    status text DEFAULT 'active'::text NOT NULL,
    is_customer_visible boolean DEFAULT false NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_documents_document_type_check CHECK ((document_type = ANY (ARRAY['contract'::text, 'plan'::text, 'specification'::text, 'permit'::text, 'certificate'::text, 'variation'::text, 'claim'::text, 'inspection_report'::text, 'defect_report'::text, 'handover_pack'::text, 'warranty'::text, 'photo'::text, 'other'::text]))),
    CONSTRAINT builder_documents_scope_type_check CHECK ((scope_type = ANY (ARRAY['project'::text, 'unit'::text, 'transaction'::text, 'construction_case'::text]))),
    CONSTRAINT builder_documents_status_check CHECK ((status = ANY (ARRAY['active'::text, 'superseded'::text, 'archived'::text, 'withdrawn'::text]))),
    CONSTRAINT builder_documents_title_check CHECK ((length(btrim(title)) > 0))
);


--
-- Name: TABLE builder_documents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_documents IS 'Builder document metadata. The storage path lives on the version row and is never a public URL; it is handed out only by a function that has already resolved the caller''s permission.';


--
-- Name: builder_upsert_document(uuid, text, uuid, uuid, text, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_document(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _document_id uuid, _scope_type text, _scope_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_documents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_documents; v_row public.builder_documents; v_org uuid;
BEGIN
  IF _document_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_documents WHERE id = _document_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_documents SET
      title = CASE WHEN _payload ? 'title' THEN _payload->>'title' ELSE title END,
      description = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      document_type = CASE WHEN _payload ? 'document_type' THEN _payload->>'document_type' ELSE document_type END,
      status = CASE WHEN _payload ? 'status' THEN _payload->>'status' ELSE status END,
      is_customer_visible = CASE WHEN _payload ? 'is_customer_visible'
        THEN (_payload->>'is_customer_visible')::boolean ELSE is_customer_visible END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF NULLIF(btrim(COALESCE(_payload->>'title','')), '') IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_TITLE_REQUIRED';
    END IF;
    v_org := public.builder_scope_org(_scope_type, _scope_id);
    IF v_org IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_documents(scope_type, scope_id, organisation_id, title,
      description, document_type, is_customer_visible)
    VALUES (_scope_type, _scope_id, v_org, _payload->>'title', _payload->>'description',
      COALESCE(_payload->>'document_type','other'),
      COALESCE((_payload->>'is_customer_visible')::boolean, false))
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _document_id IS NULL THEN 'builder_document_created'
         ELSE 'builder_document_updated' END,
    'document', v_row.id, v_row.organisation_id, _actor_builder_user_id,
    CASE WHEN _document_id IS NULL THEN NULL ELSE jsonb_build_object('title', v_existing.title) END,
    jsonb_build_object('title', v_row.title, 'status', v_row.status,
                       'row_version', v_row.row_version),
    _reason, jsonb_build_object('scope_type', v_row.scope_type, 'scope_id', v_row.scope_id));
  RETURN v_row;
END $$;


--
-- Name: builder_inspections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_inspections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    construction_stage_id uuid,
    inspection_type text DEFAULT 'quality'::text NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    inspector_name text,
    inspector_organisation text,
    scheduled_for timestamp with time zone,
    performed_at timestamp with time zone,
    outcome_notes text,
    defect_count integer DEFAULT 0 NOT NULL,
    is_customer_visible boolean DEFAULT true NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_inspections_defect_count_check CHECK ((defect_count >= 0)),
    CONSTRAINT builder_inspections_inspection_type_check CHECK ((inspection_type = ANY (ARRAY['quality'::text, 'frame'::text, 'waterproofing'::text, 'pre_plaster'::text, 'practical_completion'::text, 'handover'::text, 'warranty'::text, 'authority'::text, 'other'::text]))),
    CONSTRAINT builder_inspections_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'rescheduled'::text, 'in_progress'::text, 'passed'::text, 'failed'::text, 'passed_with_defects'::text, 'cancelled'::text]))),
    CONSTRAINT builder_inspections_title_check CHECK ((length(btrim(title)) > 0))
);


--
-- Name: builder_upsert_inspection(uuid, text, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_inspection(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _inspection_id uuid, _construction_case_id uuid, _construction_stage_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_inspections
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_inspections; v_row public.builder_inspections;
BEGIN
  IF _inspection_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_inspections WHERE id = _inspection_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_INSPECTION_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_inspections SET
      inspection_type = CASE WHEN _payload ? 'inspection_type' THEN _payload->>'inspection_type' ELSE inspection_type END,
      title = CASE WHEN _payload ? 'title' THEN _payload->>'title' ELSE title END,
      inspector_name = CASE WHEN _payload ? 'inspector_name' THEN _payload->>'inspector_name' ELSE inspector_name END,
      inspector_organisation = CASE WHEN _payload ? 'inspector_organisation' THEN _payload->>'inspector_organisation' ELSE inspector_organisation END,
      scheduled_for = CASE WHEN _payload ? 'scheduled_for' THEN (_payload->>'scheduled_for')::timestamptz ELSE scheduled_for END,
      outcome_notes = CASE WHEN _payload ? 'outcome_notes' THEN _payload->>'outcome_notes' ELSE outcome_notes END,
      is_customer_visible = CASE WHEN _payload ? 'is_customer_visible' THEN (_payload->>'is_customer_visible')::boolean ELSE is_customer_visible END,
      construction_stage_id = COALESCE(_construction_stage_id, construction_stage_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _construction_case_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_inspections(construction_case_id, construction_stage_id,
      inspection_type, title, inspector_name, inspector_organisation, scheduled_for,
      is_customer_visible)
    VALUES (_construction_case_id, _construction_stage_id,
      COALESCE(_payload->>'inspection_type','quality'), _payload->>'title',
      _payload->>'inspector_name', _payload->>'inspector_organisation',
      (_payload->>'scheduled_for')::timestamptz,
      COALESCE((_payload->>'is_customer_visible')::boolean, true))
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _inspection_id IS NULL THEN 'builder_inspection_scheduled'
         ELSE 'builder_inspection_updated' END,
    'inspection', v_row.id, public.builder_delivery_org(v_row.construction_case_id),
    _actor_builder_user_id,
    CASE WHEN _inspection_id IS NULL THEN NULL
         ELSE jsonb_build_object('scheduled_for', v_existing.scheduled_for) END,
    jsonb_build_object('title', v_row.title, 'status', v_row.status,
                       'scheduled_for', v_row.scheduled_for, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('construction_case_id', v_row.construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_lots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_lots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    stage_id uuid,
    lot_number text NOT NULL,
    plan_number text,
    land_area_sqm numeric(10,2),
    frontage_m numeric(8,2),
    titled boolean DEFAULT false NOT NULL,
    titled_at date,
    status text DEFAULT 'planned'::text NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_lots_frontage_m_check CHECK (((frontage_m IS NULL) OR (frontage_m > (0)::numeric))),
    CONSTRAINT builder_lots_land_area_sqm_check CHECK (((land_area_sqm IS NULL) OR (land_area_sqm > (0)::numeric))),
    CONSTRAINT builder_lots_lot_number_check CHECK ((length(btrim(lot_number)) > 0)),
    CONSTRAINT builder_lots_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'registered'::text, 'titled'::text, 'settled'::text, 'withdrawn'::text])))
);


--
-- Name: builder_upsert_lot(uuid, text, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_lot(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _lot_id uuid, _project_id uuid, _stage_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_lots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_lots; v_row public.builder_lots; v_org uuid;
BEGIN
  IF _lot_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_lots WHERE id = _lot_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_LOT_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_lots SET
      lot_number    = CASE WHEN _payload ? 'lot_number' THEN _payload->>'lot_number' ELSE lot_number END,
      plan_number   = CASE WHEN _payload ? 'plan_number' THEN _payload->>'plan_number' ELSE plan_number END,
      land_area_sqm = CASE WHEN _payload ? 'land_area_sqm' THEN (_payload->>'land_area_sqm')::numeric ELSE land_area_sqm END,
      frontage_m    = CASE WHEN _payload ? 'frontage_m' THEN (_payload->>'frontage_m')::numeric ELSE frontage_m END,
      titled        = CASE WHEN _payload ? 'titled' THEN (_payload->>'titled')::boolean ELSE titled END,
      titled_at     = CASE WHEN _payload ? 'titled_at' THEN (_payload->>'titled_at')::date ELSE titled_at END,
      status        = CASE WHEN _payload ? 'status' THEN _payload->>'status' ELSE status END,
      stage_id      = COALESCE(_stage_id, stage_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _project_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_REQUIRED';
    END IF;
    INSERT INTO public.builder_lots(project_id, stage_id, lot_number, plan_number,
      land_area_sqm, frontage_m, titled, status)
    VALUES (_project_id, _stage_id, _payload->>'lot_number', _payload->>'plan_number',
      (_payload->>'land_area_sqm')::numeric, (_payload->>'frontage_m')::numeric,
      COALESCE((_payload->>'titled')::boolean, false), COALESCE(_payload->>'status','planned'))
    RETURNING * INTO v_row;
  END IF;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = v_row.project_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _lot_id IS NULL THEN 'builder_lot_created' ELSE 'builder_lot_updated' END,
    'lot', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _lot_id IS NULL THEN NULL ELSE jsonb_build_object('lot_number', v_existing.lot_number) END,
    jsonb_build_object('lot_number', v_row.lot_number, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('project_id', v_row.project_id));
  RETURN v_row;
END $$;


--
-- Name: builder_construction_milestones; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_construction_milestones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    construction_stage_id uuid,
    name text NOT NULL,
    milestone_key text,
    status text DEFAULT 'pending'::text NOT NULL,
    planned_date date,
    achieved_date date,
    is_customer_visible boolean DEFAULT true NOT NULL,
    notes text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_construction_milestones_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_construction_milestones_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'achieved'::text, 'missed'::text, 'waived'::text])))
);


--
-- Name: TABLE builder_construction_milestones; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_construction_milestones IS 'A build programme event. Carries no amount and no payment flag — Finance owns build_progress_payments and every commission trigger.';


--
-- Name: builder_upsert_milestone(uuid, text, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_milestone(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _milestone_id uuid, _construction_case_id uuid, _construction_stage_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_construction_milestones
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_construction_milestones;
        v_row public.builder_construction_milestones; v_org uuid; v_txn uuid;
BEGIN
  IF _milestone_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_construction_milestones
    WHERE id = _milestone_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_MILESTONE_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    -- Status is NOT writable here: it moves only through the transition command.
    UPDATE public.builder_construction_milestones SET
      name = CASE WHEN _payload ? 'name' THEN _payload->>'name' ELSE name END,
      milestone_key = CASE WHEN _payload ? 'milestone_key' THEN _payload->>'milestone_key' ELSE milestone_key END,
      planned_date = CASE WHEN _payload ? 'planned_date' THEN (_payload->>'planned_date')::date ELSE planned_date END,
      is_customer_visible = CASE WHEN _payload ? 'is_customer_visible' THEN (_payload->>'is_customer_visible')::boolean ELSE is_customer_visible END,
      notes = CASE WHEN _payload ? 'notes' THEN _payload->>'notes' ELSE notes END,
      construction_stage_id = COALESCE(_construction_stage_id, construction_stage_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _construction_case_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_construction_milestones(construction_case_id,
      construction_stage_id, name, milestone_key, planned_date, is_customer_visible, notes)
    VALUES (_construction_case_id, _construction_stage_id, _payload->>'name',
      _payload->>'milestone_key', (_payload->>'planned_date')::date,
      COALESCE((_payload->>'is_customer_visible')::boolean, true), _payload->>'notes')
    RETURNING * INTO v_row;
  END IF;

  SELECT transaction_id INTO v_txn FROM public.builder_construction_cases
  WHERE id = v_row.construction_case_id;
  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = v_txn;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _milestone_id IS NULL THEN 'builder_milestone_created'
         ELSE 'builder_milestone_updated' END,
    'milestone', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _milestone_id IS NULL THEN NULL ELSE jsonb_build_object('name', v_existing.name) END,
    jsonb_build_object('name', v_row.name, 'status', v_row.status,
                       'row_version', v_row.row_version),
    _reason, jsonb_build_object('construction_case_id', v_row.construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_organisation_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_organisation_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organisation_id uuid NOT NULL,
    display_name text,
    primary_contact_name text,
    primary_contact_email text,
    primary_contact_phone text,
    timezone text DEFAULT 'Australia/Sydney'::text NOT NULL,
    default_landing_page text DEFAULT 'dashboard'::text NOT NULL,
    notify_on_defect boolean DEFAULT true NOT NULL,
    notify_on_inspection boolean DEFAULT true NOT NULL,
    notify_on_variation boolean DEFAULT true NOT NULL,
    notify_on_message boolean DEFAULT true NOT NULL,
    notify_on_task boolean DEFAULT true NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_organisation_settings_default_landing_page_check CHECK ((default_landing_page = ANY (ARRAY['dashboard'::text, 'projects'::text, 'inventory'::text, 'transactions'::text, 'construction'::text, 'documents'::text, 'messages'::text, 'tasks'::text]))),
    CONSTRAINT builder_organisation_settings_primary_contact_email_check CHECK (((primary_contact_email IS NULL) OR (primary_contact_email ~~ '%@%'::text)))
);


--
-- Name: TABLE builder_organisation_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_organisation_settings IS 'Display and notification preferences for one Builder organisation. Carries no access-control decision: membership and the permission matrix remain the only authority.';


--
-- Name: builder_upsert_organisation_settings(uuid, text, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_organisation_settings(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _organisation_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_organisation_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_organisation_settings;
        v_row public.builder_organisation_settings;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.builder_organisations WHERE id = _organisation_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORGANISATION_NOT_FOUND';
  END IF;

  SELECT * INTO v_existing FROM public.builder_organisation_settings
  WHERE organisation_id = _organisation_id FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_organisation_settings SET
      display_name = CASE WHEN _payload ? 'display_name'
        THEN _payload->>'display_name' ELSE display_name END,
      primary_contact_name = CASE WHEN _payload ? 'primary_contact_name'
        THEN _payload->>'primary_contact_name' ELSE primary_contact_name END,
      primary_contact_email = CASE WHEN _payload ? 'primary_contact_email'
        THEN NULLIF(_payload->>'primary_contact_email','') ELSE primary_contact_email END,
      primary_contact_phone = CASE WHEN _payload ? 'primary_contact_phone'
        THEN _payload->>'primary_contact_phone' ELSE primary_contact_phone END,
      timezone = CASE WHEN _payload ? 'timezone'
        THEN COALESCE(NULLIF(_payload->>'timezone',''), timezone) ELSE timezone END,
      default_landing_page = CASE WHEN _payload ? 'default_landing_page'
        THEN _payload->>'default_landing_page' ELSE default_landing_page END,
      notify_on_defect = CASE WHEN _payload ? 'notify_on_defect'
        THEN (_payload->>'notify_on_defect')::boolean ELSE notify_on_defect END,
      notify_on_inspection = CASE WHEN _payload ? 'notify_on_inspection'
        THEN (_payload->>'notify_on_inspection')::boolean ELSE notify_on_inspection END,
      notify_on_variation = CASE WHEN _payload ? 'notify_on_variation'
        THEN (_payload->>'notify_on_variation')::boolean ELSE notify_on_variation END,
      notify_on_message = CASE WHEN _payload ? 'notify_on_message'
        THEN (_payload->>'notify_on_message')::boolean ELSE notify_on_message END,
      notify_on_task = CASE WHEN _payload ? 'notify_on_task'
        THEN (_payload->>'notify_on_task')::boolean ELSE notify_on_task END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.builder_organisation_settings(organisation_id, display_name,
      primary_contact_name, primary_contact_email, primary_contact_phone, timezone,
      default_landing_page)
    VALUES (_organisation_id, _payload->>'display_name', _payload->>'primary_contact_name',
      NULLIF(_payload->>'primary_contact_email',''), _payload->>'primary_contact_phone',
      COALESCE(NULLIF(_payload->>'timezone',''), 'Australia/Sydney'),
      COALESCE(NULLIF(_payload->>'default_landing_page',''), 'dashboard'))
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_organisation_settings_saved',
    'organisation_settings', v_row.id, _organisation_id, _actor_builder_user_id,
    CASE WHEN v_existing.id IS NULL THEN NULL
         ELSE jsonb_build_object('timezone', v_existing.timezone,
                                 'default_landing_page', v_existing.default_landing_page) END,
    jsonb_build_object('timezone', v_row.timezone,
                       'default_landing_page', v_row.default_landing_page,
                       'row_version', v_row.row_version),
    _reason, '{}'::jsonb);
  RETURN v_row;
END $$;


--
-- Name: builder_progress_claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_progress_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    milestone_id uuid,
    claim_number text,
    claimed_amount numeric(14,2) NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    claimed_at timestamp with time zone,
    certified_at timestamp with time zone,
    certified_amount numeric(14,2),
    dispute_reason text,
    notes text,
    finance_payment_id uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_progress_claims_certified_amount_check CHECK (((certified_amount IS NULL) OR (certified_amount >= (0)::numeric))),
    CONSTRAINT builder_progress_claims_claimed_amount_check CHECK ((claimed_amount >= (0)::numeric)),
    CONSTRAINT builder_progress_claims_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'certified'::text, 'disputed'::text, 'withdrawn'::text, 'closed'::text])))
);


--
-- Name: TABLE builder_progress_claims; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_progress_claims IS 'What the Builder claimed and when. Finance owns receipt, reconciliation and commission on build_progress_payments; finance_payment_id is a pointer, never a copy.';


--
-- Name: builder_upsert_progress_claim(uuid, text, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_progress_claim(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _claim_id uuid, _construction_case_id uuid, _milestone_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_progress_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_progress_claims; v_row public.builder_progress_claims;
BEGIN
  IF _claim_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_progress_claims WHERE id = _claim_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CLAIM_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_progress_claims SET
      claim_number = CASE WHEN _payload ? 'claim_number' THEN _payload->>'claim_number' ELSE claim_number END,
      claimed_amount = CASE WHEN _payload ? 'claimed_amount' THEN (_payload->>'claimed_amount')::numeric ELSE claimed_amount END,
      certified_amount = CASE WHEN _payload ? 'certified_amount' THEN (_payload->>'certified_amount')::numeric ELSE certified_amount END,
      dispute_reason = CASE WHEN _payload ? 'dispute_reason' THEN _payload->>'dispute_reason' ELSE dispute_reason END,
      notes = CASE WHEN _payload ? 'notes' THEN _payload->>'notes' ELSE notes END,
      milestone_id = COALESCE(_milestone_id, milestone_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _construction_case_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    IF (_payload->>'claimed_amount') IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CLAIM_AMOUNT_REQUIRED';
    END IF;
    INSERT INTO public.builder_progress_claims(construction_case_id, milestone_id, claim_number,
      claimed_amount, notes)
    VALUES (_construction_case_id, _milestone_id, _payload->>'claim_number',
      (_payload->>'claimed_amount')::numeric, _payload->>'notes')
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _claim_id IS NULL THEN 'builder_progress_claim_created'
         ELSE 'builder_progress_claim_updated' END,
    'progress_claim', v_row.id, public.builder_delivery_org(v_row.construction_case_id),
    _actor_builder_user_id,
    CASE WHEN _claim_id IS NULL THEN NULL
         ELSE jsonb_build_object('status', v_existing.status) END,
    jsonb_build_object('status', v_row.status, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('construction_case_id', v_row.construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_projects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_projects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    development_id uuid,
    developer_organisation_id uuid,
    builder_organisation_id uuid,
    project_reference text,
    name text NOT NULL,
    project_type text DEFAULT 'house_and_land'::text NOT NULL,
    status text DEFAULT 'planning'::text NOT NULL,
    address_line text,
    suburb text,
    state text,
    postcode text,
    lot_number text,
    plan_number text,
    estimated_start_date date,
    estimated_completion_date date,
    actual_start_date date,
    actual_completion_date date,
    builder_notes text,
    npc_internal_notes text,
    shared_summary text,
    risk_flag boolean DEFAULT false NOT NULL,
    risk_notes text,
    row_version bigint DEFAULT 1 NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_projects_has_an_organisation CHECK (((developer_organisation_id IS NOT NULL) OR (builder_organisation_id IS NOT NULL))),
    CONSTRAINT builder_projects_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_projects_organisations_distinct CHECK (((developer_organisation_id IS NULL) OR (builder_organisation_id IS NULL) OR (developer_organisation_id <> builder_organisation_id))),
    CONSTRAINT builder_projects_postcode_check CHECK (((postcode IS NULL) OR (postcode ~ '^[0-9]{4}$'::text))),
    CONSTRAINT builder_projects_project_type_check CHECK ((project_type = ANY (ARRAY['house_and_land'::text, 'townhouse'::text, 'apartment'::text, 'duplex'::text, 'land_only'::text, 'knockdown_rebuild'::text, 'commercial'::text, 'other'::text]))),
    CONSTRAINT builder_projects_state_check CHECK (((state IS NULL) OR (state = ANY (ARRAY['NSW'::text, 'VIC'::text, 'QLD'::text, 'SA'::text, 'WA'::text, 'TAS'::text, 'NT'::text, 'ACT'::text])))),
    CONSTRAINT builder_projects_status_check CHECK ((status = ANY (ARRAY['planning'::text, 'pre_sales'::text, 'approved'::text, 'under_construction'::text, 'practical_completion'::text, 'handover'::text, 'completed'::text, 'on_hold'::text, 'cancelled'::text])))
);


--
-- Name: TABLE builder_projects; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_projects IS 'Builder Portal projects. Mirrors legal_matters. Carries TWO organisations: the developer and the builder. Organisation membership is never on its own an authorization boundary — an explicit builder_project_access grant is always required.';


--
-- Name: COLUMN builder_projects.builder_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_projects.builder_notes IS 'Builder-audience private notes. Never returned to the Command Centre contract.';


--
-- Name: COLUMN builder_projects.npc_internal_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_projects.npc_internal_notes IS 'Command Centre private notes. Never returned to the Builder Portal contract.';


--
-- Name: builder_upsert_project(uuid, text, uuid, uuid, jsonb, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_project(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _project_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _developer_organisation_id uuid DEFAULT NULL::uuid, _builder_organisation_id uuid DEFAULT NULL::uuid, _development_id uuid DEFAULT NULL::uuid, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_projects; v_row public.builder_projects; v_org_status text;
BEGIN
  IF _project_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_projects WHERE id = _project_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;

    -- Organisation columns are deliberately absent: they are set at creation and
    -- are protected afterwards by the org-drift trigger.
    UPDATE public.builder_projects SET
      project_reference           = CASE WHEN _payload ? 'project_reference' THEN _payload->>'project_reference' ELSE project_reference END,
      name                        = CASE WHEN _payload ? 'name' THEN _payload->>'name' ELSE name END,
      project_type                = CASE WHEN _payload ? 'project_type' THEN _payload->>'project_type' ELSE project_type END,
      address_line                = CASE WHEN _payload ? 'address_line' THEN _payload->>'address_line' ELSE address_line END,
      suburb                      = CASE WHEN _payload ? 'suburb' THEN _payload->>'suburb' ELSE suburb END,
      state                       = CASE WHEN _payload ? 'state' THEN _payload->>'state' ELSE state END,
      postcode                    = CASE WHEN _payload ? 'postcode' THEN _payload->>'postcode' ELSE postcode END,
      lot_number                  = CASE WHEN _payload ? 'lot_number' THEN _payload->>'lot_number' ELSE lot_number END,
      plan_number                 = CASE WHEN _payload ? 'plan_number' THEN _payload->>'plan_number' ELSE plan_number END,
      estimated_start_date        = CASE WHEN _payload ? 'estimated_start_date' THEN (_payload->>'estimated_start_date')::date ELSE estimated_start_date END,
      estimated_completion_date   = CASE WHEN _payload ? 'estimated_completion_date' THEN (_payload->>'estimated_completion_date')::date ELSE estimated_completion_date END,
      actual_start_date           = CASE WHEN _payload ? 'actual_start_date' THEN (_payload->>'actual_start_date')::date ELSE actual_start_date END,
      actual_completion_date      = CASE WHEN _payload ? 'actual_completion_date' THEN (_payload->>'actual_completion_date')::date ELSE actual_completion_date END,
      shared_summary              = CASE WHEN _payload ? 'shared_summary' THEN _payload->>'shared_summary' ELSE shared_summary END,
      risk_notes                  = CASE WHEN _payload ? 'risk_notes' THEN _payload->>'risk_notes' ELSE risk_notes END,
      risk_flag                   = CASE WHEN _payload ? 'risk_flag' THEN (_payload->>'risk_flag')::boolean ELSE risk_flag END,
      builder_notes               = CASE WHEN _payload ? 'builder_notes' THEN _payload->>'builder_notes' ELSE builder_notes END,
      npc_internal_notes          = CASE WHEN _payload ? 'npc_internal_notes' THEN _payload->>'npc_internal_notes' ELSE npc_internal_notes END,
      row_version                 = row_version + 1,
      updated_at                  = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_row;

    PERFORM public.builder_log_activity(
      _actor_user_id, _actor_type, 'builder_project_updated',
      'project', v_row.id,
      COALESCE(v_row.developer_organisation_id, v_row.builder_organisation_id),
      _actor_builder_user_id,
      jsonb_build_object('name', v_existing.name, 'row_version', v_existing.row_version),
      jsonb_build_object('name', v_row.name, 'row_version', v_row.row_version,
                         'fields', (SELECT jsonb_agg(k) FROM jsonb_object_keys(_payload) k)),
      _reason, '{}'::jsonb);
    RETURN v_row;
  END IF;

  IF _developer_organisation_id IS NULL AND _builder_organisation_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORGANISATION_REQUIRED';
  END IF;
  FOR v_org_status IN
    SELECT o.status FROM public.builder_organisations o
    WHERE o.id IN (_developer_organisation_id, _builder_organisation_id)
  LOOP
    IF v_org_status = 'closed' THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_ORG_CLOSED';
    END IF;
  END LOOP;

  INSERT INTO public.builder_projects(
    development_id, developer_organisation_id, builder_organisation_id,
    project_reference, name, project_type, address_line, suburb, state, postcode,
    lot_number, plan_number, estimated_start_date, estimated_completion_date,
    shared_summary, risk_notes, risk_flag, npc_internal_notes)
  VALUES (
    _development_id, _developer_organisation_id, _builder_organisation_id,
    _payload->>'project_reference', _payload->>'name',
    COALESCE(_payload->>'project_type', 'house_and_land'),
    _payload->>'address_line', _payload->>'suburb', _payload->>'state', _payload->>'postcode',
    _payload->>'lot_number', _payload->>'plan_number',
    (_payload->>'estimated_start_date')::date, (_payload->>'estimated_completion_date')::date,
    _payload->>'shared_summary', _payload->>'risk_notes',
    COALESCE((_payload->>'risk_flag')::boolean, false), _payload->>'npc_internal_notes')
  RETURNING * INTO v_row;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_project_created',
    'project', v_row.id,
    COALESCE(v_row.developer_organisation_id, v_row.builder_organisation_id),
    _actor_builder_user_id,
    NULL,
    jsonb_build_object('name', v_row.name, 'status', v_row.status,
                       'developer_organisation_id', v_row.developer_organisation_id,
                       'builder_organisation_id', v_row.builder_organisation_id),
    _reason, '{}'::jsonb);
  RETURN v_row;
END $$;


--
-- Name: builder_project_parties; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_project_parties (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    role text DEFAULT 'other'::text NOT NULL,
    name text NOT NULL,
    organisation text,
    email text,
    phone text,
    address text,
    reference text,
    is_primary_contact boolean DEFAULT false NOT NULL,
    notes text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_project_parties_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_project_parties_role_check CHECK ((role = ANY (ARRAY['developer'::text, 'builder'::text, 'site_supervisor'::text, 'project_manager'::text, 'sales_agent'::text, 'architect'::text, 'engineer'::text, 'certifier'::text, 'surveyor'::text, 'contractor'::text, 'purchaser'::text, 'other'::text])))
);


--
-- Name: builder_upsert_project_party(uuid, text, uuid, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_project_party(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _project_id uuid, _party_id uuid, _payload jsonb, _reason text DEFAULT NULL::text) RETURNS public.builder_project_parties
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.builder_project_parties;
  v_row public.builder_project_parties;
  v_project public.builder_projects;
BEGIN
  SELECT * INTO v_project FROM public.builder_projects WHERE id = _project_id;
  IF v_project.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
  END IF;
  IF NULLIF(btrim(COALESCE(_payload->>'name','')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PARTY_NAME_REQUIRED';
  END IF;

  IF _party_id IS NOT NULL THEN
    -- Scoped to the project: a party id belonging to another project matches
    -- no row and cannot be edited through this project's grant.
    SELECT * INTO v_existing FROM public.builder_project_parties
    WHERE id = _party_id AND project_id = _project_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PARTY_NOT_FOUND';
    END IF;

    UPDATE public.builder_project_parties SET
      role               = COALESCE(_payload->>'role', role),
      name               = _payload->>'name',
      organisation       = _payload->>'organisation',
      email              = _payload->>'email',
      phone              = _payload->>'phone',
      address            = _payload->>'address',
      reference          = _payload->>'reference',
      is_primary_contact = COALESCE((_payload->>'is_primary_contact')::boolean, false),
      notes              = _payload->>'notes',
      updated_at         = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_row;

    PERFORM public.builder_log_activity(
      _actor_user_id, _actor_type, 'builder_project_party_updated',
      'project_party', v_row.id,
      COALESCE(v_project.developer_organisation_id, v_project.builder_organisation_id),
      _actor_builder_user_id,
      jsonb_build_object('name', v_existing.name, 'role', v_existing.role),
      jsonb_build_object('name', v_row.name, 'role', v_row.role),
      _reason, jsonb_build_object('project_id', _project_id));
    RETURN v_row;
  END IF;

  INSERT INTO public.builder_project_parties(
    project_id, role, name, organisation, email, phone, address, reference,
    is_primary_contact, notes)
  VALUES (_project_id, COALESCE(_payload->>'role', 'other'), _payload->>'name',
          _payload->>'organisation', _payload->>'email', _payload->>'phone',
          _payload->>'address', _payload->>'reference',
          COALESCE((_payload->>'is_primary_contact')::boolean, false), _payload->>'notes')
  RETURNING * INTO v_row;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_project_party_added',
    'project_party', v_row.id,
    COALESCE(v_project.developer_organisation_id, v_project.builder_organisation_id),
    _actor_builder_user_id,
    NULL, jsonb_build_object('name', v_row.name, 'role', v_row.role),
    _reason, jsonb_build_object('project_id', _project_id));
  RETURN v_row;
END $$;


--
-- Name: builder_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    name text NOT NULL,
    stage_number text,
    description text,
    status text DEFAULT 'planned'::text NOT NULL,
    estimated_completion_date date,
    actual_completion_date date,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_stages_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_stages_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'released'::text, 'under_construction'::text, 'completed'::text, 'on_hold'::text, 'cancelled'::text])))
);


--
-- Name: TABLE builder_stages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_stages IS 'A project subdivides into stages. Reached through the parent project''s access grant — there is no separate stage access table.';


--
-- Name: builder_upsert_stage(uuid, text, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_stage(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _stage_id uuid, _project_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_stages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_stages; v_row public.builder_stages; v_org uuid;
BEGIN
  IF _stage_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_stages WHERE id = _stage_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STAGE_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_stages SET
      name         = CASE WHEN _payload ? 'name' THEN _payload->>'name' ELSE name END,
      stage_number = CASE WHEN _payload ? 'stage_number' THEN _payload->>'stage_number' ELSE stage_number END,
      description  = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      status       = CASE WHEN _payload ? 'status' THEN _payload->>'status' ELSE status END,
      estimated_completion_date = CASE WHEN _payload ? 'estimated_completion_date'
        THEN (_payload->>'estimated_completion_date')::date ELSE estimated_completion_date END,
      actual_completion_date = CASE WHEN _payload ? 'actual_completion_date'
        THEN (_payload->>'actual_completion_date')::date ELSE actual_completion_date END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _project_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_projects WHERE id = _project_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_stages(project_id, name, stage_number, description,
      status, estimated_completion_date)
    VALUES (_project_id, _payload->>'name', _payload->>'stage_number', _payload->>'description',
      COALESCE(_payload->>'status','planned'), (_payload->>'estimated_completion_date')::date)
    RETURNING * INTO v_row;
  END IF;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = v_row.project_id;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _stage_id IS NULL THEN 'builder_stage_created' ELSE 'builder_stage_updated' END,
    'stage', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _stage_id IS NULL THEN NULL
         ELSE jsonb_build_object('name', v_existing.name, 'status', v_existing.status) END,
    jsonb_build_object('name', v_row.name, 'status', v_row.status, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('project_id', v_row.project_id));
  RETURN v_row;
END $$;


--
-- Name: builder_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope_type text NOT NULL,
    scope_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    status text DEFAULT 'open'::text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    due_date date,
    completed_at timestamp with time zone,
    created_by_builder_user_id uuid,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_tasks_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT builder_tasks_scope_type_check CHECK ((scope_type = ANY (ARRAY['project'::text, 'unit'::text, 'transaction'::text, 'construction_case'::text]))),
    CONSTRAINT builder_tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'blocked'::text, 'done'::text, 'cancelled'::text]))),
    CONSTRAINT builder_tasks_title_check CHECK ((length(btrim(title)) > 0))
);


--
-- Name: builder_upsert_task(uuid, text, uuid, uuid, text, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_task(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _task_id uuid, _scope_type text, _scope_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_tasks; v_row public.builder_tasks; v_org uuid;
BEGIN
  IF _task_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_tasks WHERE id = _task_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TASK_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_tasks SET
      title = CASE WHEN _payload ? 'title' THEN _payload->>'title' ELSE title END,
      description = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      status = CASE WHEN _payload ? 'status' THEN _payload->>'status' ELSE status END,
      priority = CASE WHEN _payload ? 'priority' THEN _payload->>'priority' ELSE priority END,
      due_date = CASE WHEN _payload ? 'due_date' THEN (_payload->>'due_date')::date ELSE due_date END,
      completed_at = CASE WHEN _payload ? 'status' AND _payload->>'status' = 'done'
                          THEN COALESCE(completed_at, now())
                          WHEN _payload ? 'status' THEN NULL ELSE completed_at END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF NULLIF(btrim(COALESCE(_payload->>'title','')), '') IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TASK_TITLE_REQUIRED';
    END IF;
    v_org := public.builder_scope_org(_scope_type, _scope_id);
    IF v_org IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_SCOPE_TARGET_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_tasks(scope_type, scope_id, organisation_id, title, description,
      priority, due_date, created_by_builder_user_id)
    VALUES (_scope_type, _scope_id, v_org, _payload->>'title', _payload->>'description',
      COALESCE(_payload->>'priority','normal'), (_payload->>'due_date')::date,
      _actor_builder_user_id)
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _task_id IS NULL THEN 'builder_task_created' ELSE 'builder_task_updated' END,
    'task', v_row.id, v_row.organisation_id, _actor_builder_user_id,
    CASE WHEN _task_id IS NULL THEN NULL
         ELSE jsonb_build_object('status', v_existing.status, 'due_date', v_existing.due_date) END,
    jsonb_build_object('title', v_row.title, 'status', v_row.status,
                       'due_date', v_row.due_date, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('scope_type', v_row.scope_type, 'scope_id', v_row.scope_id));
  RETURN v_row;
END $$;


--
-- Name: builder_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    unit_id uuid,
    organisation_id uuid NOT NULL,
    transaction_reference text,
    transaction_type text DEFAULT 'off_the_plan'::text NOT NULL,
    status text DEFAULT 'lead'::text NOT NULL,
    purchaser_name text,
    purchaser_email text,
    purchaser_phone text,
    contract_price numeric(14,2),
    deposit_amount numeric(14,2),
    deposit_received boolean DEFAULT false NOT NULL,
    contract_issued_date date,
    contract_signed_date date,
    unconditional_date date,
    sunset_date date,
    estimated_settlement_date date,
    actual_settlement_date date,
    shared_summary text,
    builder_notes text,
    risk_flag boolean DEFAULT false NOT NULL,
    risk_notes text,
    row_version bigint DEFAULT 1 NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    connection_id uuid,
    remote_client_ref uuid,
    remote_client_label text,
    CONSTRAINT builder_transactions_connection_pair CHECK (((connection_id IS NULL) = (remote_client_ref IS NULL))),
    CONSTRAINT builder_transactions_contract_price_check CHECK (((contract_price IS NULL) OR (contract_price >= (0)::numeric))),
    CONSTRAINT builder_transactions_deposit_amount_check CHECK (((deposit_amount IS NULL) OR (deposit_amount >= (0)::numeric))),
    CONSTRAINT builder_transactions_status_check CHECK ((status = ANY (ARRAY['lead'::text, 'reserved'::text, 'contract_issued'::text, 'contract_signed'::text, 'unconditional'::text, 'construction'::text, 'practical_completion'::text, 'settled'::text, 'cancelled'::text, 'lapsed'::text]))),
    CONSTRAINT builder_transactions_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['off_the_plan'::text, 'house_and_land'::text, 'established'::text, 'land_only'::text, 'build_only'::text, 'knockdown_rebuild'::text, 'other'::text])))
);


--
-- Name: TABLE builder_transactions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_transactions IS 'The Builder''s view of one sale. Holds the customer-facing commercial position only: no cost, margin, commission, client financial position or AML determination.';


--
-- Name: builder_upsert_transaction(uuid, text, uuid, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_transaction(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _transaction_id uuid, _project_id uuid, _unit_id uuid DEFAULT NULL::uuid, _organisation_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_transactions; v_row public.builder_transactions;
BEGIN
  IF _transaction_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_transactions
    WHERE id = _transaction_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TRANSACTION_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    -- Status is NOT writable here: it moves only through the transition
    -- command, which writes history.
    UPDATE public.builder_transactions SET
      transaction_reference = CASE WHEN _payload ? 'transaction_reference'
        THEN _payload->>'transaction_reference' ELSE transaction_reference END,
      transaction_type = CASE WHEN _payload ? 'transaction_type'
        THEN _payload->>'transaction_type' ELSE transaction_type END,
      purchaser_name  = CASE WHEN _payload ? 'purchaser_name' THEN _payload->>'purchaser_name' ELSE purchaser_name END,
      purchaser_email = CASE WHEN _payload ? 'purchaser_email' THEN _payload->>'purchaser_email' ELSE purchaser_email END,
      purchaser_phone = CASE WHEN _payload ? 'purchaser_phone' THEN _payload->>'purchaser_phone' ELSE purchaser_phone END,
      contract_price  = CASE WHEN _payload ? 'contract_price' THEN (_payload->>'contract_price')::numeric ELSE contract_price END,
      deposit_amount  = CASE WHEN _payload ? 'deposit_amount' THEN (_payload->>'deposit_amount')::numeric ELSE deposit_amount END,
      deposit_received = CASE WHEN _payload ? 'deposit_received' THEN (_payload->>'deposit_received')::boolean ELSE deposit_received END,
      contract_issued_date = CASE WHEN _payload ? 'contract_issued_date' THEN (_payload->>'contract_issued_date')::date ELSE contract_issued_date END,
      contract_signed_date = CASE WHEN _payload ? 'contract_signed_date' THEN (_payload->>'contract_signed_date')::date ELSE contract_signed_date END,
      unconditional_date = CASE WHEN _payload ? 'unconditional_date' THEN (_payload->>'unconditional_date')::date ELSE unconditional_date END,
      sunset_date = CASE WHEN _payload ? 'sunset_date' THEN (_payload->>'sunset_date')::date ELSE sunset_date END,
      estimated_settlement_date = CASE WHEN _payload ? 'estimated_settlement_date' THEN (_payload->>'estimated_settlement_date')::date ELSE estimated_settlement_date END,
      actual_settlement_date = CASE WHEN _payload ? 'actual_settlement_date' THEN (_payload->>'actual_settlement_date')::date ELSE actual_settlement_date END,
      shared_summary = CASE WHEN _payload ? 'shared_summary' THEN _payload->>'shared_summary' ELSE shared_summary END,
      builder_notes  = CASE WHEN _payload ? 'builder_notes' THEN _payload->>'builder_notes' ELSE builder_notes END,
      risk_flag = CASE WHEN _payload ? 'risk_flag' THEN (_payload->>'risk_flag')::boolean ELSE risk_flag END,
      risk_notes = CASE WHEN _payload ? 'risk_notes' THEN _payload->>'risk_notes' ELSE risk_notes END,
      unit_id = COALESCE(_unit_id, unit_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _project_id IS NULL OR _organisation_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_projects WHERE id = _project_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_transactions(project_id, unit_id, organisation_id,
      transaction_reference, transaction_type, purchaser_name, purchaser_email, purchaser_phone,
      contract_price, deposit_amount, contract_issued_date, estimated_settlement_date,
      sunset_date, shared_summary, builder_notes)
    VALUES (_project_id, _unit_id, _organisation_id,
      _payload->>'transaction_reference', COALESCE(_payload->>'transaction_type','off_the_plan'),
      _payload->>'purchaser_name', _payload->>'purchaser_email', _payload->>'purchaser_phone',
      (_payload->>'contract_price')::numeric, (_payload->>'deposit_amount')::numeric,
      (_payload->>'contract_issued_date')::date, (_payload->>'estimated_settlement_date')::date,
      (_payload->>'sunset_date')::date, _payload->>'shared_summary', _payload->>'builder_notes')
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _transaction_id IS NULL THEN 'builder_transaction_created'
         ELSE 'builder_transaction_updated' END,
    'transaction', v_row.id, v_row.organisation_id, _actor_builder_user_id,
    CASE WHEN _transaction_id IS NULL THEN NULL
         ELSE jsonb_build_object('status', v_existing.status,
                                 'row_version', v_existing.row_version) END,
    jsonb_build_object('status', v_row.status, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('project_id', v_row.project_id, 'unit_id', v_row.unit_id));
  RETURN v_row;
END $$;


--
-- Name: builder_transaction_parties; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_transaction_parties (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    transaction_id uuid NOT NULL,
    role text DEFAULT 'other'::text NOT NULL,
    name text NOT NULL,
    organisation text,
    email text,
    phone text,
    reference text,
    is_primary_contact boolean DEFAULT false NOT NULL,
    notes text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_transaction_parties_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT builder_transaction_parties_role_check CHECK ((role = ANY (ARRAY['purchaser'::text, 'purchaser_solicitor'::text, 'vendor'::text, 'vendor_solicitor'::text, 'sales_agent'::text, 'broker'::text, 'guarantor'::text, 'other'::text])))
);


--
-- Name: builder_upsert_transaction_party(uuid, text, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_transaction_party(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _transaction_id uuid, _party_id uuid, _payload jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_transaction_parties
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_transaction_parties;
        v_row public.builder_transaction_parties; v_org uuid;
BEGIN
  IF NULLIF(btrim(COALESCE(_payload->>'name','')), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PARTY_NAME_REQUIRED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_transactions WHERE id = _transaction_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_TRANSACTION_NOT_FOUND';
  END IF;

  IF _party_id IS NOT NULL THEN
    -- Scoped to this transaction: an id belonging to another one matches no row.
    SELECT * INTO v_existing FROM public.builder_transaction_parties
    WHERE id = _party_id AND transaction_id = _transaction_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PARTY_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_transaction_parties SET
      role = COALESCE(_payload->>'role', role),
      name = _payload->>'name',
      organisation = _payload->>'organisation',
      email = _payload->>'email',
      phone = _payload->>'phone',
      reference = _payload->>'reference',
      is_primary_contact = COALESCE((_payload->>'is_primary_contact')::boolean, is_primary_contact),
      notes = _payload->>'notes'
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.builder_transaction_parties(transaction_id, role, name, organisation,
      email, phone, reference, is_primary_contact, notes)
    VALUES (_transaction_id, COALESCE(_payload->>'role','other'), _payload->>'name',
      _payload->>'organisation', _payload->>'email', _payload->>'phone', _payload->>'reference',
      COALESCE((_payload->>'is_primary_contact')::boolean, false), _payload->>'notes')
    RETURNING * INTO v_row;
  END IF;

  SELECT organisation_id INTO v_org FROM public.builder_transactions WHERE id = _transaction_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _party_id IS NULL THEN 'builder_transaction_party_added'
         ELSE 'builder_transaction_party_updated' END,
    'transaction_party', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _party_id IS NULL THEN NULL ELSE jsonb_build_object('name', v_existing.name) END,
    jsonb_build_object('name', v_row.name, 'role', v_row.role, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('transaction_id', _transaction_id));
  RETURN v_row;
END $$;


--
-- Name: builder_units; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_units (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    stage_id uuid,
    building_id uuid,
    lot_id uuid,
    unit_number text NOT NULL,
    unit_type text DEFAULT 'house'::text NOT NULL,
    bedrooms smallint,
    bathrooms numeric(3,1),
    car_spaces smallint,
    internal_area_sqm numeric(10,2),
    external_area_sqm numeric(10,2),
    level_number smallint,
    aspect text,
    availability_status text DEFAULT 'available'::text NOT NULL,
    release_status text DEFAULT 'unreleased'::text NOT NULL,
    released_at timestamp with time zone,
    estimated_completion_date date,
    description text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_units_aspect_check CHECK (((aspect IS NULL) OR (aspect = ANY (ARRAY['N'::text, 'NE'::text, 'E'::text, 'SE'::text, 'S'::text, 'SW'::text, 'W'::text, 'NW'::text])))),
    CONSTRAINT builder_units_availability_status_check CHECK ((availability_status = ANY (ARRAY['available'::text, 'on_hold'::text, 'reserved'::text, 'contracted'::text, 'settled'::text, 'withdrawn'::text]))),
    CONSTRAINT builder_units_bathrooms_check CHECK (((bathrooms IS NULL) OR ((bathrooms >= (0)::numeric) AND (bathrooms <= (20)::numeric)))),
    CONSTRAINT builder_units_bedrooms_check CHECK (((bedrooms IS NULL) OR ((bedrooms >= 0) AND (bedrooms <= 20)))),
    CONSTRAINT builder_units_car_spaces_check CHECK (((car_spaces IS NULL) OR ((car_spaces >= 0) AND (car_spaces <= 20)))),
    CONSTRAINT builder_units_external_area_sqm_check CHECK (((external_area_sqm IS NULL) OR (external_area_sqm >= (0)::numeric))),
    CONSTRAINT builder_units_internal_area_sqm_check CHECK (((internal_area_sqm IS NULL) OR (internal_area_sqm > (0)::numeric))),
    CONSTRAINT builder_units_release_status_check CHECK ((release_status = ANY (ARRAY['unreleased'::text, 'coming_soon'::text, 'released'::text, 'sold_out'::text]))),
    CONSTRAINT builder_units_unit_number_check CHECK ((length(btrim(unit_number)) > 0)),
    CONSTRAINT builder_units_unit_type_check CHECK ((unit_type = ANY (ARRAY['house'::text, 'townhouse'::text, 'apartment'::text, 'duplex'::text, 'land'::text, 'terrace'::text, 'other'::text])))
);


--
-- Name: TABLE builder_units; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_units IS 'Sellable inventory. Holds the customer-facing position only: no build cost, margin, supplier price or contractor price column exists on this table or any of its children.';


--
-- Name: builder_upsert_unit(uuid, text, uuid, uuid, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_unit(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _unit_id uuid, _project_id uuid, _stage_id uuid DEFAULT NULL::uuid, _building_id uuid DEFAULT NULL::uuid, _lot_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_units
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_units; v_row public.builder_units; v_org uuid;
BEGIN
  IF _unit_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_units WHERE id = _unit_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_UNIT_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    -- Availability and release are NOT writable here: they move only through
    -- their transition commands, which record history.
    UPDATE public.builder_units SET
      unit_number       = CASE WHEN _payload ? 'unit_number' THEN _payload->>'unit_number' ELSE unit_number END,
      unit_type         = CASE WHEN _payload ? 'unit_type' THEN _payload->>'unit_type' ELSE unit_type END,
      bedrooms          = CASE WHEN _payload ? 'bedrooms' THEN (_payload->>'bedrooms')::smallint ELSE bedrooms END,
      bathrooms         = CASE WHEN _payload ? 'bathrooms' THEN (_payload->>'bathrooms')::numeric ELSE bathrooms END,
      car_spaces        = CASE WHEN _payload ? 'car_spaces' THEN (_payload->>'car_spaces')::smallint ELSE car_spaces END,
      internal_area_sqm = CASE WHEN _payload ? 'internal_area_sqm' THEN (_payload->>'internal_area_sqm')::numeric ELSE internal_area_sqm END,
      external_area_sqm = CASE WHEN _payload ? 'external_area_sqm' THEN (_payload->>'external_area_sqm')::numeric ELSE external_area_sqm END,
      level_number      = CASE WHEN _payload ? 'level_number' THEN (_payload->>'level_number')::smallint ELSE level_number END,
      aspect            = CASE WHEN _payload ? 'aspect' THEN _payload->>'aspect' ELSE aspect END,
      estimated_completion_date = CASE WHEN _payload ? 'estimated_completion_date'
        THEN (_payload->>'estimated_completion_date')::date ELSE estimated_completion_date END,
      description       = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      stage_id          = COALESCE(_stage_id, stage_id),
      building_id       = COALESCE(_building_id, building_id),
      lot_id            = COALESCE(_lot_id, lot_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _project_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_projects WHERE id = _project_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PROJECT_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_units(project_id, stage_id, building_id, lot_id,
      unit_number, unit_type, bedrooms, bathrooms, car_spaces,
      internal_area_sqm, external_area_sqm, level_number, aspect,
      estimated_completion_date, description)
    VALUES (_project_id, _stage_id, _building_id, _lot_id,
      _payload->>'unit_number', COALESCE(_payload->>'unit_type','house'),
      (_payload->>'bedrooms')::smallint, (_payload->>'bathrooms')::numeric,
      (_payload->>'car_spaces')::smallint, (_payload->>'internal_area_sqm')::numeric,
      (_payload->>'external_area_sqm')::numeric, (_payload->>'level_number')::smallint,
      _payload->>'aspect', (_payload->>'estimated_completion_date')::date,
      _payload->>'description')
    RETURNING * INTO v_row;
  END IF;

  SELECT COALESCE(developer_organisation_id, builder_organisation_id) INTO v_org
  FROM public.builder_projects WHERE id = v_row.project_id;
  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _unit_id IS NULL THEN 'builder_unit_created' ELSE 'builder_unit_updated' END,
    'unit', v_row.id, v_org, _actor_builder_user_id,
    CASE WHEN _unit_id IS NULL THEN NULL
         ELSE jsonb_build_object('unit_number', v_existing.unit_number) END,
    jsonb_build_object('unit_number', v_row.unit_number, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('project_id', v_row.project_id));
  RETURN v_row;
END $$;


--
-- Name: builder_user_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_user_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    builder_user_id uuid NOT NULL,
    default_organisation_id uuid,
    landing_page text DEFAULT 'dashboard'::text NOT NULL,
    timezone text DEFAULT 'Australia/Sydney'::text NOT NULL,
    date_format text DEFAULT 'DD/MM/YYYY'::text NOT NULL,
    email_digest text DEFAULT 'daily'::text NOT NULL,
    notify_task_assigned boolean DEFAULT true NOT NULL,
    notify_message_posted boolean DEFAULT true NOT NULL,
    notify_status_change boolean DEFAULT true NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tour_completed_at timestamp with time zone,
    CONSTRAINT builder_user_preferences_date_format_check CHECK ((date_format = ANY (ARRAY['DD/MM/YYYY'::text, 'MM/DD/YYYY'::text, 'YYYY-MM-DD'::text]))),
    CONSTRAINT builder_user_preferences_email_digest_check CHECK ((email_digest = ANY (ARRAY['off'::text, 'daily'::text, 'weekly'::text]))),
    CONSTRAINT builder_user_preferences_landing_page_check CHECK ((landing_page = ANY (ARRAY['dashboard'::text, 'projects'::text, 'inventory'::text, 'transactions'::text, 'construction'::text, 'documents'::text, 'messages'::text, 'tasks'::text])))
);


--
-- Name: TABLE builder_user_preferences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_user_preferences IS 'One Builder user''s own display and notification preferences. default_organisation_id is a preference, never a grant — the session still resolves membership.';


--
-- Name: COLUMN builder_user_preferences.tour_completed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_user_preferences.tour_completed_at IS 'When this user finished or skipped the guided onboarding tour. NULL means the tour is still due. Server-stamped; never supplied by the browser.';


--
-- Name: builder_upsert_user_preferences(uuid, text, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_user_preferences(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_user_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_user_preferences; v_row public.builder_user_preferences;
        v_default_org uuid;
BEGIN
  IF _actor_builder_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_PREFERENCE_OWNER_REQUIRED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_portal_users WHERE id = _actor_builder_user_id) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_USER_NOT_FOUND';
  END IF;

  IF _payload ? 'default_organisation_id' THEN
    v_default_org := NULLIF(_payload->>'default_organisation_id','')::uuid;
    IF v_default_org IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.builder_active_membership(
                         _actor_builder_user_id, v_default_org)) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_NOT_A_MEMBER';
    END IF;
  END IF;

  SELECT * INTO v_existing FROM public.builder_user_preferences
  WHERE builder_user_id = _actor_builder_user_id FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_user_preferences SET
      default_organisation_id = CASE WHEN _payload ? 'default_organisation_id'
        THEN v_default_org ELSE default_organisation_id END,
      landing_page = CASE WHEN _payload ? 'landing_page'
        THEN _payload->>'landing_page' ELSE landing_page END,
      timezone = CASE WHEN _payload ? 'timezone'
        THEN COALESCE(NULLIF(_payload->>'timezone',''), timezone) ELSE timezone END,
      date_format = CASE WHEN _payload ? 'date_format'
        THEN _payload->>'date_format' ELSE date_format END,
      email_digest = CASE WHEN _payload ? 'email_digest'
        THEN _payload->>'email_digest' ELSE email_digest END,
      notify_task_assigned = CASE WHEN _payload ? 'notify_task_assigned'
        THEN (_payload->>'notify_task_assigned')::boolean ELSE notify_task_assigned END,
      notify_message_posted = CASE WHEN _payload ? 'notify_message_posted'
        THEN (_payload->>'notify_message_posted')::boolean ELSE notify_message_posted END,
      notify_status_change = CASE WHEN _payload ? 'notify_status_change'
        THEN (_payload->>'notify_status_change')::boolean ELSE notify_status_change END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.builder_user_preferences(builder_user_id, default_organisation_id,
      landing_page, timezone, date_format, email_digest)
    VALUES (_actor_builder_user_id, v_default_org,
      COALESCE(NULLIF(_payload->>'landing_page',''), 'dashboard'),
      COALESCE(NULLIF(_payload->>'timezone',''), 'Australia/Sydney'),
      COALESCE(NULLIF(_payload->>'date_format',''), 'DD/MM/YYYY'),
      COALESCE(NULLIF(_payload->>'email_digest',''), 'daily'))
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type, 'builder_user_preferences_saved',
    'user_preferences', v_row.id, v_row.default_organisation_id, _actor_builder_user_id,
    CASE WHEN v_existing.id IS NULL THEN NULL
         ELSE jsonb_build_object('landing_page', v_existing.landing_page) END,
    jsonb_build_object('landing_page', v_row.landing_page,
                       'email_digest', v_row.email_digest,
                       'row_version', v_row.row_version),
    _reason, '{}'::jsonb);
  RETURN v_row;
END $$;


--
-- Name: builder_variations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_variations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    variation_number text,
    title text NOT NULL,
    description text,
    origin text DEFAULT 'purchaser'::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    variation_price numeric(14,2),
    time_impact_days integer DEFAULT 0 NOT NULL,
    submitted_at timestamp with time zone,
    decided_at timestamp with time zone,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_variations_origin_check CHECK ((origin = ANY (ARRAY['purchaser'::text, 'builder'::text, 'consultant'::text, 'authority'::text, 'site_condition'::text, 'other'::text]))),
    CONSTRAINT builder_variations_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'superseded'::text]))),
    CONSTRAINT builder_variations_title_check CHECK ((length(btrim(title)) > 0)),
    CONSTRAINT builder_variations_variation_price_check CHECK (((variation_price IS NULL) OR (variation_price >= (0)::numeric)))
);


--
-- Name: TABLE builder_variations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_variations IS 'A change to the build. Carries the customer-facing variation price only: no cost, margin, supplier price or contractor price.';


--
-- Name: builder_upsert_variation(uuid, text, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_variation(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _variation_id uuid, _construction_case_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_variations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_variations; v_row public.builder_variations;
BEGIN
  IF _variation_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_variations WHERE id = _variation_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_VARIATION_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_variations SET
      variation_number = CASE WHEN _payload ? 'variation_number' THEN _payload->>'variation_number' ELSE variation_number END,
      title = CASE WHEN _payload ? 'title' THEN _payload->>'title' ELSE title END,
      description = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      origin = CASE WHEN _payload ? 'origin' THEN _payload->>'origin' ELSE origin END,
      variation_price = CASE WHEN _payload ? 'variation_price' THEN (_payload->>'variation_price')::numeric ELSE variation_price END,
      time_impact_days = CASE WHEN _payload ? 'time_impact_days' THEN (_payload->>'time_impact_days')::integer ELSE time_impact_days END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _construction_case_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_REQUIRED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_variations(construction_case_id, variation_number, title,
      description, origin, variation_price, time_impact_days)
    VALUES (_construction_case_id, _payload->>'variation_number', _payload->>'title',
      _payload->>'description', COALESCE(_payload->>'origin','purchaser'),
      (_payload->>'variation_price')::numeric,
      COALESCE((_payload->>'time_impact_days')::integer, 0))
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _variation_id IS NULL THEN 'builder_variation_created'
         ELSE 'builder_variation_updated' END,
    'variation', v_row.id, public.builder_delivery_org(v_row.construction_case_id),
    _actor_builder_user_id,
    CASE WHEN _variation_id IS NULL THEN NULL ELSE jsonb_build_object('title', v_existing.title) END,
    jsonb_build_object('title', v_row.title, 'status', v_row.status,
                       'row_version', v_row.row_version),
    _reason, jsonb_build_object('construction_case_id', v_row.construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_variation_approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_variation_approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    variation_id uuid NOT NULL,
    approver_role text DEFAULT 'purchaser'::text NOT NULL,
    approver_name text NOT NULL,
    decision text DEFAULT 'pending'::text NOT NULL,
    decided_at timestamp with time zone,
    comments text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_variation_approvals_approver_name_check CHECK ((length(btrim(approver_name)) > 0)),
    CONSTRAINT builder_variation_approvals_approver_role_check CHECK ((approver_role = ANY (ARRAY['purchaser'::text, 'builder'::text, 'developer'::text, 'consultant'::text, 'authority'::text]))),
    CONSTRAINT builder_variation_approvals_decision_check CHECK ((decision = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: builder_upsert_variation_approval(uuid, text, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_variation_approval(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _approval_id uuid, _variation_id uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_variation_approvals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_variation_approvals;
        v_row public.builder_variation_approvals; v_case uuid;
BEGIN
  IF _approval_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_variation_approvals
    WHERE id = _approval_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_APPROVAL_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_variation_approvals SET
      approver_role = CASE WHEN _payload ? 'approver_role' THEN _payload->>'approver_role' ELSE approver_role END,
      approver_name = CASE WHEN _payload ? 'approver_name' THEN _payload->>'approver_name' ELSE approver_name END,
      decision = CASE WHEN _payload ? 'decision' THEN _payload->>'decision' ELSE decision END,
      decided_at = CASE WHEN _payload ? 'decision' AND _payload->>'decision' <> 'pending'
                        THEN COALESCE(decided_at, now()) ELSE decided_at END,
      comments = CASE WHEN _payload ? 'comments' THEN _payload->>'comments' ELSE comments END
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF _variation_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_VARIATION_NOT_FOUND';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.builder_variations WHERE id = _variation_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_VARIATION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_variation_approvals(variation_id, approver_role, approver_name,
      decision, comments)
    VALUES (_variation_id, COALESCE(_payload->>'approver_role','purchaser'),
      _payload->>'approver_name', COALESCE(_payload->>'decision','pending'),
      _payload->>'comments')
    RETURNING * INTO v_row;
  END IF;

  SELECT construction_case_id INTO v_case FROM public.builder_variations
  WHERE id = v_row.variation_id;
  INSERT INTO public.builder_delivery_status_history(construction_case_id, entity_kind, entity_id,
    from_status, to_status, changed_by_type, changed_by_builder_user_id, changed_by_user_id, reason)
  VALUES (v_case, 'variation_approval', v_row.id,
    CASE WHEN _approval_id IS NULL THEN NULL ELSE v_existing.decision END,
    v_row.decision, _actor_type, _actor_builder_user_id, _actor_user_id, _reason);

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _approval_id IS NULL THEN 'builder_variation_approval_added'
         ELSE 'builder_variation_approval_updated' END,
    'variation_approval', v_row.id, public.builder_delivery_org(v_case), _actor_builder_user_id,
    CASE WHEN _approval_id IS NULL THEN NULL
         ELSE jsonb_build_object('decision', v_existing.decision) END,
    jsonb_build_object('decision', v_row.decision, 'row_version', v_row.row_version),
    _reason, jsonb_build_object('variation_id', v_row.variation_id));
  RETURN v_row;
END $$;


--
-- Name: builder_warranty_claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_warranty_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_case_id uuid NOT NULL,
    warranty_id uuid,
    claim_number text,
    title text NOT NULL,
    description text,
    status text DEFAULT 'lodged'::text NOT NULL,
    lodged_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    rectified_at timestamp with time zone,
    decision_notes text,
    row_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT builder_warranty_claims_status_check CHECK ((status = ANY (ARRAY['lodged'::text, 'under_review'::text, 'accepted'::text, 'rejected'::text, 'rectified'::text, 'closed'::text]))),
    CONSTRAINT builder_warranty_claims_title_check CHECK ((length(btrim(title)) > 0))
);


--
-- Name: builder_upsert_warranty_claim(uuid, text, uuid, uuid, uuid, uuid, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_upsert_warranty_claim(_actor_user_id uuid, _actor_type text, _actor_builder_user_id uuid, _claim_id uuid, _construction_case_id uuid, _warranty_id uuid DEFAULT NULL::uuid, _payload jsonb DEFAULT '{}'::jsonb, _expected_version bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text) RETURNS public.builder_warranty_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing public.builder_warranty_claims; v_row public.builder_warranty_claims;
BEGIN
  IF _claim_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.builder_warranty_claims WHERE id = _claim_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_WARRANTY_CLAIM_NOT_FOUND';
    END IF;
    IF _expected_version IS NULL OR v_existing.row_version <> _expected_version THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_STALE_WRITE',
        DETAIL = format('current_version=%s', v_existing.row_version);
    END IF;
    UPDATE public.builder_warranty_claims SET
      claim_number = CASE WHEN _payload ? 'claim_number' THEN _payload->>'claim_number' ELSE claim_number END,
      title = CASE WHEN _payload ? 'title' THEN _payload->>'title' ELSE title END,
      description = CASE WHEN _payload ? 'description' THEN _payload->>'description' ELSE description END,
      decision_notes = CASE WHEN _payload ? 'decision_notes' THEN _payload->>'decision_notes' ELSE decision_notes END,
      warranty_id = COALESCE(_warranty_id, warranty_id)
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.builder_construction_cases WHERE id = _construction_case_id) THEN
      RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_CONSTRUCTION_NOT_FOUND';
    END IF;
    INSERT INTO public.builder_warranty_claims(construction_case_id, warranty_id, claim_number,
      title, description)
    VALUES (_construction_case_id, _warranty_id, _payload->>'claim_number', _payload->>'title',
      _payload->>'description')
    RETURNING * INTO v_row;
  END IF;

  PERFORM public.builder_log_activity(
    _actor_user_id, _actor_type,
    CASE WHEN _claim_id IS NULL THEN 'builder_warranty_claim_lodged'
         ELSE 'builder_warranty_claim_updated' END,
    'warranty_claim', v_row.id, public.builder_delivery_org(v_row.construction_case_id),
    _actor_builder_user_id,
    CASE WHEN _claim_id IS NULL THEN NULL ELSE jsonb_build_object('title', v_existing.title) END,
    jsonb_build_object('title', v_row.title, 'status', v_row.status,
                       'row_version', v_row.row_version),
    _reason, jsonb_build_object('construction_case_id', v_row.construction_case_id));
  RETURN v_row;
END $$;


--
-- Name: builder_visible_activity(uuid, uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_visible_activity(_user_id uuid, _organisation_id uuid, _entity_type text DEFAULT NULL::text, _entity_id uuid DEFAULT NULL::uuid, _limit integer DEFAULT 100) RETURNS TABLE(id uuid, action text, entity_type text, entity_id uuid, actor_type text, reason text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT l.id, l.action, l.entity_type, l.entity_id, l.actor_type, l.reason, l.created_at
  FROM public.builder_portal_activity_log l
  WHERE l.organisation_id = _organisation_id
    AND (_entity_type IS NULL OR l.entity_type = _entity_type)
    AND (_entity_id IS NULL OR l.entity_id = _entity_id)
    AND public.builder_can_see_activity(_user_id, l.entity_type, l.entity_id)
  ORDER BY l.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(_limit, 100), 1), 200);
$$;


--
-- Name: builder_workspace_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.builder_workspace_summary(_user_id uuid, _organisation_id uuid) RETURNS TABLE(projects bigint, units bigint, transactions bigint, construction_cases bigint, open_defects bigint, documents bigint, open_conversations bigint, open_tasks bigint, overdue_tasks bigint, unread_messages bigint, unread_notifications bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH p AS (SELECT project_id FROM public.builder_accessible_projects(
               _user_id, _organisation_id, 'projects')),
       u AS (SELECT unit_id FROM public.builder_accessible_units(
               _user_id, _organisation_id, 'inventory')),
       t AS (SELECT transaction_id FROM public.builder_accessible_transactions(
               _user_id, _organisation_id, 'transactions')),
       c AS (SELECT construction_case_id FROM public.builder_accessible_construction_cases(
               _user_id, _organisation_id, 'construction')),
       d AS (SELECT document_id FROM public.builder_accessible_documents(_user_id)),
       v AS (SELECT conversation_id FROM public.builder_accessible_conversations(_user_id)),
       k AS (SELECT task_id FROM public.builder_accessible_tasks(_user_id)),
       n AS (SELECT * FROM public.builder_unread_counts(_user_id))
  SELECT
    (SELECT count(*) FROM p),
    (SELECT count(*) FROM u),
    (SELECT count(*) FROM t),
    (SELECT count(*) FROM c),
    (SELECT count(*) FROM public.builder_defects x
     WHERE x.construction_case_id IN (SELECT construction_case_id FROM c)
       AND x.status NOT IN ('closed','rejected','verified')),
    (SELECT count(*) FROM d),
    (SELECT count(*) FROM public.builder_conversations x
     WHERE x.id IN (SELECT conversation_id FROM v) AND x.status = 'open'),
    (SELECT count(*) FROM public.builder_tasks x
     WHERE x.id IN (SELECT task_id FROM k) AND x.status NOT IN ('done','cancelled')),
    (SELECT count(*) FROM public.builder_tasks x
     WHERE x.id IN (SELECT task_id FROM k) AND x.status NOT IN ('done','cancelled')
       AND x.due_date IS NOT NULL AND x.due_date < CURRENT_DATE),
    (SELECT unread_messages FROM n),
    (SELECT unread_notifications FROM n);
$$;


--
-- Name: claim_builder_document_processing_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_builder_document_processing_jobs(_worker_id text, _limit integer DEFAULT 10) RETURNS TABLE(job_id uuid, version_id uuid, storage_bucket text, storage_path text, declared_mime_type text, declared_byte_size bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    UPDATE public.document_processing_jobs j
    SET status = 'processing', attempts = j.attempts + 1,
        locked_by = _worker_id, locked_at = now(), updated_at = now()
    WHERE j.id IN (
      SELECT j2.id FROM public.document_processing_jobs j2
      WHERE j2.portal = 'builder'
        AND j2.status IN ('queued','failed')
        AND j2.attempts < 5
        AND j2.available_at <= now()
      ORDER BY j2.available_at, j2.created_at
      FOR UPDATE SKIP LOCKED
      LIMIT GREATEST(1, LEAST(COALESCE(_limit, 10), 50)))
    RETURNING j.id, j.builder_document_version_id)
  SELECT c.id, v.id, v.storage_bucket, v.storage_path, v.content_type, v.byte_size
  FROM claimed c
  JOIN public.builder_document_versions v ON v.id = c.builder_document_version_id;
END $$;


--
-- Name: builder_stock_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_stock_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organisation_id uuid NOT NULL,
    upload_id uuid,
    first_upload_id uuid,
    created_by_builder_user_id uuid,
    builder_project_id uuid,
    builder_unit_id uuid,
    external_reference text,
    development_name text,
    project_name text,
    address_line text,
    suburb text,
    state text,
    postcode text,
    lot_number text,
    unit_number text,
    bedrooms numeric(4,1),
    bathrooms numeric(4,1),
    car_spaces numeric(4,1),
    property_type text,
    land_size_sqm numeric(12,2),
    building_size_sqm numeric(12,2),
    price numeric(14,2),
    price_display text,
    availability_status text DEFAULT 'available'::text NOT NULL,
    expected_completion text,
    description text,
    lifecycle_status text DEFAULT 'active'::text NOT NULL,
    enrichment_status text DEFAULT 'pending'::text NOT NULL,
    enriched_at timestamp with time zone,
    primary_image_id uuid,
    source_row jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    source_provenance_result jsonb,
    image_work_stage text DEFAULT 'source'::text NOT NULL,
    image_work_claim_until timestamp with time zone,
    image_work_next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    image_work_attempts integer DEFAULT 0 NOT NULL,
    image_work_last_result text,
    image_work_last_error text,
    image_work_updated_at timestamp with time zone,
    pending_patch jsonb,
    pending_upload_id uuid,
    manual_stats jsonb,
    CONSTRAINT builder_stock_items_availability_status_check CHECK ((availability_status = ANY (ARRAY['available'::text, 'on_hold'::text, 'reserved'::text, 'contracted'::text, 'sold'::text, 'settled'::text, 'withdrawn'::text, 'unknown'::text]))),
    CONSTRAINT builder_stock_items_bathrooms_check CHECK (((bathrooms IS NULL) OR ((bathrooms >= (0)::numeric) AND (bathrooms <= (20)::numeric)))),
    CONSTRAINT builder_stock_items_bedrooms_check CHECK (((bedrooms IS NULL) OR ((bedrooms >= (0)::numeric) AND (bedrooms <= (20)::numeric)))),
    CONSTRAINT builder_stock_items_building_size_sqm_check CHECK (((building_size_sqm IS NULL) OR (building_size_sqm >= (0)::numeric))),
    CONSTRAINT builder_stock_items_car_spaces_check CHECK (((car_spaces IS NULL) OR ((car_spaces >= (0)::numeric) AND (car_spaces <= (20)::numeric)))),
    CONSTRAINT builder_stock_items_enrichment_status_check CHECK ((enrichment_status = ANY (ARRAY['pending'::text, 'enriching'::text, 'complete'::text, 'partial'::text, 'failed'::text]))),
    CONSTRAINT builder_stock_items_image_work_stage_check CHECK ((image_work_stage = ANY (ARRAY['source'::text, 'eligibility'::text, 'sanitization'::text, 'fallback'::text, 'settled'::text]))),
    CONSTRAINT builder_stock_items_land_size_sqm_check CHECK (((land_size_sqm IS NULL) OR (land_size_sqm >= (0)::numeric))),
    CONSTRAINT builder_stock_items_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'staged'::text, 'archived'::text]))),
    CONSTRAINT builder_stock_items_manual_stats_shape CHECK (((manual_stats IS NULL) OR ((jsonb_typeof(manual_stats) = 'object'::text) AND (manual_stats ? 'values'::text) AND (jsonb_typeof((manual_stats -> 'values'::text)) = 'object'::text) AND ((manual_stats -> 'values'::text) <> '{}'::jsonb) AND (((manual_stats -> 'values'::text) - ARRAY['bedrooms'::text, 'bathrooms'::text, 'car_spaces'::text, 'building_size_sqm'::text, 'land_size_sqm'::text]) = '{}'::jsonb) AND ((((manual_stats -> 'values'::text) -> 'bedrooms'::text) IS NULL) OR (jsonb_typeof(((manual_stats -> 'values'::text) -> 'bedrooms'::text)) = 'number'::text)) AND ((((manual_stats -> 'values'::text) -> 'bathrooms'::text) IS NULL) OR (jsonb_typeof(((manual_stats -> 'values'::text) -> 'bathrooms'::text)) = 'number'::text)) AND ((((manual_stats -> 'values'::text) -> 'car_spaces'::text) IS NULL) OR (jsonb_typeof(((manual_stats -> 'values'::text) -> 'car_spaces'::text)) = 'number'::text)) AND ((((manual_stats -> 'values'::text) -> 'building_size_sqm'::text) IS NULL) OR (jsonb_typeof(((manual_stats -> 'values'::text) -> 'building_size_sqm'::text)) = 'number'::text)) AND ((((manual_stats -> 'values'::text) -> 'land_size_sqm'::text) IS NULL) OR (jsonb_typeof(((manual_stats -> 'values'::text) -> 'land_size_sqm'::text)) = 'number'::text))))),
    CONSTRAINT builder_stock_items_postcode_check CHECK (((postcode IS NULL) OR (postcode ~ '^[0-9]{4}$'::text))),
    CONSTRAINT builder_stock_items_price_check CHECK (((price IS NULL) OR (price >= (0)::numeric))),
    CONSTRAINT builder_stock_items_property_type_check CHECK (((property_type IS NULL) OR (property_type = ANY (ARRAY['house'::text, 'townhouse'::text, 'apartment'::text, 'duplex'::text, 'land'::text, 'terrace'::text, 'house_and_land'::text, 'other'::text])))),
    CONSTRAINT builder_stock_items_state_check CHECK (((state IS NULL) OR (state = ANY (ARRAY['NSW'::text, 'VIC'::text, 'QLD'::text, 'SA'::text, 'WA'::text, 'TAS'::text, 'NT'::text, 'ACT'::text]))))
);


--
-- Name: TABLE builder_stock_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_stock_items IS 'Builder-supplied stock exposed in the Property Marketplace. Links to builder_projects / builder_units rather than copying them; organisation_id is the ownership boundary and is enforced server-side on every read.';


--
-- Name: COLUMN builder_stock_items.source_provenance_result; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_items.source_provenance_result IS 'Terminal result of the source-provenance repair for this property when its linked package was read successfully and named no image for it. Shape: {result, provenance_version, package_reference, source_anchor, detail, checked_at}. Honoured only while provenance_version, package_reference and source_anchor all still match; any change re-opens the question. Never written for an operational failure, and never a substitute for a builder_stock_item_images row.';


--
-- Name: COLUMN builder_stock_items.manual_stats; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_items.manual_stats IS 'Configuration figures stated by the builder where their stock list did not. Overlaid on read by applyManualStats; deliberately NOT named by writablePatch, so a re-import cannot overwrite a builder''s own correction. Shape: {values:{bedrooms,bathrooms,car_spaces,building_size_sqm,land_size_sqm}, recorded_at, recorded_by}.';


--
-- Name: claim_builder_stock_image_work(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_builder_stock_image_work(p_limit integer DEFAULT 1, p_lease_seconds integer DEFAULT 120, p_organisation_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.builder_stock_items
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  UPDATE public.builder_stock_items AS i
     SET image_work_claim_until = now() + make_interval(secs => greatest(p_lease_seconds, 1)),
         image_work_attempts = i.image_work_attempts + 1,
         image_work_next_attempt_at = now() + make_interval(
           secs => least(30 * power(2, least(i.image_work_attempts, 7))::integer, 3600)),
         image_work_updated_at = now()
   WHERE i.id IN (
     SELECT c.id
       FROM public.builder_stock_items AS c
      -- STAGED ROWS ARE PROCESSED. They are invisible to the Marketplace and
      -- must still reach readiness, or a replacement upload could never
      -- publish and its properties would be stranded unseen for ever.
      WHERE c.lifecycle_status IN ('active', 'staged')
        AND c.image_work_stage <> 'settled'
        AND c.image_work_next_attempt_at <= now()
        AND (c.image_work_claim_until IS NULL OR c.image_work_claim_until < now())
        AND (p_organisation_id IS NULL OR c.organisation_id = p_organisation_id)
      ORDER BY c.image_work_next_attempt_at, c.id
      LIMIT greatest(coalesce(p_limit, 1), 0)
        FOR UPDATE SKIP LOCKED
   )
  RETURNING i.*;
$$;


--
-- Name: claim_builder_stock_settlement_lease(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_builder_stock_settlement_lease(p_seconds integer DEFAULT 120, p_holder text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  UPDATE public.builder_stock_settlement_lease
     SET leased_until = now() + make_interval(secs => greatest(p_seconds, 1)),
         leased_at = now(),
         holder = left(coalesce(p_holder, 'settler'), 64)
   WHERE id = true
     AND leased_until <= now()
  RETURNING true;
$$;


--
-- Name: complete_builder_document_processing(uuid, text, text, text, bigint, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_builder_document_processing(_job_id uuid, _worker_id text, _sha256 text, _detected_mime text, _byte_size bigint, _scan_status text, _scan_provider text, _scan_reference text, _scan_details jsonb, _error text DEFAULT NULL::text) RETURNS public.builder_document_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  j public.document_processing_jobs; v public.builder_document_versions;
  v_org uuid; v_previous uuid; v_clean boolean;
BEGIN
  IF _scan_status NOT IN ('clean','infected','error') THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_UNKNOWN_SCAN_STATUS';
  END IF;

  SELECT * INTO j FROM public.document_processing_jobs
  WHERE id = _job_id AND portal = 'builder' FOR UPDATE;
  IF j.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_JOB_NOT_FOUND';
  END IF;

  SELECT * INTO v FROM public.builder_document_versions
  WHERE id = j.builder_document_version_id FOR UPDATE;
  IF v.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='BUILDER_DOCUMENT_VERSION_NOT_FOUND';
  END IF;

  v_clean := (_scan_status = 'clean');

  IF v_clean THEN
    SELECT current_version_id INTO v_previous FROM public.builder_documents WHERE id = v.document_id;

    UPDATE public.builder_document_versions
    SET sha256 = _sha256, detected_mime_type = _detected_mime,
        byte_size = COALESCE(_byte_size, byte_size),
        malware_scan_status = 'clean', lifecycle_status = 'available',
        scan_provider = _scan_provider, scan_reference = _scan_reference,
        scan_details = COALESCE(_scan_details, '{}'::jsonb), scanned_at = now()
    WHERE id = v.id RETURNING * INTO v;

    -- Only a clean version becomes current; an infected upload can never
    -- displace the version people are already relying on.
    UPDATE public.builder_documents
    SET current_version_id = v.id WHERE id = v.document_id;

    IF v_previous IS NOT NULL AND v_previous <> v.id THEN
      UPDATE public.builder_document_versions
      SET lifecycle_status = 'superseded'
      WHERE id = v_previous AND lifecycle_status = 'available';
    END IF;
  ELSE
    UPDATE public.builder_document_versions
    SET sha256 = CASE WHEN _sha256 ~ '^[0-9a-f]{64}$' THEN _sha256 ELSE sha256 END,
        detected_mime_type = _detected_mime,
        malware_scan_status = CASE WHEN _scan_status = 'infected' THEN 'infected' ELSE 'error' END,
        -- An infected file is rejected permanently. A scanner error keeps the
        -- version quarantined so the job can be retried.
        lifecycle_status = CASE WHEN _scan_status = 'infected' THEN 'rejected' ELSE 'quarantined' END,
        scan_provider = _scan_provider, scan_reference = _scan_reference,
        scan_details = COALESCE(_scan_details, '{}'::jsonb), scanned_at = now()
    WHERE id = v.id RETURNING * INTO v;
  END IF;

  -- A scanner error is retryable with backoff until the attempt ceiling, after
  -- which the job is dead-lettered and shows up in builder_document_scan_health.
  UPDATE public.document_processing_jobs
  SET status = CASE
        WHEN _scan_status <> 'error' THEN 'succeeded'
        WHEN j.attempts >= 5 THEN 'dead_lettered'
        ELSE 'failed' END,
      available_at = CASE
        WHEN _scan_status = 'error' AND j.attempts < 5
        THEN now() + (interval '1 minute' * power(2, LEAST(j.attempts, 5)))
        ELSE available_at END,
      last_error = left(_error, 2000),
      updated_at = now()
  WHERE id = j.id;

  SELECT organisation_id INTO v_org FROM public.builder_documents WHERE id = v.document_id;

  PERFORM public.builder_log_activity(
    NULL, 'system',
    CASE WHEN v_clean THEN 'builder_document_scan_passed'
         WHEN _scan_status = 'infected' THEN 'builder_document_malware_detected'
         ELSE 'builder_document_scan_failed' END,
    'document_version', v.id, v_org, NULL,
    NULL,
    jsonb_build_object('lifecycle_status', v.lifecycle_status,
                       'malware_scan_status', v.malware_scan_status,
                       'scan_provider', v.scan_provider),
    left(_error, 500),
    jsonb_build_object('document_id', v.document_id, 'job_id', j.id));

  RETURN v;
END $_$;


--
-- Name: complete_builder_stock_image_work(uuid, text, text, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_builder_stock_image_work(p_item_id uuid, p_next_stage text DEFAULT NULL::text, p_result text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 0, p_reset_attempts boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  UPDATE public.builder_stock_items AS i
     SET image_work_stage = coalesce(p_next_stage, i.image_work_stage),
         /*
          * A RESUMABLE STEP THAT PROGRESSED MUST NOT ACCUMULATE BACKOFF.
          *
          * Some stages are legitimately resumable: a source read that stored
          * what it could and will store the rest next tick has made progress,
          * and counting that as a failed attempt would push a HEALTHY
          * property's backoff towards the hour cap for doing exactly what it
          * is supposed to do.
          *
          * The asymmetry is the design. A worker that RETURNS and reports
          * progress clears the count; a worker that is KILLED returns nothing,
          * clears nothing, and the count it raised inside the claim stands.
          * The counter measures silence, not work.
          *
          * It is still not a package retirement counter and must never be used
          * as one — `MAX_PACKAGE_ATTEMPTS = 2` lives in
          * `source_provenance_result`, is written before the download begins,
          * and is untouched by anything here.
          */
         image_work_attempts = CASE
           WHEN coalesce(p_reset_attempts, false) THEN 0
           WHEN p_next_stage IS NOT NULL AND p_next_stage IS DISTINCT FROM i.image_work_stage
             THEN 0
           ELSE i.image_work_attempts
         END,
         image_work_claim_until = NULL,
         image_work_next_attempt_at =
           now() + make_interval(secs => greatest(coalesce(p_retry_after_seconds, 0), 0)),
         image_work_last_result = left(p_result, 200),
         image_work_last_error = left(p_error, 500),
         image_work_updated_at = now()
   WHERE i.id = p_item_id
  RETURNING true;
$$;


--
-- Name: consume_builder_portal_reset_attempt(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_builder_portal_reset_attempt(p_email text, p_token_hash text, p_max integer) RETURNS TABLE(status text, user_id uuid, invite_accepted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid; v_hash text; v_expires_at timestamptz; v_attempts integer;
  v_invite_accepted timestamptz;
BEGIN
  -- Every RETURNING target is table-qualified: this function's OUT columns
  -- include `user_id` and `invite_accepted_at`, and an unqualified reference in
  -- RETURNING resolves ambiguously against them, failing at runtime.
  UPDATE public.builder_portal_users u
     SET reset_attempts = COALESCE(u.reset_attempts, 0) + 1
   WHERE u.id = (
     SELECT b.id FROM public.builder_portal_users b
      WHERE lower(btrim(b.email)) = lower(btrim(p_email))
        AND b.reset_token_hash IS NOT NULL
        AND b.is_active AND b.revoked_at IS NULL
      LIMIT 1)
  RETURNING u.id, u.reset_token_hash, u.reset_token_expires_at, u.reset_attempts, u.invite_accepted_at
       INTO v_id, v_hash, v_expires_at, v_attempts, v_invite_accepted;

  IF v_id IS NULL THEN
    status := 'not_found'; user_id := NULL; invite_accepted_at := NULL;
    RETURN NEXT; RETURN;
  END IF;

  IF v_attempts > p_max THEN
    status := 'too_many'; user_id := v_id; invite_accepted_at := v_invite_accepted;
    RETURN NEXT; RETURN;
  END IF;

  IF v_expires_at IS NULL OR v_expires_at < now() THEN
    status := 'expired'; user_id := v_id; invite_accepted_at := v_invite_accepted;
    RETURN NEXT; RETURN;
  END IF;

  -- Hash comparison. A mismatch is reported as not_found so a caller cannot
  -- distinguish "wrong code" from "no such account" (Phase 0 SEC-12).
  IF p_token_hash IS NULL OR v_hash IS DISTINCT FROM p_token_hash THEN
    status := 'not_found'; user_id := NULL; invite_accepted_at := NULL;
    RETURN NEXT; RETURN;
  END IF;

  status := 'ok'; user_id := v_id; invite_accepted_at := v_invite_accepted;
  RETURN NEXT;
END $$;


--
-- Name: ensure_builder_stock_settlement_scheduled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_builder_stock_settlement_scheduled() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    RETURN false;
  END IF;
  IF EXISTS (
    SELECT 1 FROM cron.job
     WHERE jobname = 'settle-builder-stock-marketplace-eligibility'
  ) THEN
    RETURN false;
  END IF;

  /*
   * EVERY MINUTE, AND ONLY WHILE THERE IS WORK.
   *
   * The tick's own gate is what makes this safe to run often: it counts both
   * queues and unschedules itself the moment they are empty, so a minute is the
   * cadence of an ACTIVE import and not a standing load. An idle deployment has
   * no job at all.
   */
  PERFORM cron.schedule(
    'settle-builder-stock-marketplace-eligibility',
    '* * * * *',
    $job$SELECT public.settle_builder_stock_marketplace_eligibility_tick();$job$
  );
  RETURN true;
END;
$_$;


--
-- Name: get_builder_operational_health(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_builder_operational_health(_organisation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_alerts jsonb := '[]'::jsonb; v_events jsonb := '{}'::jsonb;
BEGIN
  IF to_regclass('public.portal_operational_alerts') IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC), '[]'::jsonb) INTO v_alerts
    FROM (
      SELECT a.id, a.alert_type, a.severity, a.status, a.summary, a.created_at, e.correlation_id
      FROM public.portal_operational_alerts a
      JOIN public.portal_operational_events e ON e.id = a.event_id
      WHERE a.status = 'open' AND e.portal = 'builder'
      ORDER BY a.created_at DESC LIMIT 100
    ) x;

    SELECT jsonb_build_object(
      'events_24h', count(*),
      'failures_24h', count(*) FILTER (WHERE success = false),
      'critical_24h', count(*) FILTER (WHERE severity = 'critical')) INTO v_events
    FROM public.portal_operational_events
    WHERE portal = 'builder' AND occurred_at >= now() - interval '24 hours';
  END IF;

  RETURN jsonb_build_object(
    'portal','builder',
    'organisation_id', _organisation_id,
    'open_alerts', v_alerts,
    'event_summary', v_events,
    -- A session is live only while it is unrevoked and inside BOTH its idle and
    -- absolute expiry, matching resolveBuilderSessionToken.
    'sessions_active', (SELECT count(*) FROM public.builder_portal_sessions
                        WHERE revoked_at IS NULL
                          AND idle_expires_at > now()
                          AND absolute_expires_at > now()),
    'evaluated_at', now());
END $$;


--
-- Name: guard_builder_document_version_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_builder_document_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='BUILDER_DOCUMENT_VERSION_IMMUTABLE',
      DETAIL='document versions are append-only';
  END IF;

  IF OLD.malware_scan_status IN ('clean','infected')
     AND (OLD.document_id      IS DISTINCT FROM NEW.document_id
       OR OLD.version_number   IS DISTINCT FROM NEW.version_number
       OR OLD.storage_bucket   IS DISTINCT FROM NEW.storage_bucket
       OR OLD.storage_path     IS DISTINCT FROM NEW.storage_path
       OR OLD.sha256           IS DISTINCT FROM NEW.sha256
       OR OLD.byte_size        IS DISTINCT FROM NEW.byte_size
       OR OLD.detected_mime_type IS DISTINCT FROM NEW.detected_mime_type)
  THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='BUILDER_DOCUMENT_VERSION_IMMUTABLE',
      DETAIL='a scanned version cannot have its identity or content rewritten';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: publish_builder_stock_upload(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_builder_stock_upload(p_upload_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ready boolean;
  v_staged bigint;
  v_outstanding bigint;
  v_replaces uuid[];
  v_published integer := 0;
  v_archived integer := 0;
  v_patched integer := 0;
  v_deleted timestamptz;
  v_already timestamptz;
BEGIN
  SELECT deleted_at, published_at INTO v_deleted, v_already
    FROM public.builder_stock_uploads WHERE id = p_upload_id;

  IF v_already IS NOT NULL THEN
    RETURN jsonb_build_object('published', false, 'reason', 'already_published');
  END IF;

  -- A deleted upload is not a stock list, and a superseded one is somebody's
  -- abandoned draft. Neither may move the Marketplace.
  IF v_deleted IS NOT NULL THEN
    RETURN jsonb_build_object('published', false, 'reason', 'deleted');
  END IF;

  IF public.builder_stock_upload_superseded(p_upload_id) THEN
    RETURN jsonb_build_object('published', false, 'reason', 'superseded');
  END IF;

  SELECT staged, source_outstanding, ready
    INTO v_staged, v_outstanding, v_ready
    FROM public.builder_stock_publication_readiness(p_upload_id);

  IF NOT coalesce(v_ready, false) THEN
    RETURN jsonb_build_object(
      'published', false, 'reason', 'not_ready',
      'staged', coalesce(v_staged, 0), 'source_outstanding', coalesce(v_outstanding, 0));
  END IF;

  SELECT coalesce(replaces_upload_ids, '{}') INTO v_replaces
    FROM public.builder_stock_uploads WHERE id = p_upload_id;

  /*
   * 1. APPLY EVERY HELD-BACK PATCH — FIRST, and the order is load-bearing.
   *
   * This is what re-points a matched row's `upload_id` to this upload, and step
   * 3 archives by `upload_id`. Do it after, and every kept property would look
   * like a removed one.
   *
   * EVERY COLUMN IS NAMED. A `jsonb_populate_record` over the whole row would
   * let whatever ended up in that column write any field of the table, which is
   * mass assignment through a jsonb door.
   */
  UPDATE public.builder_stock_items AS i
     SET external_reference = coalesce(i.pending_patch->>'external_reference', i.external_reference),
         development_name   = coalesce(i.pending_patch->>'development_name', i.development_name),
         project_name       = coalesce(i.pending_patch->>'project_name', i.project_name),
         address_line       = coalesce(i.pending_patch->>'address_line', i.address_line),
         suburb             = coalesce(i.pending_patch->>'suburb', i.suburb),
         state              = coalesce(i.pending_patch->>'state', i.state),
         postcode           = coalesce(i.pending_patch->>'postcode', i.postcode),
         lot_number         = coalesce(i.pending_patch->>'lot_number', i.lot_number),
         unit_number        = coalesce(i.pending_patch->>'unit_number', i.unit_number),
         bedrooms           = coalesce((i.pending_patch->>'bedrooms')::numeric, i.bedrooms),
         bathrooms          = coalesce((i.pending_patch->>'bathrooms')::numeric, i.bathrooms),
         car_spaces         = coalesce((i.pending_patch->>'car_spaces')::numeric, i.car_spaces),
         property_type      = coalesce(i.pending_patch->>'property_type', i.property_type),
         land_size_sqm      = coalesce((i.pending_patch->>'land_size_sqm')::numeric, i.land_size_sqm),
         building_size_sqm  = coalesce((i.pending_patch->>'building_size_sqm')::numeric, i.building_size_sqm),
         price              = coalesce((i.pending_patch->>'price')::numeric, i.price),
         price_display      = coalesce(i.pending_patch->>'price_display', i.price_display),
         expected_completion= coalesce(i.pending_patch->>'expected_completion', i.expected_completion),
         description        = coalesce(i.pending_patch->>'description', i.description),
         availability_status= coalesce(i.pending_patch->>'availability_status', i.availability_status),
         builder_project_id = coalesce((i.pending_patch->>'builder_project_id')::uuid, i.builder_project_id),
         builder_unit_id    = coalesce((i.pending_patch->>'builder_unit_id')::uuid, i.builder_unit_id),
         source_row         = coalesce(i.pending_patch->'source_row', i.source_row),
         upload_id          = p_upload_id,
         last_seen_at       = now(),
         pending_patch      = NULL,
         pending_upload_id  = NULL,
         updated_at         = now()
   WHERE i.pending_upload_id = p_upload_id;
  GET DIAGNOSTICS v_patched = ROW_COUNT;

  -- 2. Promote this upload's staged rows.
  UPDATE public.builder_stock_items
     SET lifecycle_status = 'active', updated_at = now()
   WHERE upload_id = p_upload_id AND lifecycle_status = 'staged';
  GET DIAGNOSTICS v_published = ROW_COUNT;

  -- 3. Archive what the superseded uploads still supply. Anything still
  --    carrying one of their ids is a property the new list did not contain.
  IF array_length(v_replaces, 1) IS NOT NULL THEN
    UPDATE public.builder_stock_items
       SET lifecycle_status = 'archived', updated_at = now()
     WHERE lifecycle_status = 'active'
       AND upload_id = ANY(v_replaces)
       AND upload_id <> p_upload_id;
    GET DIAGNOSTICS v_archived = ROW_COUNT;
  END IF;

  UPDATE public.builder_stock_uploads
     SET published_at = now(), updated_at = now()
   WHERE id = p_upload_id AND published_at IS NULL;

  RETURN jsonb_build_object(
    'published', true, 'promoted', v_published,
    'patched', v_patched, 'archived', v_archived);
END;
$$;


--
-- Name: publish_ready_builder_stock_uploads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_ready_builder_stock_uploads() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_upload record;
  v_result jsonb;
  v_published integer := 0;
  v_considered integer := 0;
  v_details jsonb := '[]'::jsonb;
BEGIN
  FOR v_upload IN
    SELECT u.id
      FROM public.builder_stock_uploads AS u
     WHERE u.published_at IS NULL
       AND u.deleted_at IS NULL
       AND NOT public.builder_stock_upload_superseded(u.id)
     ORDER BY u.created_at
  LOOP
    v_considered := v_considered + 1;
    v_result := public.publish_builder_stock_upload(v_upload.id);
    IF (v_result->>'published')::boolean THEN
      v_published := v_published + 1;
      v_details := v_details || jsonb_build_object('upload_id', v_upload.id, 'result', v_result);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'considered', v_considered, 'published', v_published, 'cutovers', v_details);
END;
$$;


--
-- Name: release_builder_stock_settlement_lease(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_builder_stock_settlement_lease() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  UPDATE public.builder_stock_settlement_lease
     SET leased_until = now() - interval '1 second'
   WHERE id = true;
$$;


--
-- Name: reopen_builder_stock_runtime_failures(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_builder_stock_runtime_failures() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reopened integer := 0;
  v_runtime integer;
BEGIN
  SELECT image_runtime_version INTO v_runtime
    FROM public.builder_stock_settlement_target
   LIMIT 1;
  IF v_runtime IS NULL THEN
    RETURN 0;
  END IF;

  WITH reopened AS (
    UPDATE public.builder_stock_items AS i
       SET image_work_stage = 'source',
           image_work_next_attempt_at = now(),
           image_work_claim_until = NULL,
           image_work_attempts = 0,
           -- Asked again, so the terminal enrichment verdict must not keep it
           -- out of the fallback queue. Same reasoning as the sibling reopen.
           enrichment_status = 'pending',
           image_work_updated_at = now(),
           updated_at = now()
     WHERE i.lifecycle_status IN ('active', 'staged')
       AND i.image_work_stage = 'settled'
       AND i.primary_image_id IS NULL
       AND EXISTS (
         SELECT 1
           FROM jsonb_each(
             coalesce(i.source_provenance_result -> 'branches', '{}'::jsonb)) AS b(k, v)
          WHERE (
            -- A step that began and never came back.
            v ->> 'result' = 'package_recovery_attempt'
            AND coalesce((v ->> 'runtime_version')::integer, 0) < v_runtime
          )
          OR (
            -- A retirement we caused, stamped with the runtime that caused it.
            v ->> 'result' = 'no_deterministic_image'
            AND v ? 'runtime_version'
            AND coalesce((v ->> 'runtime_version')::integer, 0) < v_runtime
          )
       )
    RETURNING i.id
  )
  SELECT count(*) INTO v_reopened FROM reopened;

  RETURN coalesce(v_reopened, 0);
END;
$$;


--
-- Name: FUNCTION reopen_builder_stock_runtime_failures(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reopen_builder_stock_runtime_failures() IS 'Returns settled, pictureless properties to the source rung when the worker that failed their documents has been superseded. Reopens ONLY branches carrying evidence of our own failure — never a dead link, never a document that answered.';


--
-- Name: reopen_builder_stock_stranded_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_builder_stock_stranded_items() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reopened integer := 0;
  v_generation timestamptz;
BEGIN
  SELECT image_ladder_generation_at INTO v_generation
    FROM public.builder_stock_settlement_target
   LIMIT 1;

  WITH reopened AS (
    UPDATE public.builder_stock_items AS i
       SET image_work_stage = 'eligibility',
           image_work_next_attempt_at = now(),
           image_work_claim_until = NULL,
           image_work_attempts = 0,
           -- A property is being asked again, so the terminal enrichment
           -- verdict from the previous generation must not keep it out of the
           -- fallback queue `settleFallbackImages` reads.
           enrichment_status = 'pending',
           image_work_updated_at = now(),
           updated_at = now()
     WHERE i.lifecycle_status IN ('active', 'staged')
       AND i.image_work_stage = 'settled'
       AND i.primary_image_id IS NULL
       AND (
         -- Its own evidence was re-judged after it concluded. (20261026000000)
         EXISTS (
           SELECT 1
             FROM public.builder_stock_item_images AS x
            WHERE x.stock_item_id = i.id
              AND x.updated_at > i.image_work_updated_at
         )
         -- Or the engine that drew the conclusion has since changed.
         OR (v_generation IS NOT NULL AND i.image_work_updated_at < v_generation)
       )
    RETURNING i.id
  )
  /*
   * AND THE BOOKKEEPING THE OLD LADDER LEFT BEHIND GOES WITH IT.
   *
   * Re-opening a property is not enough on its own. `nextImageStage` reads
   * `stage-status` rows to decide which rungs are still owed, and the rows the
   * previous generation wrote say the rungs were climbed. On the measured
   * upload, 86 properties hold a `google_maps` row reading "This property has
   * no street address to look up" — a refusal caused by a MISSING INPUT that
   * this generation supplies. Leave those rows and every property re-opens,
   * finds both stages recorded as done, and settles blank again immediately:
   * the fix would run, cost a claim each, and change nothing.
   *
   * These rows are pure bookkeeping. A `stage-status` row never carries an
   * image — a real Street View is `streetview`, a real search result is its own
   * URL — so deleting them destroys no picture and no provenance. What it
   * destroys is a conclusion that, by the definition of a new generation, no
   * longer stands.
   *
   * SCOPED TO THE TWO PAID STAGES AND TO `stage-status` ALONE. Nothing here can
   * touch a builder-supplied row, a stored photograph, or the package attempt
   * counters that stage 1 keeps.
   */
  , cleared AS (
    DELETE FROM public.builder_stock_item_images AS x
     USING reopened AS r
     WHERE x.stock_item_id = r.id
       AND x.source_reference = 'stage-status'
       AND x.source_stage IN ('internet_search', 'google_maps')
    RETURNING x.id
  )
  -- A data-modifying CTE always runs to completion whether or not the primary
  -- query reads it, so `cleared` is executed and the count is the PROPERTIES.
  SELECT count(*) INTO v_reopened FROM reopened;

  RETURN v_reopened;
END;
$$;


--
-- Name: set_builder_stock_eligibility_target(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_builder_stock_eligibility_target(p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_version integer;
BEGIN
  INSERT INTO public.builder_stock_settlement_target (id, marketplace_eligibility_version)
  VALUES (true, p_version)
  ON CONFLICT (id) DO UPDATE
    SET marketplace_eligibility_version =
          GREATEST(public.builder_stock_settlement_target.marketplace_eligibility_version,
                   EXCLUDED.marketplace_eligibility_version),
        updated_at = now()
  RETURNING marketplace_eligibility_version INTO v_version;

  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    IF NOT EXISTS (
      SELECT 1 FROM cron.job
       WHERE jobname = 'settle-builder-stock-marketplace-eligibility'
    ) THEN
      PERFORM cron.schedule(
        'settle-builder-stock-marketplace-eligibility',
        '*/5 * * * *',
        $job$SELECT public.settle_builder_stock_marketplace_eligibility_tick();$job$
      );
    END IF;
  END IF;

  RETURN v_version;
END;
$_$;


--
-- Name: FUNCTION set_builder_stock_eligibility_target(p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_builder_stock_eligibility_target(p_version integer) IS 'Raise the Builder Stock display-eligibility target (never lowers it) and reschedule the settlement sweep if it had unscheduled itself. Call this from the same migration that ships a MARKETPLACE_ELIGIBILITY_VERSION bump.';


--
-- Name: set_builder_stock_sanitization_target(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_builder_stock_sanitization_target(p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_version integer;
BEGIN
  INSERT INTO public.builder_stock_settlement_target (id, image_sanitization_version)
  VALUES (true, p_version)
  ON CONFLICT (id) DO UPDATE
    SET image_sanitization_version =
          GREATEST(public.builder_stock_settlement_target.image_sanitization_version,
                   EXCLUDED.image_sanitization_version),
        updated_at = now()
  RETURNING image_sanitization_version INTO v_version;

  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    IF NOT EXISTS (
      SELECT 1 FROM cron.job
       WHERE jobname = 'settle-builder-stock-marketplace-eligibility'
    ) THEN
      PERFORM cron.schedule(
        'settle-builder-stock-marketplace-eligibility',
        '*/5 * * * *',
        $job$SELECT public.settle_builder_stock_marketplace_eligibility_tick();$job$
      );
    END IF;
  END IF;

  RETURN v_version;
END;
$_$;


--
-- Name: FUNCTION set_builder_stock_sanitization_target(p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_builder_stock_sanitization_target(p_version integer) IS 'Raise the Builder Stock overlay-removal target (never lowers it) and reschedule the settlement sweep if it had unscheduled itself. Call this from the same migration that ships a SANITIZATION_VERSION bump.';


--
-- Name: set_builder_stock_source_images_target(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_builder_stock_source_images_target(p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_version integer;
BEGIN
  INSERT INTO public.builder_stock_settlement_target (id, source_images_version)
  VALUES (true, p_version)
  ON CONFLICT (id) DO UPDATE
    SET source_images_version =
          GREATEST(public.builder_stock_settlement_target.source_images_version,
                   EXCLUDED.source_images_version),
        updated_at = now()
  RETURNING source_images_version INTO v_version;

  -- Through the function that OWNS the schedule rather than a second copy of
  -- the cron string: `ensure_builder_stock_settlement_scheduled` is already
  -- idempotent, already checks for pg_cron, and is what every other caller
  -- uses. Two places naming a schedule is how two schedules come to differ —
  -- the eligibility setter still says `*/5 * * * *` while the job this repair
  -- actually runs on is every minute.
  PERFORM public.ensure_builder_stock_settlement_scheduled();

  RETURN v_version;
END;
$$;


--
-- Name: FUNCTION set_builder_stock_source_images_target(p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_builder_stock_source_images_target(p_version integer) IS 'Raises the extractor (provenance) settlement target and re-schedules the builder stock sweep, because the sweep unschedules itself when idle. Monotonic: the target never goes down.';


--
-- Name: settle_builder_stock_marketplace_eligibility_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_builder_stock_marketplace_eligibility_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_target integer;
  v_sanitization integer;
  v_provenance integer;
  v_outstanding integer;
  v_fallback integer;
  v_item_work integer;
  v_publications integer;
  v_upload_completion integer;
  v_dispatch integer;
  i integer;
BEGIN
  PERFORM public.publish_ready_builder_stock_uploads();
  PERFORM public.reopen_builder_stock_stranded_items();
  -- And the properties a superseded worker failed on, which the sibling above
  -- cannot see: it reopens on a changed ladder, this on a changed runtime.
  PERFORM public.reopen_builder_stock_runtime_failures();

  SELECT marketplace_eligibility_version, image_sanitization_version,
         source_images_version
    INTO v_target, v_sanitization, v_provenance
    FROM public.builder_stock_settlement_target
   LIMIT 1;
  v_target := coalesce(v_target, 0);
  v_sanitization := coalesce(v_sanitization, 0);
  v_provenance := coalesce(v_provenance, 0);

  SELECT count(*) INTO v_outstanding
    FROM public.builder_stock_uploads
   WHERE deleted_at IS NULL
     AND (coalesce(marketplace_eligibility_settled_version, -1) < v_target
          OR coalesce(image_sanitization_settled_version, -1) < v_sanitization
          -- WAS `source_images_settled_version IS NULL`. An upload re-read
          -- under an older extractor is outstanding in exactly the way an
          -- upload never read is, and only the second was countable.
          OR coalesce(source_images_settled_version, -1) < v_provenance);

  SELECT count(*) INTO v_fallback
    FROM public.builder_stock_items
   WHERE lifecycle_status IN ('active', 'staged')
     AND enrichment_status IN ('pending', 'enriching');

  SELECT count(*) INTO v_item_work
    FROM public.builder_stock_items
   WHERE lifecycle_status IN ('active', 'staged')
     AND image_work_stage <> 'settled';

  v_publications := public.builder_stock_publications_pending();

  SELECT count(*) INTO v_upload_completion
    FROM public.builder_stock_uploads u
   WHERE u.deleted_at IS NULL
     AND u.status IN ('enriching', 'partially_complete')
     AND NOT EXISTS (
       SELECT 1
         FROM public.builder_stock_items it
        WHERE it.upload_id = u.id
          AND it.lifecycle_status = 'active'
          AND it.enrichment_status IN ('pending', 'enriching')
     );

  IF v_outstanding + v_fallback + v_item_work + v_publications
     + v_upload_completion = 0 THEN
    IF EXISTS (
      SELECT 1 FROM cron.job
       WHERE jobname = 'settle-builder-stock-marketplace-eligibility'
    ) THEN
      PERFORM cron.unschedule('settle-builder-stock-marketplace-eligibility');
    END IF;
    RETURN;
  END IF;

  -- FIXED, and deliberately not derived from any count above: a backlog is a
  -- reason to work steadily, never a licence to start more workers inside one
  -- memory ceiling.
  v_dispatch := 2;

  FOR i IN 1..v_dispatch LOOP
    PERFORM public.cron_invoke_signed_function(
      'builder-stock-image-settler', '{}'::jsonb, 'pg_cron');
  END LOOP;
END;
$$;


--
-- Name: FUNCTION settle_builder_stock_marketplace_eligibility_tick(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.settle_builder_stock_marketplace_eligibility_tick() IS 'Drives builder-stock-image-settler at a FIXED small concurrency and unschedules its cron job when no work of any kind remains. All three settlement markers are compared against their targets, the extractor version included — see the migration header for what testing that one with IS NULL cost.';


--
-- Name: settle_builder_stock_source_images_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_builder_stock_source_images_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_outstanding integer;
BEGIN
  SELECT count(*) INTO v_outstanding
    FROM public.builder_stock_uploads
   WHERE deleted_at IS NULL
     AND source_images_settled_version IS NULL;

  IF v_outstanding = 0 THEN
    IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'settle-builder-stock-source-images') THEN
      PERFORM cron.unschedule('settle-builder-stock-source-images');
    END IF;
    RETURN;
  END IF;

  PERFORM public.cron_invoke_signed_function(
    'builder-stock-image-settler', '{}'::jsonb, 'pg_cron');
END;
$$;


--
-- Name: FUNCTION settle_builder_stock_source_images_tick(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.settle_builder_stock_source_images_tick() IS 'One tick of the Builder Stock image settlement deployment repair. Invokes builder-stock-image-settler while any upload is unsettled, then unschedules its own cron job. Restricted to postgres/service_role.';


