--
-- Name: builder_document_scan_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.builder_document_scan_health AS
 SELECT count(*) FILTER (WHERE (malware_scan_status = 'pending'::text)) AS pending,
    count(*) FILTER (WHERE (malware_scan_status = 'scanning'::text)) AS scanning,
    count(*) FILTER (WHERE (malware_scan_status = 'clean'::text)) AS clean,
    count(*) FILTER (WHERE (malware_scan_status = 'infected'::text)) AS infected,
    count(*) FILTER (WHERE (malware_scan_status = 'error'::text)) AS errored,
    count(*) FILTER (WHERE ((malware_scan_status = ANY (ARRAY['pending'::text, 'scanning'::text])) AND (created_at < (now() - '01:00:00'::interval)))) AS stuck_over_1h,
    ( SELECT count(*) AS count
           FROM public.document_processing_jobs
          WHERE ((document_processing_jobs.portal = 'builder'::text) AND (document_processing_jobs.status = 'failed'::text) AND (document_processing_jobs.attempts >= 5))) AS dead_lettered
   FROM public.builder_document_versions v;


--
-- Name: VIEW builder_document_scan_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.builder_document_scan_health IS 'Builder document scanning health. stuck_over_1h and dead_lettered are the signals that the processor is not running or the scanner is unreachable.';


