    CONSTRAINT builder_portal_sessions_ip_hash_check CHECK (((ip_hash IS NULL) OR (ip_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT builder_portal_sessions_revocation_reason CHECK (((revoked_at IS NULL) OR (revoked_reason IS NOT NULL))),
    CONSTRAINT builder_portal_sessions_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT builder_portal_sessions_user_agent_hash_check CHECK (((user_agent_hash IS NULL) OR (user_agent_hash ~ '^[0-9a-f]{64}$'::text)))
);


--
-- Name: TABLE builder_portal_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_portal_sessions IS 'Builder Portal sessions. Separate from solicitor_portal_sessions: no shared row, no shared cookie, no shared resolver. Only SHA-256 token hashes are stored; raw tokens never reach the database.';


--
-- Name: COLUMN builder_portal_sessions.token_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_portal_sessions.token_hash IS 'SHA-256 hex digest of the session token. The raw token lives only in the HttpOnly __Host-builder_session_token cookie.';


--
-- Name: COLUMN builder_portal_sessions.active_organisation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_portal_sessions.active_organisation_id IS 'Server-held active organisation for this session. Only set through builder_select_session_organisation(), which re-verifies membership. Never trusted from the browser.';


