    CONSTRAINT builder_stock_item_images_source_stage_check CHECK ((source_stage = ANY (ARRAY['uploaded_document'::text, 'google_maps'::text, 'internet_search'::text]))),
    CONSTRAINT builder_stock_item_images_verification_status_check CHECK ((verification_status = ANY (ARRAY['source_supplied'::text, 'location_derived'::text, 'unverified'::text, 'property_identity_verified'::text])))
);


