--
-- Name: builder_stock_settlement_target; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_stock_settlement_target (
    id boolean DEFAULT true NOT NULL,
    marketplace_eligibility_version integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    image_sanitization_version integer DEFAULT 0 NOT NULL,
    image_ladder_generation_at timestamp with time zone,
    image_runtime_version integer DEFAULT 0 NOT NULL,
    source_images_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT builder_stock_settlement_target_id_check CHECK (id)
);


--
-- Name: TABLE builder_stock_settlement_target; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_stock_settlement_target IS 'The Builder Stock display-eligibility version production is being brought to. Exactly one row. Raised by set_builder_stock_eligibility_target() in the same deployment as a MARKETPLACE_ELIGIBILITY_VERSION bump; an upload whose marketplace_eligibility_settled_version is below it has a re-audit outstanding.';


--
-- Name: COLUMN builder_stock_settlement_target.image_sanitization_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_settlement_target.image_sanitization_version IS 'The Builder Stock overlay-removal version production is being brought to. Raised by set_builder_stock_sanitization_target() in the same deployment as a SANITIZATION_VERSION bump.';


--
-- Name: COLUMN builder_stock_settlement_target.image_ladder_generation_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_settlement_target.image_ladder_generation_at IS 'When the image ladder last changed what it is capable of. A settled property with no picture whose own conclusion predates this is re-opened exactly once. Raise it — SET image_ladder_generation_at = now() — in the migration that ships any change to what a stage can find, refuse or retry.';


--
-- Name: COLUMN builder_stock_settlement_target.image_runtime_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_settlement_target.image_runtime_version IS 'How reliably the worker can OPEN a document — distinct from what the extractor understands. Raising it reopens properties whose branches failed because WE could not process them, and nothing else. Must equal RUNTIME_VERSION in runtimeVersion.pure.ts.';


--
-- Name: COLUMN builder_stock_settlement_target.source_images_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_settlement_target.source_images_version IS 'The extractor version (PROVENANCE_VERSION) uploads must have been re-read under. An upload whose source_images_settled_version is below this has provenance work outstanding. Raised only by set_builder_stock_source_images_target, which also re-schedules the sweep.';


--
-- Name: builder_stock_uploads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.builder_stock_uploads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organisation_id uuid NOT NULL,
    uploaded_by_builder_user_id uuid,
    original_filename text NOT NULL,
    declared_content_type text,
    detected_content_type text,
    byte_size bigint,
    file_sha256 text,
    storage_bucket text DEFAULT 'builder-stock-lists'::text NOT NULL,
    storage_path text NOT NULL,
    status text DEFAULT 'uploaded'::text NOT NULL,
    parse_strategy text,
    records_detected integer DEFAULT 0 NOT NULL,
    records_imported integer DEFAULT 0 NOT NULL,
    records_updated integer DEFAULT 0 NOT NULL,
    records_failed integer DEFAULT 0 NOT NULL,
    image_stage_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_code text,
    error_message text,
    error_detail jsonb,
    processing_started_at timestamp with time zone,
    processing_completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_type text DEFAULT 'file'::text NOT NULL,
    source_url text,
    final_url text,
    source_title text,
    retrieved_at timestamp with time zone,
    deleted_at timestamp with time zone,
    deleted_by_builder_user_id uuid,
    source_images_settled_version integer,
    marketplace_eligibility_settled_version integer,
    image_sanitization_settled_version integer,
    replaces_upload_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    published_at timestamp with time zone,
    CONSTRAINT builder_stock_uploads_byte_size_check CHECK (((byte_size IS NULL) OR (byte_size >= 0))),
    CONSTRAINT builder_stock_uploads_original_filename_check CHECK ((length(btrim(original_filename)) > 0)),
    CONSTRAINT builder_stock_uploads_source_type_check CHECK ((source_type = ANY (ARRAY['file'::text, 'url'::text]))),
    CONSTRAINT builder_stock_uploads_status_check CHECK ((status = ANY (ARRAY['uploaded'::text, 'parsing'::text, 'imported'::text, 'enriching'::text, 'complete'::text, 'partially_complete'::text, 'failed'::text]))),
    CONSTRAINT builder_stock_uploads_url_source_has_a_url CHECK (((source_type <> 'url'::text) OR (source_url IS NOT NULL)))
);


--
-- Name: TABLE builder_stock_uploads; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.builder_stock_uploads IS 'One row per stock-list file a builder uploaded. The audit record of the import: who, what file, how many records, which stages succeeded.';


--
-- Name: COLUMN builder_stock_uploads.error_detail; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_uploads.error_detail IS 'Internal diagnosis. Never returned to a Builder Portal or Command Centre caller — error_message is the safe surface.';


--
-- Name: COLUMN builder_stock_uploads.source_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_uploads.source_type IS 'file = the builder uploaded bytes; url = the server fetched them. Both end in the same extraction, normalisation and import path.';


--
-- Name: COLUMN builder_stock_uploads.final_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_uploads.final_url IS 'The URL the fetch settled on after redirects, each of which was SSRF-checked. Never the URL the browser claimed.';


--
-- Name: COLUMN builder_stock_uploads.deleted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_uploads.deleted_at IS 'The builder removed this source. The row stays: stock it created and selections made against that stock still reference it.';


--
-- Name: COLUMN builder_stock_uploads.source_images_settled_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_uploads.source_images_settled_version IS 'The image-provenance version this upload''s imagery was last re-derived under (see PROVENANCE_VERSION in _shared/builderStock/sourceImages.ts). NULL or below the current version means the source has not been read under the current primary-image rules and the settler will read it once. Written only by a COMPLETE settlement pass, so a run that hit its wall clock is never mistaken for a finished one.';


--
-- Name: COLUMN builder_stock_uploads.marketplace_eligibility_settled_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_uploads.marketplace_eligibility_settled_version IS 'The marketplace display-eligibility version this upload''s primary images were last assessed under (see MARKETPLACE_ELIGIBILITY_VERSION in _shared/builderStock/marketplaceEligibility.pure.ts). NULL or below the current version means its images have not been judged under the current rules and the settler will judge them once. Deliberately independent of source_images_settled_version: the two versions move for different reasons. Written only by a COMPLETE pass, so a run that hit its wall clock is never mistaken for a finished one.';


--
-- Name: COLUMN builder_stock_uploads.image_sanitization_settled_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.builder_stock_uploads.image_sanitization_settled_version IS 'The overlay-removal version this upload''s images have been through. Below builder_stock_settlement_target.image_sanitization_version means a sweep is outstanding. Independent of the provenance and display-eligibility markers: a better repair must not re-fetch sources, and a better classifier must not re-run repairs.';


