--
-- Name: workspace_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    builder_organisation_id uuid NOT NULL,
    state text DEFAULT 'invited'::text NOT NULL,
    initiated_by text NOT NULL,
    invite_code_hash text,
    invite_expires_at timestamp with time zone,
    outbound_hmac_secret text,
    accepted_at timestamp with time zone,
    revoked_at timestamp with time zone,
    revoke_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_connections_check CHECK (((state <> 'revoked'::text) OR (revoked_at IS NOT NULL))),
    CONSTRAINT workspace_connections_check1 CHECK (((state <> 'active'::text) OR (accepted_at IS NOT NULL))),
    CONSTRAINT workspace_connections_initiated_by_check CHECK ((initiated_by = ANY (ARRAY['workspace'::text, 'builder'::text]))),
    CONSTRAINT workspace_connections_state_check CHECK ((state = ANY (ARRAY['invited'::text, 'active'::text, 'revoked'::text])))
);


--
-- Name: workspace_registry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_registry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    mc_clone_id uuid NOT NULL,
    slug text NOT NULL,
    display_name text,
    last_asserted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


