--
-- Name: TRIGGER builder_stock_items_rearm_settlement ON builder_stock_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TRIGGER builder_stock_items_rearm_settlement ON public.builder_stock_items IS 'Re-arms the settlement cron job whenever image work is queued — on a new property (INSERT) and on a re-read, a supplied render or a recovered link (UPDATE of enrichment_status / image_work_stage). Statement level; the function it calls is idempotent.';


